INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12371, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b500861d-662e-47de-9e4a-8fcaf08db021') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12371, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指话语或语言具有某种神秘力量，能影响现实，常用于虚构作品。", "primary_collocate": null, "pronunciation": "yán líng", "ipa": "jɛn˧˥ liŋ˧˥", "syllable_count": 2, "sentences": [{"text": "叙事因此成为一种“言灵”式的存在——语言不仅描述世界，更建构现实。", "target_word": "言灵", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "这部小说里的魔法师靠言灵打败了敌人。", "target_word": "言灵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这个故事里，言灵能让说出口的话变成现实。", "target_word": "言灵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "主角不小心说错话，言灵就让灾难发生了。", "target_word": "言灵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "动画里的少女用言灵保护了整座城市。", "target_word": "言灵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "作者把言灵写成一种古老的力量。", "target_word": "言灵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位作家喜欢在小说中使用言灵的设定。", "target_word": "言灵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在漫画里，言灵的力量会随着说话人的心情变化。", "target_word": "言灵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "故事中的王子被言灵困住，只能说真话。", "target_word": "言灵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本奇幻小说里的言灵，来自古代的传说。", "target_word": "言灵", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "言靈", "label": "繁体"}], "register": "书面", "sense_fingerprint": "虚构作品中能改变现实的话语神秘力量", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f278538-1681-45dd-833e-5419567a1254') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12371, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "言灵", "is_correct": true, "explanation": "“言灵”指话语的神秘力量，与“语言不仅描述世界，更建构现实”的语境相合。"}, {"text": "石像", "is_correct": false, "explanation": "语义：石像不能“建构现实”，与句中强调语言的作用不符。"}, {"text": "图画", "is_correct": false, "explanation": "语义：图画不是语言，与“语言不仅描述世界”的语境冲突。"}, {"text": "岩石", "is_correct": false, "explanation": "搭配：“建构现实”的主语应是语言，“岩石”与“建构”搭配不当。"}], "explanations": {"言灵": "“言灵”指话语的神秘力量，与“语言不仅描述世界，更建构现实”的语境相合。", "石像": "语义：石像不能“建构现实”，与句中强调语言的作用不符。", "图画": "语义：图画不是语言，与“语言不仅描述世界”的语境冲突。", "岩石": "搭配：“建构现实”的主语应是语言，“岩石”与“建构”搭配不当。"}, "sentence_index": 0, "correct_answer": "言灵"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "远处传来一阵奇怪的言灵，像是有人在哭。", "explanation": "这里应该用〈声音〉。言灵指话语的神秘力量，不是耳朵能听见的声音。"}, {"text": "言灵过得很快，转眼就到了年底。", "explanation": "这里应该用〈时间〉。言灵指话语的神秘力量，不是流逝的时间，不能说“过得很快”。"}, {"text": "他郑重地立下言灵，要永远守护家人。", "explanation": "这里应该用〈誓言〉。言灵指话语的神秘力量，不是立下的承诺。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b500861d-662e-47de-9e4a-8fcaf08db021') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12371, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "言灵", "is_correct": true, "explanation": "“言灵”指话语的神秘力量，可以作为小说中的设定，与句意相符。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：“设定”指故事中的规则或概念，“桌子”是家具，不能作为设定。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：“使用……的设定”要求概念性的对象，“石头”不能用作设定。"}, {"text": "饭菜", "is_correct": false, "explanation": "语义：饭菜是食物，不能作为小说中的设定。"}], "explanations": {"言灵": "“言灵”指话语的神秘力量，可以作为小说中的设定，与句意相符。", "桌子": "语义：“设定”指故事中的规则或概念，“桌子”是家具，不能作为设定。", "石头": "搭配：“使用……的设定”要求概念性的对象，“石头”不能用作设定。", "饭菜": "语义：饭菜是食物，不能作为小说中的设定。"}, "sentence_index": 6, "correct_answer": "言灵"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "人们向言灵祈祷，希望天下太平。", "explanation": "这里应该用〈神灵〉。言灵指话语的神秘力量，不是有意志的神灵，不能向它祈祷。"}, {"text": "村里突然来了一个言灵，吓坏了大家。", "explanation": "这里应该用〈妖怪〉。言灵指话语的力量，不是会行动的生物。"}, {"text": "他从包里拿出一件言灵，递给了朋友。", "explanation": "这里应该用〈法宝〉。言灵是话语的力量，不是可以拿在手里的物件。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b500861d-662e-47de-9e4a-8fcaf08db021') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12371, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "书里提到一只言灵，它来自古代。", "corrected_sentence": "书里提到一种言灵，它来自古代。", "error_description": "量词错误：“言灵”是抽象的力量，量词应用“种”，不能用“只”（“只”多用于动物或成对的物品）。正确说法是“一种言灵”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b500861d-662e-47de-9e4a-8fcaf08db021') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12371, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位作家写了一个很有趣言灵设定。", "corrected_sentence": "这位作家写了一个很有趣的言灵设定。", "error_description": "漏掉“的”：“很有趣”修饰“言灵设定”时中间要加“的”。正确说法是“很有趣的言灵设定”，漏掉“的”不成句。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b500861d-662e-47de-9e4a-8fcaf08db021') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12374, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b500861d-662e-47de-9e4a-8fcaf08db021') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12374, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b500861d-662e-47de-9e4a-8fcaf08db021') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12374, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "叙述或讲述某件事的人。", "primary_collocate": null, "pronunciation": "jiǎng shù zhě", "ipa": "tɕjɑŋ˨˩˦ ʂu˥˩ ʈʂɤ˨˩˦", "syllable_count": 3, "sentences": [{"text": "与书写文本的固化不同，每一次讲述都是对传统的再创造，讲述者根据当下语境、听众构成与社会需求，对情节进行增删或重构。", "target_word": "讲述者", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这个故事的讲述者是一位老渔民。", "target_word": "讲述者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的讲述者会用声音吸引听众。", "target_word": "讲述者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影里的讲述者一直没有出现在画面中。", "target_word": "讲述者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "讲述者慢慢说起了四十年前的往事。", "target_word": "讲述者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小说用孩子做讲述者，读起来很亲切。", "target_word": "讲述者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位讲述者记得每一个细节。", "target_word": "讲述者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "作为讲述者，他把事故经过说得很清楚。", "target_word": "讲述者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书中的讲述者不是作者，而是一只猫。", "target_word": "讲述者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "广播剧请来一位声音好听的讲述者。", "target_word": "讲述者", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "講述者", "label": "繁体"}], "register": "中性", "sense_fingerprint": "叙述故事或事件的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f278538-1681-45dd-833e-5419567a1254') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12374, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "讲述者", "is_correct": true, "explanation": "正确：讲述者是每次讲述时根据语境增删情节的人，与句中的“讲述”呼应。"}, {"text": "书写者", "is_correct": false, "explanation": "语义：书写者面对的是固定的文本，与“每一次讲述都是再创造”的对比相矛盾。"}, {"text": "文本", "is_correct": false, "explanation": "搭配：文本本身不能“根据语境”主动增删情节，这里需要有判断能力的行为者。"}, {"text": "观众", "is_correct": false, "explanation": "语义：句中已把“听众构成”列为另一方，观众不能同时成为增删情节的人。"}], "explanations": {"讲述者": "正确：讲述者是每次讲述时根据语境增删情节的人，与句中的“讲述”呼应。", "书写者": "语义：书写者面对的是固定的文本，与“每一次讲述都是再创造”的对比相矛盾。", "文本": "搭配：文本本身不能“根据语境”主动增删情节，这里需要有判断能力的行为者。", "观众": "语义：句中已把“听众构成”列为另一方，观众不能同时成为增删情节的人。"}, "sentence_index": 0, "correct_answer": "讲述者"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家工厂的讲述者每天负责焊接钢板。", "explanation": "这里应该用〈焊工〉。讲述者指叙述故事或事件的人，负责焊接钢板的是焊工，不能用“讲述者”。"}, {"text": "这位讲述者每天在菜市场卖菜。", "explanation": "这里应该用〈菜贩〉。讲述者指叙述故事或事件的人，每天在菜市场卖菜的是菜贩，不能用“讲述者”。"}, {"text": "台下坐满了讲述者，大家都安静地听着。", "explanation": "这里应该用〈听众〉。讲述者是讲述故事的人，安静坐着听的是听众。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b500861d-662e-47de-9e4a-8fcaf08db021') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12374, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "讲述者", "is_correct": true, "explanation": "正确：讲述者是讲述经历并能记得细节的人，“这位”用于指人。"}, {"text": "失忆者", "is_correct": false, "explanation": "语义：失忆者记不住事情，与“记得每一个细节”直接矛盾。"}, {"text": "作品", "is_correct": false, "explanation": "搭配：“作品”不是人，不能用“这位”计数，也不会“记得”细节。"}, {"text": "日记", "is_correct": false, "explanation": "搭配：日记是物件，不能用“这位”修饰，也不会“记得”。"}], "explanations": {"讲述者": "正确：讲述者是讲述经历并能记得细节的人，“这位”用于指人。", "失忆者": "语义：失忆者记不住事情，与“记得每一个细节”直接矛盾。", "作品": "搭配：“作品”不是人，不能用“这位”计数，也不会“记得”细节。", "日记": "搭配：日记是物件，不能用“这位”修饰，也不会“记得”。"}, "sentence_index": 6, "correct_answer": "讲述者"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们请了一位讲述者帮忙修理电脑。", "explanation": "这里应该用〈维修员〉。讲述者指叙述故事或事件的人，修理电脑的是维修员，不能用“讲述者”。"}, {"text": "会上，讲述者对这个问题发表了自己的看法。", "explanation": "这里应该用〈发言人〉。讲述者指讲述故事或事件的人，对问题发表看法要用发言人。"}, {"text": "这位讲述者正在田里插秧。", "explanation": "这里应该用〈农民〉。讲述者指叙述故事或事件的人，在田里插秧的是农民，不能用“讲述者”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b500861d-662e-47de-9e4a-8fcaf08db021') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12374, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "节目请来一只讲述者，他很会讲故事。", "corrected_sentence": "节目请来一位讲述者，他很会讲故事。", "error_description": "错误在量词：讲述者指人，应用“位”或“个”，不能用“只”。正确说法是“一位讲述者”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b500861d-662e-47de-9e4a-8fcaf08db021') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12374, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个节目需要一位好的讲述者们。", "corrected_sentence": "这个节目需要一位好的讲述者。", "error_description": "错误在复数标记：“一位”表示单数，后面不能再加“们”，应说“一位好的讲述者”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b500861d-662e-47de-9e4a-8fcaf08db021') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12375, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b500861d-662e-47de-9e4a-8fcaf08db021') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12375, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b500861d-662e-47de-9e4a-8fcaf08db021') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12375, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "听演讲、广播、音乐等的人。", "primary_collocate": null, "pronunciation": "tīng zhòng", "ipa": "tʰiŋ˥ ʈʂʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "与书写文本的固化不同，每一次讲述都是对传统的再创造，讲述者根据当下语境、听众构成与社会需求，对情节进行增删或重构。", "target_word": "听众", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "演讲结束后，听众热烈地鼓掌。", "target_word": "听众", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个电台节目有很多年轻听众。", "target_word": "听众", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "音乐会上，听众都安静地听着。", "target_word": "听众", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听众打来电话，说想听一首老歌。", "target_word": "听众", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的演讲让听众笑了好几次。", "target_word": "听众", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "广播里说，听众可以发短信参加活动。", "target_word": "听众", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "台下坐着三百多位听众。", "target_word": "听众", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "歌手唱完后，听众还不想离开。", "target_word": "听众", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位主持人很了解自己的听众。", "target_word": "听众", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "聽眾", "label": "繁体"}, {"form": "听众席", "label": "复合"}], "register": "中性", "sense_fingerprint": "听演讲、广播或音乐的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f278538-1681-45dd-833e-5419567a1254') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12375, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "听众", "is_correct": true, "explanation": "正确：听众是听演讲、广播、音乐的人，与讲述者相对，是讲述所面向的对象。"}, {"text": "温度", "is_correct": false, "explanation": "语义：温度不是人群，无法与“社会需求”一起构成讲述的对象。"}, {"text": "海洋", "is_correct": false, "explanation": "语义：海洋不能接受讲述，“构成”一词要求人或群体。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“听众构成”搭配的是人群，天气不能作为这里的主体。"}], "explanations": {"听众": "正确：听众是听演讲、广播、音乐的人，与讲述者相对，是讲述所面向的对象。", "温度": "语义：温度不是人群，无法与“社会需求”一起构成讲述的对象。", "海洋": "语义：海洋不能接受讲述，“构成”一词要求人或群体。", "天气": "搭配：“听众构成”搭配的是人群，天气不能作为这里的主体。"}, "sentence_index": 0, "correct_answer": "听众"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "电影院里坐满了听众。", "explanation": "这里应该用〈观众〉。听众指听演讲、广播、音乐的人，在电影院看电影的是观众。"}, {"text": "这本小说的听众很多。", "explanation": "这里应该用〈读者〉。听众指听的人，阅读小说的是读者。"}, {"text": "电台的听众每天早上播新闻。", "explanation": "这里应该用〈播音员〉。听众指听广播的人，每天早上播新闻的是播音员，不能用“听众”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b500861d-662e-47de-9e4a-8fcaf08db021') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12375, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "听众", "is_correct": true, "explanation": "正确：听众是收听广播、能发短信参加活动的人。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不能收听广播，也不能发短信。"}, {"text": "空调", "is_correct": false, "explanation": "语义：空调是机器，不会发短信参加活动。"}, {"text": "玻璃", "is_correct": false, "explanation": "搭配：“参加活动”的主语须是有行为能力的人，玻璃不能作主语。"}], "explanations": {"听众": "正确：听众是收听广播、能发短信参加活动的人。", "石头": "语义：石头不能收听广播，也不能发短信。", "空调": "语义：空调是机器，不会发短信参加活动。", "玻璃": "搭配：“参加活动”的主语须是有行为能力的人，玻璃不能作主语。"}, "sentence_index": 6, "correct_answer": "听众"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今天的球场上，两万名听众正在踢球。", "explanation": "这里应该用〈球员〉。听众指听演讲、广播、音乐的人，正在踢球的是球员，不能用“听众”。"}, {"text": "公交车上的听众很多。", "explanation": "这里应该用〈乘客〉。听众指听讲话或音乐的人，坐公交车的是乘客。"}, {"text": "婚礼上，听众宣布仪式正式开始。", "explanation": "这里应该用〈司仪〉。听众是听讲话或音乐的人，宣布仪式开始的是司仪。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b500861d-662e-47de-9e4a-8fcaf08db021') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12375, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这场演唱会来了一只听众，他想听老歌。", "corrected_sentence": "这场演唱会来了一位听众，他想听老歌。", "error_description": "错误在量词：听众指人，应用“位”或“个”，不能用“只”。正确说法是“一位听众”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b500861d-662e-47de-9e4a-8fcaf08db021') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12375, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个节目里来了三台听众，很热闹。", "corrected_sentence": "这个节目里来了三位听众，很热闹。", "error_description": "错误在量词：听众指人，应用“位”或“个”，不能用“台”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b500861d-662e-47de-9e4a-8fcaf08db021') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
