INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12376, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51b02fcb-c6ae-4f20-8356-50f5f4438809') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12376, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "社会或群体对某种事物、服务或行为的需要。", "primary_collocate": null, "pronunciation": "xū qiú", "ipa": "ɕy˥˥ tɕʰjoʊ˧˥", "syllable_count": 2, "sentences": [{"text": "人们对文化娱乐的需求越来越大。", "target_word": "需求", "complexity_tier": "T3", "furigana": "rén men duì wén huà yú lè de xū qiú yuè lái yuè dà.", "sentence_source": "generated"}, {"text": "城市对公共文化服务的需求很大。", "target_word": "需求", "complexity_tier": "T3", "furigana": "chéng shì duì gōng gòng wén huà fú wù de xū qiú hěn dà.", "sentence_source": "generated"}, {"text": "节假日里，人们对文化演出的需求突然变大。", "target_word": "需求", "complexity_tier": "T3", "furigana": "jié jià rì lǐ, rén men duì wén huà yǎn chū de xū qiú tū rán biàn dà.", "sentence_source": "generated"}, {"text": "现在的年轻人对文化活动的需求越来越多。", "target_word": "需求", "complexity_tier": "T3", "furigana": "xiàn zài de nián qīng rén duì wén huà huó dòng de xū qiú yuè lái yuè duō.", "sentence_source": "generated"}, {"text": "文化市场的需求变小，剧团只好少演出一些。", "target_word": "需求", "complexity_tier": "T3", "furigana": "wén huà shì chǎng de xū qiú biàn xiǎo, jù tuán zhǐ hǎo shǎo yǎn chū yì xiē.", "sentence_source": "generated"}, {"text": "社区根据居民的文化需求，建了一个小图书室。", "target_word": "需求", "complexity_tier": "T3", "furigana": "shè qū gēn jù jū mín de wén huà xū qiú, jiàn le yí gè xiǎo tú shū shì.", "sentence_source": "generated"}, {"text": "现在纸质书的需求没有以前大。", "target_word": "需求", "complexity_tier": "T3", "furigana": "xiàn zài zhǐ zhì shū de xū qiú méi yǒu yǐ qián dà.", "sentence_source": "generated"}, {"text": "这场音乐会满足了观众对艺术的需求。", "target_word": "需求", "complexity_tier": "T3", "furigana": "zhè chǎng yīn yuè huì mǎn zú le guān zhòng duì yì shù de xū qiú.", "sentence_source": "generated"}, {"text": "旅游旺季，人们对文化展览的需求特别大。", "target_word": "需求", "complexity_tier": "T3", "furigana": "lǚ yóu wàng jì, rén men duì wén huà zhǎn lǎn de xū qiú tè bié dà.", "sentence_source": "generated"}, {"text": "农村对文化书籍的需求一直很大。", "target_word": "需求", "complexity_tier": "T3", "furigana": "nóng cūn duì wén huà shū jí de xū qiú yì zhí hěn dà.", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "市场需求", "label": "复合"}], "register": "中性", "sense_fingerprint": "社会或群体对某种事物、服务或行为的总体需要", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a949716a-af53-4c71-8fd0-9a695ad86cc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12376, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "身高", "is_correct": false, "explanation": "体貌：身高是人的体征，不是人对文化娱乐的需要，“对文化娱乐的身高越来越大”说不通。"}, {"text": "需求", "is_correct": true, "explanation": "正确：“对文化娱乐的需求”指社会或个人对文化娱乐的需要，“越来越大”描述需要的程度，搭配自然。"}, {"text": "门票", "is_correct": false, "explanation": "语义：门票是一种凭证，不能成为人对文化娱乐的需要，句子没有合理的意思。"}, {"text": "时间", "is_correct": false, "explanation": "搭配：“越来越大”不用来形容时间，时间的增减应说“越来越多”或“越来越长”。"}], "explanations": {"身高": "体貌：身高是人的体征，不是人对文化娱乐的需要，“对文化娱乐的身高越来越大”说不通。", "需求": "正确：“对文化娱乐的需求”指社会或个人对文化娱乐的需要，“越来越大”描述需要的程度，搭配自然。", "门票": "语义：门票是一种凭证，不能成为人对文化娱乐的需要，句子没有合理的意思。", "时间": "搭配：“越来越大”不用来形容时间，时间的增减应说“越来越多”或“越来越长”。"}, "sentence_index": 0, "correct_answer": "需求"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学校对学生的需求很严格。", "explanation": "这里应该用〈要求〉。“严格”形容对人或事的规定与标准，说“对学生的要求很严格”；“需求”不能说严格。"}, {"text": "他的需求是当一名医生。", "explanation": "这里应该用〈梦想〉。“梦想”指心中向往的理想，“需求”指社会或个人必须具备的东西，不能用来表示职业理想。"}, {"text": "这个社区有一只很大的需求。", "explanation": "这里应该用“种”。“只”用于动物或成对的东西，不能用来计量抽象的“需求”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51b02fcb-c6ae-4f20-8356-50f5f4438809') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12376, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "作者", "is_correct": false, "explanation": "语义：作者是人，不能说大小，“纸质书的作者没有以前大”说不通。"}, {"text": "需求", "is_correct": true, "explanation": "正确：“纸质书的需求没有以前大”指人们对纸质书的需要量变小，搭配自然。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：价格用“高”或“低”来形容，不说“没有以前大”。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不能比较大小，“纸质书的颜色没有以前大”不成立。"}], "explanations": {"作者": "语义：作者是人，不能说大小，“纸质书的作者没有以前大”说不通。", "需求": "正确：“纸质书的需求没有以前大”指人们对纸质书的需要量变小，搭配自然。", "价格": "搭配：价格用“高”或“低”来形容，不说“没有以前大”。", "颜色": "语义：颜色不能比较大小，“纸质书的颜色没有以前大”不成立。"}, "sentence_index": 6, "correct_answer": "需求"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "农村需求更多的文化书籍。", "explanation": "这里应该用〈需要〉。“需求”是名词，不能直接带动词宾语“更多的文化书籍”；“需要”是动词，可以直接带宾语。"}, {"text": "社区需求组织一场文化讲座。", "explanation": "这里应该用〈打算〉。“打算”是动词，可以带动词宾语“组织一场文化讲座”；“需求”是名词，不能直接带动词宾语。"}, {"text": "农村有一条很大的需求。", "explanation": "这里应该用“种”。“条”用于长条形的东西，不能用来计量抽象的“需求”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51b02fcb-c6ae-4f20-8356-50f5f4438809') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12376, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "社会对文化服务的一只需求正在增长。", "corrected_sentence": "社会对文化服务的需求正在增长。", "error_description": "错误在“一只需求”。“需求”是抽象名词，不能用“只”计量；应去掉数量词，或者用“种”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51b02fcb-c6ae-4f20-8356-50f5f4438809') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12376, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "农村对电子书的一朵需求一直很大。", "corrected_sentence": "农村对电子书的需求一直很大。", "error_description": "错误在“一朵需求”。“朵”用于花朵等，不能用来计量抽象的“需求”；应去掉数量词，直接说“需求”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51b02fcb-c6ae-4f20-8356-50f5f4438809') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12377, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51b02fcb-c6ae-4f20-8356-50f5f4438809') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
