INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12377, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事情发展的经过或故事中的事件。", "primary_collocate": null, "pronunciation": "qíng jié", "ipa": "tɕʰiŋ˧˥ tɕjɛ˧˥", "syllable_count": 2, "sentences": [{"text": "与书写文本的固化不同，每一次讲述都是对传统的再创造，讲述者根据当下语境、听众构成与社会需求，对情节进行增删或重构。", "target_word": "情节", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这部电影的情节很复杂，我看了两遍才懂。", "target_word": "情节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法官要先了解案件的情节，再做决定。", "target_word": "情节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把事情的情节一点一点讲给大家听。", "target_word": "情节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本小说的情节发展得很快。", "target_word": "情节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察问他事情的情节，他说得很清楚。", "target_word": "情节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事的情节很复杂，必须仔细调查。", "target_word": "情节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶讲的故事，情节简单，孩子们都爱听。", "target_word": "情节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你按时间顺序说一下事情的情节。", "target_word": "情节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们把课文的情节写成短文。", "target_word": "情节", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "段", "label": "量词"}, {"form": "情節", "label": "繁体"}], "register": "中性", "sense_fingerprint": "事情发展的经过，或故事里的一个个事件", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a949716a-af53-4c71-8fd0-9a695ad86cc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12377, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "身高", "is_correct": false, "explanation": "体貌：身高是人的体征，不是讲述中可以增删或重构的内容，“对身高进行增删”说不通。"}, {"text": "情节", "is_correct": true, "explanation": "正确：“对情节进行增删或重构”指对事件的具体经过做改动，与前文的讲述语境搭配。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不属于讲述的内容，不能被“增删或重构”。"}, {"text": "门票", "is_correct": false, "explanation": "语义：门票是凭证，不是讲述的内容，“对门票进行增删或重构”没有意义。"}], "explanations": {"身高": "体貌：身高是人的体征，不是讲述中可以增删或重构的内容，“对身高进行增删”说不通。", "情节": "正确：“对情节进行增删或重构”指对事件的具体经过做改动，与前文的讲述语境搭配。", "颜色": "语义：颜色不属于讲述的内容，不能被“增删或重构”。", "门票": "语义：门票是凭证，不是讲述的内容，“对门票进行增删或重构”没有意义。"}, "sentence_index": 0, "correct_answer": "情节"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "做这道菜的情节很简单，十分钟就学会了。", "explanation": "这里应该用〈步骤〉。“步骤”指做事的先后环节，做菜、操作多说“步骤”；“情节”只用于故事或事件的经过。"}, {"text": "这个实验的情节很简单，三步就完成了。", "explanation": "这里应该用〈过程〉。“过程”指事物发展变化的阶段，实验、生产多说“过程”；“情节”用于故事或事件的具体经过。"}, {"text": "这本小说有一块很精彩的情节。", "explanation": "这里应该用“段”或“个”。“块”用于块状或片状的东西，不能用来计量“情节”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51b02fcb-c6ae-4f20-8356-50f5f4438809') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12377, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "价格", "is_correct": false, "explanation": "搭配：“复杂”不修饰价格，价格应用“高”或“低”来形容。"}, {"text": "情节", "is_correct": true, "explanation": "正确：“这件事的情节很复杂”指事件的具体经过较繁复，需要仔细调查，搭配自然。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是事情的组成部分，“这件事的天气”说不通。"}, {"text": "体重", "is_correct": false, "explanation": "体貌：体重是人的体征，不能用于事情，“这件事的体重”不成立。"}], "explanations": {"价格": "搭配：“复杂”不修饰价格，价格应用“高”或“低”来形容。", "情节": "正确：“这件事的情节很复杂”指事件的具体经过较繁复，需要仔细调查，搭配自然。", "天气": "语义：天气不是事情的组成部分，“这件事的天气”说不通。", "体重": "体貌：体重是人的体征，不能用于事情，“这件事的体重”不成立。"}, "sentence_index": 6, "correct_answer": "情节"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个软件的安装情节很简单，几步就完成了。", "explanation": "这里应该用〈程序〉。“程序”指按步骤进行的操作流程，软件安装用“程序”；“情节”只指故事或事件的具体经过。"}, {"text": "这次演出的情节非常壮观。", "explanation": "这里应该用〈场面〉。“壮观”形容场景和画面，“情节”不能用“壮观”来形容。"}, {"text": "这部小说有一束很有趣的情节。", "explanation": "这里应该用“段”或“个”。“束”多用于花、光线等成束的东西，不能用来计量“情节”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51b02fcb-c6ae-4f20-8356-50f5f4438809') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12377, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这部小说的一朵情节很曲折，我一口气读完了。", "corrected_sentence": "这部小说的情节很曲折，我一口气读完了。", "error_description": "错误在“一朵情节”。“朵”用于花朵等，不能用来计量“情节”；应说“一段”或“一个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51b02fcb-c6ae-4f20-8356-50f5f4438809') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12377, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这部电影的一幅情节几乎一样，我看了两遍才发现。", "corrected_sentence": "这部电影的情节几乎一样，我看了两遍才发现。", "error_description": "错误在“一幅情节”。“幅”用于画、布等平面作品，不能用来计量抽象的“情节”；应去掉数量词，直接说“情节”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51b02fcb-c6ae-4f20-8356-50f5f4438809') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
