INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12378, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指增加和删减，即对内容、项目等进行添加或移除的操作。", "primary_collocate": null, "pronunciation": "zēng shān", "ipa": "tsəŋ˥˥ ʂan˥˥", "syllable_count": 2, "sentences": [{"text": "与书写文本的固化不同，每一次讲述都是对传统的再创造，讲述者根据当下语境、听众构成与社会需求，对情节进行增删或重构。", "target_word": "增删", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "写完文章后，我又增删了几个句子。", "target_word": "增删", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "编辑会增删稿子里的一些内容。", "target_word": "增删", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份计划还要增删几个项目。", "target_word": "增删", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你可以随时增删名单上的名字。", "target_word": "增删", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你增删一下这篇作文的内容。", "target_word": "增删", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把旧书的内容增删了一遍，重新出版。", "target_word": "增删", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个软件可以增删联系人。", "target_word": "增删", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "翻译时，我们常常要增删一些词。", "target_word": "增删", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "导演增删了剧本里的几场戏。", "target_word": "增删", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "增删了", "label": "体标"}, {"form": "增删过", "label": "体标"}, {"form": "增刪", "label": "繁体"}], "register": "书面", "sense_fingerprint": "对内容、项目等添加或删去的操作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a949716a-af53-4c71-8fd0-9a695ad86cc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12378, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "拆除", "is_correct": false, "explanation": "搭配：“拆除”用于建筑、障碍物等实体，不能用于情节，“对情节进行拆除”不成立。"}, {"text": "增删", "is_correct": true, "explanation": "“增删”指对内容进行添加或删去，与“对情节进行增删或重构”搭配，符合句意。"}, {"text": "安装", "is_correct": false, "explanation": "搭配：“安装”用于设备、器材，不能用于情节，句子说的是改动内容。"}, {"text": "翻译", "is_correct": false, "explanation": "语义：“翻译”指转换语言，这里是在同一文本内改动情节，与句意不符。"}], "explanations": {"拆除": "搭配：“拆除”用于建筑、障碍物等实体，不能用于情节，“对情节进行拆除”不成立。", "增删": "“增删”指对内容进行添加或删去，与“对情节进行增删或重构”搭配，符合句意。", "安装": "搭配：“安装”用于设备、器材，不能用于情节，句子说的是改动内容。", "翻译": "语义：“翻译”指转换语言，这里是在同一文本内改动情节，与句意不符。"}, "sentence_index": 0, "correct_answer": "增删"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个月我的身高增删了三厘米。", "explanation": "这里应该用〈增长〉。增删指对内容、项目等进行加减，身高的变化应说增长或长高。"}, {"text": "工人增删了那条断裂的路。", "explanation": "这里应该用〈修复〉。增删用于内容、项目、名单等，断裂的道路要修复，不能增删。"}, {"text": "这家商店的面积增删了一倍。", "explanation": "这里应该用〈扩大〉。增删强调具体项目的加与删，面积变大要用扩大。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51b02fcb-c6ae-4f20-8356-50f5f4438809') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12378, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "出售", "is_correct": false, "explanation": "语义：“出售”是卖出，句子说的是修改旧书的内容，不是卖书。"}, {"text": "装订", "is_correct": false, "explanation": "搭配：“装订”针对纸张、书页，不能与“内容”搭配。"}, {"text": "增删", "is_correct": true, "explanation": "“增删”指对内容进行添加或删去，“把旧书的内容增删了一遍”符合句意。"}, {"text": "切割", "is_correct": false, "explanation": "搭配：“切割”用于切开实体材料，内容不能切割。"}], "explanations": {"出售": "语义：“出售”是卖出，句子说的是修改旧书的内容，不是卖书。", "装订": "搭配：“装订”针对纸张、书页，不能与“内容”搭配。", "增删": "“增删”指对内容进行添加或删去，“把旧书的内容增删了一遍”符合句意。", "切割": "搭配：“切割”用于切开实体材料，内容不能切割。"}, "sentence_index": 6, "correct_answer": "增删"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件事给生活增删了许多乐趣。", "explanation": "这里应该用〈增添〉。增删针对可以逐项加减的项目，乐趣只能说增添。"}, {"text": "医生增删了病人的感冒。", "explanation": "这里应该用〈治疗〉。增删用于内容、项目，感冒只能治疗，不能增删。"}, {"text": "他增删了厨房。", "explanation": "这里应该用〈清洁〉。增删针对内容和项目，厨房要清洁，不能说增删。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51b02fcb-c6ae-4f20-8356-50f5f4438809') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12378, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他又增删了了两段文字。", "corrected_sentence": "他又增删了两段文字。", "error_description": "错误在“了了”。动词后只用一个“了”表示动作完成，重复的“了”不通；正确为“又增删了两段文字”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51b02fcb-c6ae-4f20-8356-50f5f4438809') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12378, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师又增删把两道题。", "corrected_sentence": "老师又增删了两道题。", "error_description": "错误在“增删把两道题”。“了”表示动作完成，应说“增删了两道题”；“把”不能直接放在动词后引出宾语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51b02fcb-c6ae-4f20-8356-50f5f4438809') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12382, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51b02fcb-c6ae-4f20-8356-50f5f4438809') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12382, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51b02fcb-c6ae-4f20-8356-50f5f4438809') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12382, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "指事物持续不间断的性质或状态。", "primary_collocate": null, "pronunciation": "lián xù xìng", "ipa": "ljɛn˧˥ ɕy˥˩ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "这种“变异中的存续”机制，使文化核心得以在形式变迁中维持精神连续性。", "target_word": "连续性", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "红绿灯太多，影响了这条路的连续性。", "target_word": "连续性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "睡眠的连续性对身体很重要。", "target_word": "连续性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这部电影的故事缺少连续性，看不懂。", "target_word": "连续性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，学习要有连续性，不能三天打鱼两天晒网。", "target_word": "连续性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "数据的连续性很好，中间一天也没有少。", "target_word": "连续性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "思路一断，工作的连续性就没有了。", "target_word": "连续性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这段视频的连续性不好，画面总是跳。", "target_word": "连续性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了保证生产的连续性，工厂二十四小时开机。", "target_word": "连续性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了保证供水的连续性，水厂全年不停地运转。", "target_word": "连续性", "complexity_tier": "T3", "furigana": "wèi le bǎo zhèng gōng shuǐ de lián xù xìng, shuǐ chǎng quán nián bú tíng de yùn zhuǎn.", "sentence_source": "generated"}], "morphological_forms": [{"form": "連續性", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "事物持续不间断的性质", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a949716a-af53-4c71-8fd0-9a695ad86cc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12382, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "物理性", "is_correct": false, "explanation": "语义：“物理性”指物质的物理特征，与“精神”的延续意义不符。"}, {"text": "化学性", "is_correct": false, "explanation": "搭配：“精神”不能与“化学性”搭配，句子说的是精神层面的延续。"}, {"text": "连续性", "is_correct": true, "explanation": "“连续性”指不间断地延续，“维持精神连续性”符合句意。"}, {"text": "生理性", "is_correct": false, "explanation": "语义：“生理性”指身体的机能特征，与文化精神的延续无关。"}], "explanations": {"物理性": "语义：“物理性”指物质的物理特征，与“精神”的延续意义不符。", "化学性": "搭配：“精神”不能与“化学性”搭配，句子说的是精神层面的延续。", "连续性": "“连续性”指不间断地延续，“维持精神连续性”符合句意。", "生理性": "语义：“生理性”指身体的机能特征，与文化精神的延续无关。"}, "sentence_index": 0, "correct_answer": "连续性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这种涂料的连续性很好，用了好几年颜色都没变。", "explanation": "这里应该用〈持久性〉。连续性指事情不间断，涂料强调耐用、经久，要用持久性。"}, {"text": "这种金属的连续性很强，导电性能很好。", "explanation": "这里应该用〈导电性〉。连续性指不间断，金属导电能力要说导电性。"}, {"text": "这盏灯的连续性很高，照得很亮。", "explanation": "这里应该用〈亮度〉。连续性指不间断，灯的明亮程度要说亮度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51b02fcb-c6ae-4f20-8356-50f5f4438809') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12382, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”指色彩，工作不具有颜色，“工作的颜色就没有了”不通。"}, {"text": "硬度", "is_correct": false, "explanation": "搭配：“硬度”用于材料、物体，不能说工作的硬度。"}, {"text": "连续性", "is_correct": true, "explanation": "“连续性”指工作不间断，“思路一断，工作的连续性就没有了”符合句意。"}, {"text": "形状", "is_correct": false, "explanation": "语义：“形状”指物体的外形，工作没有形状，与句意不符。"}], "explanations": {"颜色": "语义：“颜色”指色彩，工作不具有颜色，“工作的颜色就没有了”不通。", "硬度": "搭配：“硬度”用于材料、物体，不能说工作的硬度。", "连续性": "“连续性”指工作不间断，“思路一断，工作的连续性就没有了”符合句意。", "形状": "语义：“形状”指物体的外形，工作没有形状，与句意不符。"}, "sentence_index": 6, "correct_answer": "连续性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台仪器的连续性很高，测量结果很准。", "explanation": "这里应该用〈精确性〉。连续性指不间断，仪器测量的准确程度要说精确性。"}, {"text": "这块面料的连续性很好，穿着很舒服。", "explanation": "这里应该用〈柔软性〉。连续性指不间断，面料穿着舒服要说柔软性。"}, {"text": "这条毛巾的连续性很强，擦身体很快干。", "explanation": "这里应该用〈吸水性〉。连续性指不间断，毛巾擦干身体靠的是吸水性。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51b02fcb-c6ae-4f20-8356-50f5f4438809') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12382, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条河的水流连续性好很。", "corrected_sentence": "这条河的水流连续性很好。", "error_description": "“很”应放在形容词“好”前，修饰“好”；正确为“连续性很好”，“连续性好很”语序错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51b02fcb-c6ae-4f20-8356-50f5f4438809') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12382, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这份报告地连续性很强，前后衔接得很好。", "corrected_sentence": "这份报告的连续性很强，前后衔接得很好。", "error_description": "定语标记应用“的”，不能用“地”；正确为“报告的连续性很强”，“报告地连续性很强”错误。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51b02fcb-c6ae-4f20-8356-50f5f4438809') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
