INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12389, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指季节或特定的时间阶段。", "primary_collocate": null, "pronunciation": "shí jié", "ipa": "ʂɻ̩˧˥ tɕjɛ˧˥", "syllable_count": 2, "sentences": [{"text": "例如，在非洲部分部落，同一则英雄传说在战时会被强调勇气与牺牲，在丰收时节则突出与自然的和谐共生——历史由此成为可被调用的意义资源，而非僵化的事实档案。", "target_word": "时节", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "清明时节，南方常常下雨。", "target_word": "时节", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "秋收时节，农民们在田里忙着收稻子。", "target_word": "时节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每到春耕时节，村里的人都起得很早。", "target_word": "时节", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个时节，山上的花开得最好。", "target_word": "时节", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在多雨的时节，出门最好带一把伞。", "target_word": "时节", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "桂花开放的时节，满城都是香味。", "target_word": "时节", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "冬天是最冷的时节，大家都穿上了厚衣服。", "target_word": "时节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "麦子成熟的时节，田野一片金黄。", "target_word": "时节", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在寒冷的时节里，这种花依然开着。", "target_word": "时节", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "時節", "label": "繁体"}], "register": "中性", "sense_fingerprint": "时节：季节或特定的时间阶段，如丰收时节、清明时节", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8cc17b9-de67-4efd-85c9-5c806de33319') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12389, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "时节", "is_correct": true, "explanation": "时节（shí jié）指季节或特定的时间阶段，是本题的目标词。"}, {"text": "诗节", "is_correct": false, "explanation": "第一音节 shī（第一声）与 shí（第二声）只差声调，意思是诗歌的段落。"}, {"text": "石阶", "is_correct": false, "explanation": "第二音节 jiē（第一声）与 jié（第二声）只差声调，意思是台阶。"}, {"text": "十届", "is_correct": false, "explanation": "第二音节 jiè（第四声）与 jié（第二声）只差声调，意思是第十届。"}, {"text": "十级", "is_correct": false, "explanation": "第二音节 jí 与 jié 声调相同，韵母不同（i 与 ie），意思是十级。"}], "explanations": {"时节": "时节（shí jié）指季节或特定的时间阶段，是本题的目标词。", "诗节": "第一音节 shī（第一声）与 shí（第二声）只差声调，意思是诗歌的段落。", "石阶": "第二音节 jiē（第一声）与 jié（第二声）只差声调，意思是台阶。", "十届": "第二音节 jiè（第四声）与 jié（第二声）只差声调，意思是第十届。", "十级": "第二音节 jí 与 jié 声调相同，韵母不同（i 与 ie），意思是十级。"}, "sentence_index": null, "correct_answer": "时节"}, "level_3": {"options": [{"text": "时节", "is_correct": true, "explanation": "正确：“时节”指特定时段，与前文的“战时”并列，只有它能填入空格。"}, {"text": "田地", "is_correct": false, "explanation": "语义：“田地”指土地，不表示时段，不能与“战时”并列。"}, {"text": "人群", "is_correct": false, "explanation": "语义：“人群”指人，不指时段，不能作为“丰收”所限定的时间。"}, {"text": "节奏", "is_correct": false, "explanation": "搭配：“丰收节奏”不成搭配，“节奏”指快慢的规律，不表示时段。"}], "explanations": {"时节": "正确：“时节”指特定时段，与前文的“战时”并列，只有它能填入空格。", "田地": "语义：“田地”指土地，不表示时段，不能与“战时”并列。", "人群": "语义：“人群”指人，不指时段，不能作为“丰收”所限定的时间。", "节奏": "搭配：“丰收节奏”不成搭配，“节奏”指快慢的规律，不表示时段。"}, "sentence_index": 0, "correct_answer": "时节"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他跑完全程的时节创了新纪录。", "explanation": "这里应该用〈时间〉。跑完全程所用的时长要说“时间”，时节指季节或一段时期。"}, {"text": "火车到站的时节是下午三点。", "explanation": "这里应该用〈时刻〉。时节指季节或较长的时段，不指具体的某个钟点。"}, {"text": "这次会议的时节定在下周三。", "explanation": "这里应该用〈日期〉。时节指季节或一段时期，不指某一天；定下具体哪一天要说“日期”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a434e14f-6618-43bc-9ff2-5ede03d72089') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12389, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "时节", "is_correct": true, "explanation": "时节（shí jié）指季节或特定的时间阶段，是本题的目标词。"}, {"text": "世界", "is_correct": false, "explanation": "两个音节都只差声调：shì（第四声）对 shí（第二声），jiè（第四声）对 jié（第二声），意思是世界。"}, {"text": "十戒", "is_correct": false, "explanation": "第二音节 jiè（第四声）与 jié（第二声）只差声调，意思是十条戒律。"}, {"text": "失节", "is_correct": false, "explanation": "第一音节 shī（第一声）与 shí（第二声）只差声调，意思是丧失节操。"}, {"text": "诗界", "is_correct": false, "explanation": "两个音节都只差声调：shī（第一声）对 shí（第二声），jiè（第四声）对 jié（第二声），意思是诗歌界。"}], "explanations": {"时节": "时节（shí jié）指季节或特定的时间阶段，是本题的目标词。", "世界": "两个音节都只差声调：shì（第四声）对 shí（第二声），jiè（第四声）对 jié（第二声），意思是世界。", "十戒": "第二音节 jiè（第四声）与 jié（第二声）只差声调，意思是十条戒律。", "失节": "第一音节 shī（第一声）与 shí（第二声）只差声调，意思是丧失节操。", "诗界": "两个音节都只差声调：shī（第一声）对 shí（第二声），jiè（第四声）对 jié（第二声），意思是诗歌界。"}, "sentence_index": null, "correct_answer": "时节"}, "level_3": {"options": [{"text": "时节", "is_correct": true, "explanation": "正确：“时节”指季节，与“桂花开放”相合，“满城都是香味”也符合季节语境。"}, {"text": "空间", "is_correct": false, "explanation": "语义：“空间”指范围，不表示季节或时段，与“桂花开放”的时间语境不符。"}, {"text": "角落", "is_correct": false, "explanation": "语义：“角落”指局部位置，与“满城都是香味”的整体范围相矛盾。"}, {"text": "时辰", "is_correct": false, "explanation": "语域：“时辰”是古代的计时单位，书面化，不用于描述桂花开放的季节。"}], "explanations": {"时节": "正确：“时节”指季节，与“桂花开放”相合，“满城都是香味”也符合季节语境。", "空间": "语义：“空间”指范围，不表示季节或时段，与“桂花开放”的时间语境不符。", "角落": "语义：“角落”指局部位置，与“满城都是香味”的整体范围相矛盾。", "时辰": "语域：“时辰”是古代的计时单位，书面化，不用于描述桂花开放的季节。"}, "sentence_index": 6, "correct_answer": "时节"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "公司第三时节的利润增加了。", "explanation": "这里应该用〈季度〉。时节不与“第三”这样的序数搭配来表示第几个季度。"}, {"text": "这项工作要花很多时节。", "explanation": "这里应该用〈时间〉。时节指季节或特定时段，不能像时间那样用“很多”来计量时长。"}, {"text": "我的手机上的时节总是不准。", "explanation": "这里应该用〈时钟〉。时节指季节或一段时间，不指计时的钟表；说手机的计时不准要用“时钟”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a434e14f-6618-43bc-9ff2-5ede03d72089') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12389, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是一只美好的时节，适合出去散步。", "corrected_sentence": "这是一个美好的时节，适合出去散步。", "error_description": "量词错误：“时节”前应用“个”，不能用“只”（“只”多用于动物或单件小物）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a434e14f-6618-43bc-9ff2-5ede03d72089') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12389, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "在春天的时节上，树叶依然绿着。", "corrected_sentence": "在春天的时节里，树叶依然绿着。", "error_description": "方位词错误：“时节”是时间段，表示范围内应用“里”，“时节上”不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a434e14f-6618-43bc-9ff2-5ede03d72089') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
