INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12391, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指计算机程序中执行某个子程序或函数，也指调配使用。", "primary_collocate": null, "pronunciation": "diào yòng", "ipa": "tjɑʊ̯˥˩ jʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "例如，在非洲部分部落，同一则英雄传说在战时会被强调勇气与牺牲，在丰收时节则突出与自然的和谐共生——历史由此成为可被调用的意义资源，而非僵化的事实档案。", "target_word": "调用", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这个程序会调用一个函数。", "target_word": "调用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们可以在主程序里调用这个子程序。", "target_word": "调用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "调用函数前，要先写好它。", "target_word": "调用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "手机应用想调用相机，需要你的同意。", "target_word": "调用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她调用了数据库里的全部资料。", "target_word": "调用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司调用了各部门的人手来完成任务。", "target_word": "调用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "系统每秒调用这个接口上百次。", "target_word": "调用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "消防队调用了几辆消防车来灭火。", "target_word": "调用", "complexity_tier": "T3", "furigana": "xiāo fáng duì diào yòng le jǐ liàng xiāo fáng chē lái miè huǒ。", "sentence_source": "generated"}, {"text": "老师调用了学校的图书资料来备课。", "target_word": "调用", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "调用了", "label": "体标"}, {"form": "调用过", "label": "体标"}, {"form": "調用", "label": "繁体"}], "register": "中性", "sense_fingerprint": "调用：执行子程序或函数；调配使用资源", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8cc17b9-de67-4efd-85c9-5c806de33319') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12391, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "调用", "is_correct": true, "explanation": "调用（diào yòng）指执行子程序，或调配人员、资源，是本题的目标词。"}, {"text": "调运", "is_correct": false, "explanation": "第二音节 yùn 与 yòng 韵母与声调都不同，意思是调运物资。"}, {"text": "调养", "is_correct": false, "explanation": "第二音节 yǎng（第三声）与 yòng（第四声）韵母与声调都不同，意思是调养身体。"}, {"text": "调研", "is_correct": false, "explanation": "第二音节 yán（第二声）与 yòng 韵母与声调都不同，意思是调查研究。"}, {"text": "妙用", "is_correct": false, "explanation": "第一音节 miào 与 diào 只差声母（m 与 d），声调相同，意思是巧妙的用处。"}], "explanations": {"调用": "调用（diào yòng）指执行子程序，或调配人员、资源，是本题的目标词。", "调运": "第二音节 yùn 与 yòng 韵母与声调都不同，意思是调运物资。", "调养": "第二音节 yǎng（第三声）与 yòng（第四声）韵母与声调都不同，意思是调养身体。", "调研": "第二音节 yán（第二声）与 yòng 韵母与声调都不同，意思是调查研究。", "妙用": "第一音节 miào 与 diào 只差声母（m 与 d），声调相同，意思是巧妙的用处。"}, "sentence_index": null, "correct_answer": "调用"}, "level_3": {"options": [{"text": "调用", "is_correct": true, "explanation": "正确：“调用”表示使用，符合“可被调用的意义资源”，只有它能填入空格。"}, {"text": "销毁", "is_correct": false, "explanation": "语义：“销毁”是毁掉，与“成为可用的意义资源”的意思相反。"}, {"text": "颁布", "is_correct": false, "explanation": "搭配：“颁布”用于法令、规章，不能说“可被颁布的意义资源”。"}, {"text": "拆卸", "is_correct": false, "explanation": "搭配：“拆卸”用于机器或零件，不用于抽象的“意义资源”。"}], "explanations": {"调用": "正确：“调用”表示使用，符合“可被调用的意义资源”，只有它能填入空格。", "销毁": "语义：“销毁”是毁掉，与“成为可用的意义资源”的意思相反。", "颁布": "搭配：“颁布”用于法令、规章，不能说“可被颁布的意义资源”。", "拆卸": "搭配：“拆卸”用于机器或零件，不用于抽象的“意义资源”。"}, "sentence_index": 0, "correct_answer": "调用"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我向同学调用了一支笔。", "explanation": "这里应该用〈借〉。调用多指调配人力或系统资源，同学之间借东西要说“借”。"}, {"text": "我从网上调用了这首歌。", "explanation": "这里应该用〈下载〉。调用指执行或调配，不指把网络内容存到自己的设备上。"}, {"text": "他把桌子调用到了客厅。", "explanation": "这里应该用〈搬〉。调用指调配或执行，不用于搬动家具，搬东西要说“搬”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a434e14f-6618-43bc-9ff2-5ede03d72089') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12391, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "调用", "is_correct": true, "explanation": "正确：“调用”表示调配人手，符合“公司……人手来完成任务”的语境，只有它能填入空格。"}, {"text": "解雇", "is_correct": false, "explanation": "语义：“解雇”是辞退员工，与“来完成任务”的调配目的相矛盾。"}, {"text": "盘点", "is_correct": false, "explanation": "语义：“盘点”指清点核对，不表示把人手调来做事。"}, {"text": "出租", "is_correct": false, "explanation": "搭配：“出租”指把物品或房屋有偿给别人使用，不说“出租人手”来完成任务。"}], "explanations": {"调用": "正确：“调用”表示调配人手，符合“公司……人手来完成任务”的语境，只有它能填入空格。", "解雇": "语义：“解雇”是辞退员工，与“来完成任务”的调配目的相矛盾。", "盘点": "语义：“盘点”指清点核对，不表示把人手调来做事。", "出租": "搭配：“出租”指把物品或房屋有偿给别人使用，不说“出租人手”来完成任务。"}, "sentence_index": 6, "correct_answer": "调用"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把邮件调用给了老板。", "explanation": "这里应该用〈发送〉。调用指调配或执行，传递邮件要说“发送”。"}, {"text": "他把重复的文件调用了。", "explanation": "这里应该用〈删除〉。调用不表示去掉，删去文件要说“删除”。"}, {"text": "他在家调用了一只猫。", "explanation": "这里应该用〈养〉。调用用于调配人力、资源或程序，不用于饲养动物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a434e14f-6618-43bc-9ff2-5ede03d72089') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12391, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我以前调用了过这个函数。", "corrected_sentence": "我以前调用过这个函数。", "error_description": "体标重叠：“调用”后不能同时用“了”和“过”；表示曾经做过应只用“过”，即“调用过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a434e14f-6618-43bc-9ff2-5ede03d72089') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12391, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工厂调用了一只机器来生产。", "corrected_sentence": "工厂调用了一台机器来生产。", "error_description": "量词错误：“机器”的量词是“台”，应说“一台机器”，不能用“只”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a434e14f-6618-43bc-9ff2-5ede03d72089') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
