INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12392, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "可用来支持观点或表达意义的文化材料", "primary_collocate": null, "pronunciation": "zī yuán", "ipa": "tsɹ̩˥ ɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "这些老照片是很好的文化资源。", "target_word": "资源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "写文章时，我们需要找一些资源来支持观点。", "target_word": "资源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "博物馆里有丰富的历史资源。", "target_word": "资源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位作家利用民间故事资源表达自己的想法。", "target_word": "资源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他查阅了大量档案资源，用来支持自己的观点。", "target_word": "资源", "complexity_tier": "T3", "furigana": "tā chá yuè le dà liàng dàng àn zī yuán, yòng lái zhī chí zì jǐ de guān diǎn.", "sentence_source": "generated"}, {"text": "老师给我们提供了一些文化资源，用来说明他的看法。", "target_word": "资源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影用了很多传统音乐资源。", "target_word": "资源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要证明这个观点，需要更多历史资源。", "target_word": "资源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那座老城保存着丰富的文化资源。", "target_word": "资源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把家乡的民歌当作写作的资源。", "target_word": "资源", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}], "register": "书面", "sense_fingerprint": "文化、历史、语言等可用于论证或表达的材料", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b62a16e-8257-4aad-9b92-a998a7c9c5ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12392, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "资源", "is_correct": true, "explanation": "正是词目「资源」zī yuán，指可用来支持观点的文化材料。"}, {"text": "支援", "is_correct": false, "explanation": "zhī 与 zī 声母不同（zh/z），意思是支持、援助。"}, {"text": "自愿", "is_correct": false, "explanation": "zì 与 zī 声调不同，yuàn 与 yuán 声调也不同，意思是自己愿意。"}, {"text": "字源", "is_correct": false, "explanation": "zì 与 zī 仅声调不同，意思是汉字的来源。"}], "explanations": {"资源": "正是词目「资源」zī yuán，指可用来支持观点的文化材料。", "支援": "zhī 与 zī 声母不同（zh/z），意思是支持、援助。", "自愿": "zì 与 zī 声调不同，yuàn 与 yuán 声调也不同，意思是自己愿意。", "字源": "zì 与 zī 仅声调不同，意思是汉字的来源。"}, "sentence_index": null, "correct_answer": "资源"}, "level_3": {"options": [{"text": "资源", "is_correct": true, "explanation": "资源：可用来支持观点的文化材料，老照片属于此类，句意通顺。"}, {"text": "资金", "is_correct": false, "explanation": "语义：「资金」指钱款，老照片不是钱款，句意不通。"}, {"text": "资格", "is_correct": false, "explanation": "搭配：「很好的资格」说的是人的条件，不能用来修饰老照片。"}, {"text": "资历", "is_correct": false, "explanation": "搭配：「资历」指人的经历和年资，不能说老照片是「很好的资历」。"}], "explanations": {"资源": "资源：可用来支持观点的文化材料，老照片属于此类，句意通顺。", "资金": "语义：「资金」指钱款，老照片不是钱款，句意不通。", "资格": "搭配：「很好的资格」说的是人的条件，不能用来修饰老照片。", "资历": "搭配：「资历」指人的经历和年资，不能说老照片是「很好的资历」。"}, "sentence_index": 0, "correct_answer": "资源"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座煤矿的资源很丰富，产量很高。", "explanation": "这里的「资源」指可开采的自然物质财富，是另一个义项；本句讨论的是用于论证的文化材料，不指矿产。"}, {"text": "这本书大量引用了资源。", "explanation": "这里应该用〈史料〉。引用的对象是史料、文献等具体材料，「资源」不作引用的对象。"}, {"text": "他找到了一条文化资源。", "explanation": "这里应该用〈种〉。「资源」常用量词是「种」或「项」，「条」用于绳索、河流等长条状事物，不用于此。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da0fcc3e-8d96-4608-aaeb-4aca38e7ff2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12392, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "资源", "is_correct": true, "explanation": "资源：可用来支持观点或表达意义的文化材料，此处指传统音乐素材，句意通顺。"}, {"text": "人口", "is_correct": false, "explanation": "语义：「人口」指人的数量，电影不能「用」人口，句意不通。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是可以被「用」的材料，与「传统音乐」搭配不通。"}, {"text": "资质", "is_correct": false, "explanation": "搭配：「用」可以接「资源」，不接「资质」，「传统音乐资质」不成立。"}], "explanations": {"资源": "资源：可用来支持观点或表达意义的文化材料，此处指传统音乐素材，句意通顺。", "人口": "语义：「人口」指人的数量，电影不能「用」人口，句意不通。", "天气": "语义：天气不是可以被「用」的材料，与「传统音乐」搭配不通。", "资质": "搭配：「用」可以接「资源」，不接「资质」，「传统音乐资质」不成立。"}, "sentence_index": 6, "correct_answer": "资源"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个国家的资源很丰富。", "explanation": "这里的「资源」指自然界或经济上的物质财富，是「资源」的另一个义项，与本句讨论的文化材料不同。"}, {"text": "木头、水和煤都是资源。", "explanation": "这里的「资源」指可开采或利用的物质财富，是另一个义项；本义项指可用于论证的文化材料。"}, {"text": "我们要节约资源，不要浪费。", "explanation": "这里的「资源」指可消耗的物质财富，是另一个义项，不指用来支持观点的文化材料。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da0fcc3e-8d96-4608-aaeb-4aca38e7ff2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12392, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是一本珍贵的文化资源。", "corrected_sentence": "这是一种珍贵的文化资源。", "error_description": "量词错误：「资源」常配量词「种」或「项」，不能用「本」（「本」用于书册）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da0fcc3e-8d96-4608-aaeb-4aca38e7ff2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12392, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师把这些资源们都交给了我们。", "corrected_sentence": "老师把这些资源都交给了我们。", "error_description": "复数标记错误：「们」只用于人，「资源」是非人名词，不能加「们」，应说「这些资源」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da0fcc3e-8d96-4608-aaeb-4aca38e7ff2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12393, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "灵活", "is_correct": true, "explanation": "灵活：不死板、能根据情况变通，与“僵化”构成反义。"}, {"text": "繁荣", "is_correct": false, "explanation": "无关：繁荣指兴旺发达，与僵化没有反义关系。"}, {"text": "明亮", "is_correct": false, "explanation": "无关：明亮形容光线或颜色，与僵化不构成反义。"}, {"text": "辛苦", "is_correct": false, "explanation": "无关：辛苦指劳累，与僵化不是反义关系。"}], "correct_answer": "灵活", "explanations": {"灵活": "灵活：不死板、能根据情况变通，与“僵化”构成反义。", "繁荣": "无关：繁荣指兴旺发达，与僵化没有反义关系。", "明亮": "无关：明亮形容光线或颜色，与僵化不构成反义。", "辛苦": "无关：辛苦指劳累，与僵化不是反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a434e14f-6618-43bc-9ff2-5ede03d72089') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12393, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "灵活", "is_correct": true, "explanation": "灵活：不死板、可以变通，与僵化相对。"}, {"text": "寂静", "is_correct": false, "explanation": "无关：寂静指没有声音，与僵化不构成反义。"}, {"text": "漂浮", "is_correct": false, "explanation": "无关：漂浮指浮在水面或空中，与僵化没有反义关系。"}, {"text": "清澈", "is_correct": false, "explanation": "无关：清澈形容水或眼神干净透明，与僵化不相对。"}], "correct_answer": "灵活", "explanations": {"灵活": "灵活：不死板、可以变通，与僵化相对。", "寂静": "无关：寂静指没有声音，与僵化不构成反义。", "漂浮": "无关：漂浮指浮在水面或空中，与僵化没有反义关系。", "清澈": "无关：清澈形容水或眼神干净透明，与僵化不相对。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a434e14f-6618-43bc-9ff2-5ede03d72089') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12393, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "形容思想、方法等变得死板、不灵活，或事物变得僵硬。", "primary_collocate": null, "pronunciation": "jiāng huà", "ipa": "tɕjɑŋ˥ xu̯ɑ˥˩", "syllable_count": 2, "sentences": [{"text": "例如，在非洲部分部落，同一则英雄传说在战时会被强调勇气与牺牲，在丰收时节则突出与自然的和谐共生——历史由此成为可被调用的意义资源，而非僵化的事实档案。", "target_word": "僵化", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "他的想法已经僵化了。", "target_word": "僵化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "管理方法僵化，公司很难进步。", "target_word": "僵化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师不让思想僵化，常常鼓励我们提问。", "target_word": "僵化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "制度太僵化，年轻人都不愿意留下。", "target_word": "僵化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "教学方式僵化，学生很快就没了兴趣。", "target_word": "僵化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "人老了以后，想法容易变得僵化。", "target_word": "僵化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要多学习，不要让头脑僵化。", "target_word": "僵化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这套规定已经僵化，需要改一改了。", "target_word": "僵化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的工作方法太僵化，不会根据情况调整。", "target_word": "僵化", "complexity_tier": "T3", "furigana": "tā de gōngzuò fāngfǎ tài jiānghuà, bù huì gēnjù qíngkuàng tiáozhěng.", "sentence_source": "generated"}], "morphological_forms": [{"form": "僵化了", "label": "体标"}], "register": "书面", "sense_fingerprint": "僵化：思想、方法、制度变得死板不灵活", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f8cc17b9-de67-4efd-85c9-5c806de33319') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12393, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "僵化", "is_correct": true, "explanation": "僵化（jiānghuà）：思想、方法、制度变得死板、不灵活。"}, {"text": "讲话", "is_correct": false, "explanation": "讲话（jiǎnghuà）第一个音节为第三声，与 jiāng（第一声）声调不同，意思是说话。"}, {"text": "强化", "is_correct": false, "explanation": "强化（qiánghuà）声母为 q，与 j 不同，意思是加强。"}, {"text": "钢化", "is_correct": false, "explanation": "钢化（gānghuà）声母为 g，与 j 不同，意思是经过处理使材料更坚硬。"}, {"text": "姜花", "is_correct": false, "explanation": "姜花（jiānghuā）末字为第一声 huā，与 huà（第四声）声调不同，意思是一种植物。"}], "explanations": {"僵化": "僵化（jiānghuà）：思想、方法、制度变得死板、不灵活。", "讲话": "讲话（jiǎnghuà）第一个音节为第三声，与 jiāng（第一声）声调不同，意思是说话。", "强化": "强化（qiánghuà）声母为 q，与 j 不同，意思是加强。", "钢化": "钢化（gānghuà）声母为 g，与 j 不同，意思是经过处理使材料更坚硬。", "姜花": "姜花（jiānghuā）末字为第一声 huā，与 huà（第四声）声调不同，意思是一种植物。"}, "sentence_index": null, "correct_answer": "僵化"}, "level_3": {"options": [{"text": "僵化", "is_correct": true, "explanation": "僵化：形容思想或制度死板、不灵活，与“可被调用的意义资源”相对，句中说得通。"}, {"text": "欢呼", "is_correct": false, "explanation": "语义：档案只是记录，不会欢呼，“欢呼的事实档案”说不通。"}, {"text": "咆哮", "is_correct": false, "explanation": "搭配：“咆哮”多用于野兽或愤怒的人，不能修饰档案。"}, {"text": "哭泣", "is_correct": false, "explanation": "语义：档案无法哭泣，“哭泣的事实档案”与句意不符。"}], "explanations": {"僵化": "僵化：形容思想或制度死板、不灵活，与“可被调用的意义资源”相对，句中说得通。", "欢呼": "语义：档案只是记录，不会欢呼，“欢呼的事实档案”说不通。", "咆哮": "搭配：“咆哮”多用于野兽或愤怒的人，不能修饰档案。", "哭泣": "语义：档案无法哭泣，“哭泣的事实档案”与句意不符。"}, "sentence_index": 0, "correct_answer": "僵化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这几天的天气很僵化，我们都不敢出门。", "explanation": "这里把〈僵化〉当成〈僵硬〉（变硬、不能动）来形容天气；僵化的本义不适用于天气，天气不会变得死板。"}, {"text": "今天的心情很僵化，一整天都不想说话。", "explanation": "这里把〈僵化〉当成〈僵〉（如「气氛很僵」中紧张、僵持的意思）来形容心情；僵化没有这个义项，心情不会僵化。"}, {"text": "这锅汤的味道很僵化，大家都喝完了。", "explanation": "这里把〈僵化〉当成〈僵硬〉（变硬、不能动）来形容味道；味道不会变硬，僵化不用于描述味觉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a434e14f-6618-43bc-9ff2-5ede03d72089') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12393, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "僵化", "is_correct": true, "explanation": "僵化：说想法随年龄变得固定不变，句中合理。"}, {"text": "肥胖", "is_correct": false, "explanation": "搭配：“肥胖”形容人或动物的体态，不能修饰想法。"}, {"text": "鲜艳", "is_correct": false, "explanation": "搭配：“鲜艳”形容颜色，想法不能说鲜艳。"}, {"text": "融化", "is_correct": false, "explanation": "语义：想法不会融化，“容易融化”与句意不符。"}], "explanations": {"僵化": "僵化：说想法随年龄变得固定不变，句中合理。", "肥胖": "搭配：“肥胖”形容人或动物的体态，不能修饰想法。", "鲜艳": "搭配：“鲜艳”形容颜色，想法不能说鲜艳。", "融化": "语义：想法不会融化，“容易融化”与句意不符。"}, "sentence_index": 6, "correct_answer": "僵化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这盏灯的光很僵化，屋子里很暗。", "explanation": "这里把〈僵化〉当成〈昏暗〉（描写光线的）来用；光线不会变得死板，僵化不能用来形容光。"}, {"text": "这幅画的颜色很僵化，我很喜欢。", "explanation": "这里把〈僵化〉当成〈呆板〉（形容颜色单调）来用；〈呆板〉可以形容颜色，僵化却只用于思想、方法等失去变通的事物。"}, {"text": "这座楼的高度很僵化，一直没有变过。", "explanation": "这里把〈僵化〉当成〈稳定〉（不变）来形容高度；高度是尺寸，不会变得死板，僵化不用于描述尺寸。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a434e14f-6618-43bc-9ff2-5ede03d72089') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12393, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些规定慢慢僵化来了，大家都很不满意。", "corrected_sentence": "这些规定慢慢僵化起来了，大家都很不满意。", "error_description": "错误在补语：表示逐渐变得死板要用趋向补语“起来”，不能只说“僵化来”；正确说法是“僵化起来”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a434e14f-6618-43bc-9ff2-5ede03d72089') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12393, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的想法越来僵化，我们都很担心。", "corrected_sentence": "他的想法越来越僵化，我们都很担心。", "error_description": "语法错误：漏掉了“越”，“越来”后必须接“越”构成固定格式“越来越”，应说“越来越僵化”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a434e14f-6618-43bc-9ff2-5ede03d72089') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
