INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12400, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd80b283-a68c-4a59-830d-1153310a68d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12400, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指返回、回到原来的位置或状态。", "primary_collocate": null, "pronunciation": "huí guī", "ipa": "xweɪ˧˥ kweɪ˥", "syllable_count": 2, "sentences": [{"text": "他离开多年后又回归了家乡。", "target_word": "回归", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多年轻人毕业后选择回归农村。", "target_word": "回归", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "受伤的球星终于回归球队了。", "target_word": "回归", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经过长途旅行，他回归平静的生活。", "target_word": "回归", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "离开一年的老朋友又回归了团队。", "target_word": "回归", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她放下工作，回归家庭。", "target_word": "回归", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位歌手休息三年后回归舞台。", "target_word": "回归", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "假期结束，大家回归校园。", "target_word": "回归", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "病好后，他回归正常的生活。", "target_word": "回归", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "香港于一九九七年回归祖国。", "target_word": "回归", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "回归：动词，回到原来的位置或状态", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57556918-9c49-4ffb-99f3-aee62b027b4c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12400, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "回归", "is_correct": true, "explanation": "正确答案：回归（huí guī），指回到原来的位置或状态。"}, {"text": "回国", "is_correct": false, "explanation": "guó（第二声）与 guī 韵母不同（uo 与 ui），声调也不同，意思是回国（回到自己的国家）。"}, {"text": "回锅", "is_correct": false, "explanation": "guō（第一声）与 guī 韵母不同（uo 与 ui），意思是回锅（食物再次加热）。"}, {"text": "汇归", "is_correct": false, "explanation": "声调混淆：huì（第四声）与 huí（第二声）声调不同，其余音节相同；汇归指水流等汇入某处。"}], "explanations": {"回归": "正确答案：回归（huí guī），指回到原来的位置或状态。", "回国": "guó（第二声）与 guī 韵母不同（uo 与 ui），声调也不同，意思是回国（回到自己的国家）。", "回锅": "guō（第一声）与 guī 韵母不同（uo 与 ui），意思是回锅（食物再次加热）。", "汇归": "声调混淆：huì（第四声）与 huí（第二声）声调不同，其余音节相同；汇归指水流等汇入某处。"}, "sentence_index": null, "correct_answer": "回归"}, "level_3": {"options": [{"text": "回归", "is_correct": true, "explanation": "正确：“回归”指回到原来的地方，与“离开多年后”相呼应。"}, {"text": "诞生", "is_correct": false, "explanation": "配价：“诞生”是不及物动词，不带宾语，不能说“又诞生了家乡”。"}, {"text": "生育", "is_correct": false, "explanation": "搭配：“生育”的对象是子女，不能用于家乡。"}, {"text": "盛行", "is_correct": false, "explanation": "搭配：“盛行”用于风气、习俗、思潮，不能说“又盛行了家乡”。"}], "explanations": {"回归": "正确：“回归”指回到原来的地方，与“离开多年后”相呼应。", "诞生": "配价：“诞生”是不及物动词，不带宾语，不能说“又诞生了家乡”。", "生育": "搭配：“生育”的对象是子女，不能用于家乡。", "盛行": "搭配：“盛行”用于风气、习俗、思潮，不能说“又盛行了家乡”。"}, "sentence_index": 0, "correct_answer": "回归"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这些资料可以回归为三类。", "explanation": "这里应该用〈归纳〉。回归指回到原来的位置或状态，不表示把材料整理归类；把资料按类别整理要用归纳。"}, {"text": "他回归了新的阶段。", "explanation": "这里应该用〈进入〉。回归指回到原来的状态，开启新的阶段应说进入。"}, {"text": "他在北京回归了三天。", "explanation": "这里应该用〈逗留〉。回归表示回到原处，不表示在某地停留多久。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd80b283-a68c-4a59-830d-1153310a68d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12400, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "回归", "is_correct": true, "explanation": "正确：“回归”指回到原来的位置或状态，符合歌手重返舞台的语境。"}, {"text": "替代", "is_correct": false, "explanation": "语义：“替代”要说明替代了谁或什么，“歌手替代舞台”与语境不符。"}, {"text": "降临", "is_correct": false, "explanation": "搭配：“降临”多与夜幕、幸福、灾难等从外而来的事搭配，不用于歌手重返舞台。"}, {"text": "撤离", "is_correct": false, "explanation": "语义：“撤离”指离开某地，与“休息三年后重返舞台”的方向相反。"}], "explanations": {"回归": "正确：“回归”指回到原来的位置或状态，符合歌手重返舞台的语境。", "替代": "语义：“替代”要说明替代了谁或什么，“歌手替代舞台”与语境不符。", "降临": "搭配：“降临”多与夜幕、幸福、灾难等从外而来的事搭配，不用于歌手重返舞台。", "撤离": "语义：“撤离”指离开某地，与“休息三年后重返舞台”的方向相反。"}, "sentence_index": 6, "correct_answer": "回归"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他终于回归了欠款。", "explanation": "这里应该用〈偿还〉。回归指回到原来的位置或状态，不表示还钱；还清欠款要用偿还。"}, {"text": "售货员回归了他找的零钱。", "explanation": "这里应该用〈找回〉。回归指回到原来的位置或状态，不用于收到找零的情形；顾客拿回找零应说找回。"}, {"text": "学生们今天回归了作业。", "explanation": "这里应该用〈交〉。回归指回到原来的位置或状态，作业不会自己回到老师那里；把作业交给老师要用交。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd80b283-a68c-4a59-830d-1153310a68d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12400, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她终于被回归职场。", "corrected_sentence": "她终于回归职场。", "error_description": "错误：“被回归”。“回归”是不及物动词，不能加“被”构成被动句；应说“她终于回归职场”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd80b283-a68c-4a59-830d-1153310a68d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12400, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他终于回归老家来了。", "corrected_sentence": "他终于回归老家了。", "error_description": "错误：“回归……来”。“回归”表示回到原处，不带“来”；“来”属于“回来”，应去掉，说“他终于回归老家了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd80b283-a68c-4a59-830d-1153310a68d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
