INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12401, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一种数字媒体形式，用户可以通过互联网下载或在线收听音频节目。", "primary_collocate": null, "pronunciation": "bō kè", "ipa": "pwo˥ kʰɤ˥˩", "syllable_count": 2, "sentences": [{"text": "在全球化与数字化的当代，尽管书面记录与影像媒介主导了信息传播，口头叙事并未消亡，而是以新的形态回归：播客、口述史项目、非物质文化遗产保护运动，皆可视作对原始交流模式的现代回响。", "target_word": "播客", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "我每天上班路上都听一个英语播客。", "target_word": "播客", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个播客每周更新两次，内容很有意思。", "target_word": "播客", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他做了一个介绍中国文化的播客。", "target_word": "播客", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "很多人喜欢在睡觉前听播客。", "target_word": "播客", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个科技播客有一百多万听众。", "target_word": "播客", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她请了一位作家来播客里聊新书。", "target_word": "播客", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你可以在网上免费下载这个播客。", "target_word": "播客", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想自己做一个关于美食的播客。", "target_word": "播客", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这期播客讲的是怎样学好汉语。", "target_word": "播客", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "期", "label": "量词"}, {"form": "播客节目", "label": "复合"}], "register": "中性", "sense_fingerprint": "播客：可在网上下载或收听的音频节目形式", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40485493-8204-4e56-be10-c71e2455482f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12401, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "播客", "is_correct": true, "explanation": "正确：播客指可以下载或在线收听的音频节目。"}, {"text": "博客", "is_correct": false, "explanation": "“博客”的第一音节是 bó（第二声），与 bō（第一声）声调不同，意思是网络上的个人日志。"}, {"text": "播音", "is_correct": false, "explanation": "“播音”的第二音节是 yīn，与 kè 的声母和韵母都不同，意思是播送声音。"}, {"text": "播报", "is_correct": false, "explanation": "“播报”的第二音节是 bào，与 kè 不同，意思是播送新闻或报道。"}, {"text": "播放", "is_correct": false, "explanation": "“播放”的第二音节是 fàng，与 kè 不同，意思是放送影音内容。"}, {"text": "拨开", "is_correct": false, "explanation": "“拨开”的第二音节是 kāi，与 kè 不同，意思是用手把东西分开。"}, {"text": "播出", "is_correct": false, "explanation": "“播出”的第二音节是 chū，与 kè 不同，意思是把节目播送出去。"}], "explanations": {"播客": "正确：播客指可以下载或在线收听的音频节目。", "博客": "“博客”的第一音节是 bó（第二声），与 bō（第一声）声调不同，意思是网络上的个人日志。", "播音": "“播音”的第二音节是 yīn，与 kè 的声母和韵母都不同，意思是播送声音。", "播报": "“播报”的第二音节是 bào，与 kè 不同，意思是播送新闻或报道。", "播放": "“播放”的第二音节是 fàng，与 kè 不同，意思是放送影音内容。", "拨开": "“拨开”的第二音节是 kāi，与 kè 不同，意思是用手把东西分开。", "播出": "“播出”的第二音节是 chū，与 kè 不同，意思是把节目播送出去。"}, "sentence_index": null, "correct_answer": "播客"}, "level_3": {"options": [{"text": "播客", "is_correct": true, "explanation": "正确：播客指可下载或在线收听的音频节目，这里与口述史项目并列，指口头叙事的新形态。"}, {"text": "报纸", "is_correct": false, "explanation": "语义：报纸属于书面记录和传统媒介，与“口头叙事……以新的形态回归”的意思相反。"}, {"text": "信件", "is_correct": false, "explanation": "语义：信件是书面交流方式，句中强调的是口头叙事的回归，信件不符合这一语境。"}, {"text": "电影", "is_correct": false, "explanation": "语义：电影属于影像媒介，句中说影像媒介主导了信息传播，不是口头叙事的回归。"}], "explanations": {"播客": "正确：播客指可下载或在线收听的音频节目，这里与口述史项目并列，指口头叙事的新形态。", "报纸": "语义：报纸属于书面记录和传统媒介，与“口头叙事……以新的形态回归”的意思相反。", "信件": "语义：信件是书面交流方式，句中强调的是口头叙事的回归，信件不符合这一语境。", "电影": "语义：电影属于影像媒介，句中说影像媒介主导了信息传播，不是口头叙事的回归。"}, "sentence_index": 0, "correct_answer": "播客"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在菜市场买了一个介绍中国文化的播客。", "explanation": "这里应该用〈蔬菜〉。菜市场卖的是蔬菜等实物，播客是可以收听的节目，不能在菜市场买卖。"}, {"text": "他给我寄了一个介绍中国文化的播客。", "explanation": "这里应该用〈链接〉。播客是可以收听的节目，不是实物，不能寄；要寄的是播客的链接。"}, {"text": "他在火车站捡到了一个介绍中国文化的播客。", "explanation": "这里应该用〈钱包〉。捡到的是实物，播客是网上收听的节目，不能在火车站捡到。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5af3f3f-28b9-436c-a853-699974f0110f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12401, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "播客", "is_correct": true, "explanation": "正确：播客指可以下载或在线收听的音频节目。"}, {"text": "拨款", "is_correct": false, "explanation": "“拨款”的第二音节是 kuǎn，与 kè 的韵母和声调都不同，意思是拨给资金。"}, {"text": "菠菜", "is_correct": false, "explanation": "“菠菜”的第二音节是 cài，与 kè 不同，意思是一种蔬菜。"}, {"text": "波浪", "is_correct": false, "explanation": "“波浪”的第二音节是 làng，与 kè 不同，意思是水面起伏的水流。"}, {"text": "播种", "is_correct": false, "explanation": "“播种”的第二音节是 zhǒng，与 kè 不同，意思是把种子撒到土里。"}, {"text": "博客", "is_correct": false, "explanation": "“博客”的第一音节是 bó（第二声），与 bō（第一声）声调不同，意思是网络上的个人日志。"}], "explanations": {"播客": "正确：播客指可以下载或在线收听的音频节目。", "拨款": "“拨款”的第二音节是 kuǎn，与 kè 的韵母和声调都不同，意思是拨给资金。", "菠菜": "“菠菜”的第二音节是 cài，与 kè 不同，意思是一种蔬菜。", "波浪": "“波浪”的第二音节是 làng，与 kè 不同，意思是水面起伏的水流。", "播种": "“播种”的第二音节是 zhǒng，与 kè 不同，意思是把种子撒到土里。", "博客": "“博客”的第一音节是 bó（第二声），与 bō（第一声）声调不同，意思是网络上的个人日志。"}, "sentence_index": null, "correct_answer": "播客"}, "level_3": {"options": [{"text": "播客", "is_correct": true, "explanation": "正确：这里指节目，“来播客里聊”表示作家在播客节目中做客，符合句意。"}, {"text": "信封", "is_correct": false, "explanation": "语义：信封是装信件的纸袋，不能作为聊天新书的场所。"}, {"text": "玻璃杯", "is_correct": false, "explanation": "语义：玻璃杯是盛水的器具，不能用在“来……里聊新书”的结构中。"}, {"text": "大衣", "is_correct": false, "explanation": "搭配：“来……里聊”需要能容纳人的场所，“大衣”不能与“聊”搭配。"}], "explanations": {"播客": "正确：这里指节目，“来播客里聊”表示作家在播客节目中做客，符合句意。", "信封": "语义：信封是装信件的纸袋，不能作为聊天新书的场所。", "玻璃杯": "语义：玻璃杯是盛水的器具，不能用在“来……里聊新书”的结构中。", "大衣": "搭配：“来……里聊”需要能容纳人的场所，“大衣”不能与“聊”搭配。"}, "sentence_index": 6, "correct_answer": "播客"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这期播客被画成了一幅油画。", "explanation": "这里应该用〈油画〉。播客是音频节目，不能被画成画，画出来的是油画这类作品。"}, {"text": "这期播客被挂在客厅墙上当装饰。", "explanation": "这里应该用〈画〉。播客是音频，不能挂在墙上当装饰；能挂在墙上的是画。"}, {"text": "这期播客印在纸上，出版社已经发行。", "explanation": "这里应该用〈文章〉。播客是音频，不能印在纸上；印刷出版的是文章。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5af3f3f-28b9-436c-a853-699974f0110f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12401, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我每天晚上都听一只历史播客。", "corrected_sentence": "我每天晚上都听一个历史播客。", "error_description": "量词错误：“一只历史播客”应改为“一个历史播客”。“只”用于动物等，播客是音频节目，应用量词“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5af3f3f-28b9-436c-a853-699974f0110f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12401, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她在一个英语播客们里学习发音。", "corrected_sentence": "她在一个英语播客里学习发音。", "error_description": "后缀错误：“播客们”应改为“播客”。“们”只用于指人的名词，播客是音频节目，不能加“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5af3f3f-28b9-436c-a853-699974f0110f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12402, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da0fcc3e-8d96-4608-aaeb-4aca38e7ff2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12402, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da0fcc3e-8d96-4608-aaeb-4aca38e7ff2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12402, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指用口头的方式表达，通常与书面表达相对。", "primary_collocate": null, "pronunciation": "kǒu shù", "ipa": "kʰou̯˨˩˦ ʂu˥˩", "syllable_count": 2, "sentences": [{"text": "这些老故事从未被写下来，只能由老人一边回忆，一边口述给年轻人，再由他们整理成册。", "target_word": "口述", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "爷爷眼睛不好，只能口述，让孙女帮他写信。", "target_word": "口述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不会写字，就口述了自己的故事。", "target_word": "口述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师请我们口述一遍昨天看到的事。", "target_word": "口述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生口述病历，护士在电脑上记下来。", "target_word": "口述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份报告不用写，你口述给我听就行。", "target_word": "口述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "作家受伤了，只好口述，由朋友代笔。", "target_word": "口述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把旅行的经历口述给了记者。", "target_word": "口述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶不识字，儿孙们就听她口述老故事。", "target_word": "口述", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会议很重要，秘书一边听领导口述，一边记录。", "target_word": "口述", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "口述了", "label": "体标"}, {"form": "口述过", "label": "体标"}, {"form": "口述史", "label": "复合"}], "register": "中性", "sense_fingerprint": "口述：用口头方式表达，与书面表达相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b62a16e-8257-4aad-9b92-a998a7c9c5ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12402, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "口述", "is_correct": true, "explanation": "正确：「口述」指用口头方式讲述，此句中老人只能凭回忆口讲，与语境相符。"}, {"text": "朗读", "is_correct": false, "explanation": "语义：「朗读」需要照着现成的文字念，而句中故事「从未被写下来」，句意不通。"}, {"text": "书写", "is_correct": false, "explanation": "语义：句中故事「从未被写下来」，且「只能」口讲，「书写」与句意矛盾。"}, {"text": "默写", "is_correct": false, "explanation": "语义：「默写」指凭记忆写出，与句中「只能」口头讲述的语境相反。"}], "explanations": {"口述": "正确：「口述」指用口头方式讲述，此句中老人只能凭回忆口讲，与语境相符。", "朗读": "语义：「朗读」需要照着现成的文字念，而句中故事「从未被写下来」，句意不通。", "书写": "语义：句中故事「从未被写下来」，且「只能」口讲，「书写」与句意矛盾。", "默写": "语义：「默写」指凭记忆写出，与句中「只能」口头讲述的语境相反。"}, "sentence_index": 0, "correct_answer": "口述"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "演员在舞台上口述诗歌。", "explanation": "这里应该用〈朗诵〉。朗诵是有感情地念出已写好的作品，「口述」是用嘴说出自己的话，不用于念现成的诗。"}, {"text": "他没有说话，却口述了整篇论文。", "explanation": "这里应该用〈写〉。「口述」要用嘴说出，而句中说「没有说话」，前后矛盾。"}, {"text": "孩子用粉笔口述了答案。", "explanation": "这里应该用〈写〉。「口述」是用嘴说出，不用粉笔等书写工具，用粉笔应说写。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da0fcc3e-8d96-4608-aaeb-4aca38e7ff2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12402, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "口述", "is_correct": true, "explanation": "口述：用口头方式表达，此句中指作家由朋友代笔、自己口头讲述，句意通顺。"}, {"text": "书写", "is_correct": false, "explanation": "语义：作家受伤无法书写，且句中由朋友代笔，「书写」与句意矛盾。"}, {"text": "誊抄", "is_correct": false, "explanation": "搭配：「誊抄」的对象是已写好的文稿，与「口述」的讲述方式不搭。"}, {"text": "执笔", "is_correct": false, "explanation": "语义：「执笔」指亲自拿笔写，与「受伤了」和「由朋友代笔」矛盾。"}], "explanations": {"口述": "口述：用口头方式表达，此句中指作家由朋友代笔、自己口头讲述，句意通顺。", "书写": "语义：作家受伤无法书写，且句中由朋友代笔，「书写」与句意矛盾。", "誊抄": "搭配：「誊抄」的对象是已写好的文稿，与「口述」的讲述方式不搭。", "执笔": "语义：「执笔」指亲自拿笔写，与「受伤了」和「由朋友代笔」矛盾。"}, "sentence_index": 6, "correct_answer": "口述"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把汽水口述给了妈妈。", "explanation": "这里应该用〈送〉。送是把实物交给别人，「口述」只用于说出话语或内容，汽水是实物，不能用口述转交。"}, {"text": "工人口述了一张桌子。", "explanation": "这里应该用〈做〉。做是造出实物，「口述」只用于说出话语或内容，桌子是实物，不能口述。"}, {"text": "他口述了一辆自行车。", "explanation": "这里应该用〈买〉。买是取得实物，「口述」只用于说出话语或内容，自行车是实物，不能口述。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da0fcc3e-8d96-4608-aaeb-4aca38e7ff2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12402, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她口述非常流利。", "corrected_sentence": "她口述得非常流利。", "error_description": "补语错误：状态补语前要加「得」，应说「口述得非常流利」，不说「口述非常流利」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da0fcc3e-8d96-4608-aaeb-4aca38e7ff2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12402, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他口述了完这个故事。", "corrected_sentence": "他口述完了这个故事。", "error_description": "结果补语错误：结果补语「完」应紧接动词，应说「口述完了」，不说「口述了完」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'da0fcc3e-8d96-4608-aaeb-4aca38e7ff2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
