INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12406, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e4a91d6-71e2-4710-8870-96bbf7f7d5cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12406, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "认为、当作。", "primary_collocate": null, "pronunciation": "shì zuò", "ipa": "ʂɻ̩˥˩ tswo˥˩", "syllable_count": 2, "sentences": [{"text": "在此背景下，城市不再被视作自然的对立面，而是通过技术创新与制度设计，成为可持续性、粮食主权与经济活力协同演进的复杂适应系统。", "target_word": "视作", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "在全球化与数字化的当代，尽管书面记录与影像媒介主导了信息传播，口头叙事并未消亡，而是以新的形态回归：播客、口述史项目、非物质文化遗产保护运动，皆可视作对原始交流模式的现代回响。", "target_word": "视作", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "他把这次失败视作一次机会。", "target_word": "视作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多人把老师视作自己的朋友。", "target_word": "视作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们不能把孩子的问题视作小事。", "target_word": "视作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她一直把这只小狗视作家人。", "target_word": "视作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司把客户的意见视作最重要的参考。", "target_word": "视作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把这座老房子视作家族的记忆。", "target_word": "视作", "complexity_tier": "T3", "furigana": "tā bǎ zhè zuò lǎo fáng zi shì zuò jiā zú de jì yì.", "sentence_source": "generated"}, {"text": "有些人把比赛视作一场战争。", "target_word": "视作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老人把邻居的孩子视作自己的孙子。", "target_word": "视作", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "视作：把某人或某事认为是、当作另一种事物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f775cb0c-f64a-45de-b26d-fcb784c8d131') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12406, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "视作", "is_correct": true, "explanation": "“被视作……”表示被认为是某种事物，符合书面语语境。"}, {"text": "保护", "is_correct": false, "explanation": "语义：“城市被保护自然的对立面”说不通，句意是把城市看作某种事物。"}, {"text": "推翻", "is_correct": false, "explanation": "语义：“推翻”指颠覆，与“城市不再被……”的句意不符。"}, {"text": "等于", "is_correct": false, "explanation": "配价：“等于”不用于被动句，“被等于……”不成立。"}], "explanations": {"视作": "“被视作……”表示被认为是某种事物，符合书面语语境。", "保护": "语义：“城市被保护自然的对立面”说不通，句意是把城市看作某种事物。", "推翻": "语义：“推翻”指颠覆，与“城市不再被……”的句意不符。", "等于": "配价：“等于”不用于被动句，“被等于……”不成立。"}, "sentence_index": 0, "correct_answer": "视作"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把树影视作了人，吓得后退了一步。", "explanation": "这里应该用〈看成〉。“视作”表示有意识地认定，不用于把影子错看成人。"}, {"text": "他把镜子视作窗户，一头撞了上去。", "explanation": "这里应该用〈误认为〉。“视作”是有意识的认定，不用于因看错而把镜子当成窗户的情况。"}, {"text": "我把远处的大石头视作了一个人，吓了一跳。", "explanation": "这里应该用〈误认成〉。“视作”表示有意识地认定，不能表示把石头错看成人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e4a91d6-71e2-4710-8870-96bbf7f7d5cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12406, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "视作", "is_correct": true, "explanation": "“把意见视作参考”表示把意见当作重要的参考，符合句意。"}, {"text": "反映", "is_correct": false, "explanation": "搭配：“反映”的对象是情况或意见，不能接“最重要的参考”。"}, {"text": "编辑", "is_correct": false, "explanation": "语义：“编辑”是修改文字，与“意见视作参考”的句意不符。"}, {"text": "拒绝", "is_correct": false, "explanation": "语义：“拒绝最重要的参考”与“最重要”的评价自相矛盾。"}], "explanations": {"视作": "“把意见视作参考”表示把意见当作重要的参考，符合句意。", "反映": "搭配：“反映”的对象是情况或意见，不能接“最重要的参考”。", "编辑": "语义：“编辑”是修改文字，与“意见视作参考”的句意不符。", "拒绝": "语义：“拒绝最重要的参考”与“最重要”的评价自相矛盾。"}, "sentence_index": 6, "correct_answer": "视作"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她把桌上的水杯视作了花瓶，一不小心碰倒了。", "explanation": "这里应该用〈误认为〉。“视作”是有意识的认定，不用于把水杯错看成花瓶的情况。"}, {"text": "我把路边的垃圾视作了包子，咬了一口。", "explanation": "这里应该用〈错当〉。“视作”不用于把垃圾错当成食物的情况，应说“错当成”。"}, {"text": "我把黑暗中的那只小狗视作了一只猫，走近才看清。", "explanation": "这里应该用〈错当〉。“视作”是有意识的看待，不用于错当的情况。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e4a91d6-71e2-4710-8870-96bbf7f7d5cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12406, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把这次考试视作成一次锻炼的机会。", "corrected_sentence": "他把这次考试视作一次锻炼的机会。", "error_description": "多余的“成”：“视作”后直接接宾语，不用“成”（“当成”才用“成”），应说“视作一次锻炼的机会”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e4a91d6-71e2-4710-8870-96bbf7f7d5cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12406, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们把那位老师视作为榜样。", "corrected_sentence": "我们把那位老师视作榜样。", "error_description": "多余的“为”：“视作”后面直接接宾语，不要加“为”，应说“视作榜样”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e4a91d6-71e2-4710-8870-96bbf7f7d5cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12407, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "否定", "is_correct": true, "explanation": "正确：“否定”与“肯定”构成反义，表示不认可、否认。"}, {"text": "赞美", "is_correct": false, "explanation": "非反义：“赞美”与“肯定”意思相近，属于近义，不构成反义。"}, {"text": "计算", "is_correct": false, "explanation": "非反义：“计算”指算数，与“肯定”无关。"}, {"text": "讨论", "is_correct": false, "explanation": "非反义：“讨论”是交换意见，与“肯定”不构成反义。"}], "correct_answer": "否定", "explanations": {"否定": "正确：“否定”与“肯定”构成反义，表示不认可、否认。", "赞美": "非反义：“赞美”与“肯定”意思相近，属于近义，不构成反义。", "计算": "非反义：“计算”指算数，与“肯定”无关。", "讨论": "非反义：“讨论”是交换意见，与“肯定”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70277f0c-921d-42eb-8929-b89d25e8f429') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12407, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "否定", "is_correct": true, "explanation": "正确：“否定”与“肯定”构成反义，表示不认可、否认。"}, {"text": "同意", "is_correct": false, "explanation": "非反义：“同意”与“肯定”意思相近，属于近义，不构成反义。"}, {"text": "打击", "is_correct": false, "explanation": "非反义：“打击”是使人受挫，与“认可”不是反义关系。"}, {"text": "修改", "is_correct": false, "explanation": "非反义：“修改”指改动，与“肯定”不构成反义。"}], "correct_answer": "否定", "explanations": {"否定": "正确：“否定”与“肯定”构成反义，表示不认可、否认。", "同意": "非反义：“同意”与“肯定”意思相近，属于近义，不构成反义。", "打击": "非反义：“打击”是使人受挫，与“认可”不是反义关系。", "修改": "非反义：“修改”指改动，与“肯定”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70277f0c-921d-42eb-8929-b89d25e8f429') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12407, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "明确表达对某种价值或意义的支持和认可", "primary_collocate": null, "pronunciation": "kěn dìng", "ipa": "kʰən˨˩˦ tiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "老师肯定了我的努力。", "target_word": "肯定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家都肯定他的工作能力。", "target_word": "肯定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经理当面肯定了小王的想法。", "target_word": "肯定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们应该肯定孩子的每一点进步。", "target_word": "肯定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "专家肯定了这个办法。", "target_word": "肯定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈笑着肯定了我的选择。", "target_word": "肯定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从不肯定别人，总是只说缺点。", "target_word": "肯定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司肯定了她这一年的付出。", "target_word": "肯定", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生的话肯定了我们的做法是对的。", "target_word": "肯定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友们都肯定我的决定。", "target_word": "肯定", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "肯定了", "label": "体标"}, {"form": "肯定过", "label": "体标"}], "register": "中性", "sense_fingerprint": "明确认可、赞同某人或某事的价值", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c21dd34c-16ba-43e7-a982-0b6076900aea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12407, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "肯定", "is_correct": true, "explanation": "正确：“肯定了我的努力”表示认可努力的价值，符合语境。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能以“努力”这类抽象名词为宾语。"}, {"text": "偷", "is_correct": false, "explanation": "语义：“偷”是窃取，与老师的正面评价相悖。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”不能与“努力”这类抽象名词搭配作宾语。"}], "explanations": {"肯定": "正确：“肯定了我的努力”表示认可努力的价值，符合语境。", "吃": "搭配：“吃”不能以“努力”这类抽象名词为宾语。", "偷": "语义：“偷”是窃取，与老师的正面评价相悖。", "洗": "搭配：“洗”不能与“努力”这类抽象名词搭配作宾语。"}, "sentence_index": 0, "correct_answer": "肯定"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他肯定了自己的错误。", "explanation": "这里应该用〈承认〉。“肯定”表示认可、赞同，不能用于承认错误。"}, {"text": "他的脸上肯定了笑容。", "explanation": "这里应该用〈露出〉。“肯定”表示认可、赞同，不能用来描述表情。"}, {"text": "这次失败肯定了他的信心。", "explanation": "这里应该用〈打击〉。“肯定”表示认可、支持，不能表示使人受挫。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70277f0c-921d-42eb-8929-b89d25e8f429') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12407, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "肯定", "is_correct": true, "explanation": "正确：“从不肯定别人”指从不认可别人，与“只说缺点”相呼应。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：“煮”的宾语多为食物，不能接“别人”。"}, {"text": "洗澡", "is_correct": false, "explanation": "配价：“洗澡”是不及物动词，后面不能直接带“别人”作宾语。"}, {"text": "理发", "is_correct": false, "explanation": "配价：“理发”是离合词，不能直接带“别人”作宾语，需说“为别人理发”。"}], "explanations": {"肯定": "正确：“从不肯定别人”指从不认可别人，与“只说缺点”相呼应。", "煮": "搭配：“煮”的宾语多为食物，不能接“别人”。", "洗澡": "配价：“洗澡”是不及物动词，后面不能直接带“别人”作宾语。", "理发": "配价：“理发”是离合词，不能直接带“别人”作宾语，需说“为别人理发”。"}, "sentence_index": 6, "correct_answer": "肯定"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师肯定了我的错误。", "explanation": "这里应该用〈批评〉。“肯定”表示认可，不能用来指出错误。"}, {"text": "这盘菜肯定了我的食欲。", "explanation": "这里应该用〈勾起〉。“肯定”表示认可、赞同，不能用于食欲被引发。"}, {"text": "妈妈肯定了我的粗心。", "explanation": "这里应该用〈责备〉。“肯定”表示认可，不能用来指责过失。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70277f0c-921d-42eb-8929-b89d25e8f429') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12407, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "经理肯定了着他的计划。", "corrected_sentence": "经理肯定了他的计划。", "error_description": "体标错误：“了”与“着”不能同时用在同一个动词后，应只用“了”，说“经理肯定了他的计划”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70277f0c-921d-42eb-8929-b89d25e8f429') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12407, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "朋友们都没肯定了我的决定。", "corrected_sentence": "朋友们都没肯定我的决定。", "error_description": "体标错误：“没”表示否定已发生的动作，句中不能再用“了”，应说“没肯定”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '70277f0c-921d-42eb-8929-b89d25e8f429') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
