INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12408, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指亲身在事情发生的地点。", "primary_collocate": null, "pronunciation": "zài chǎng", "ipa": "tsaɪ̯˥˩ ʈʂʰaŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "这些实践重新肯定了身体在场、声音质感与即兴互动所蕴含的认知深度——它们无法被完全转译为文字或数据。", "target_word": "在场", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "事情发生的时候，我正好在场。", "target_word": "在场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "开会时，经理和老师都在场。", "target_word": "在场", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "当时在场的人都听到了他的话。", "target_word": "在场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不在场，所以不知道发生了什么。", "target_word": "在场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件事有很多人在场，可以作证。", "target_word": "在场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "会议开始时，所有人都已经在场了。", "target_word": "在场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "警察问在场的每个人看到了什么。", "target_word": "在场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你在场的话，他就不会生气了。", "target_word": "在场", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子出生时，爸爸一直在场。", "target_word": "在场", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "在场的", "label": "定语形式"}, {"form": "不在场", "label": "否定形式"}, {"form": "在场了", "label": "体标"}], "register": "中性", "sense_fingerprint": "在场：亲身处在事情发生的现场", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40485493-8204-4e56-be10-c71e2455482f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12408, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "在场", "is_correct": true, "explanation": "正确：在场指亲身处于事情发生的现场，符合“身体在场”的说法。"}, {"text": "在唱", "is_correct": false, "explanation": "“在唱”的第二音节是 chàng（第四声），与 chǎng（第三声）声调不同，意思是正在唱歌。"}, {"text": "再长", "is_correct": false, "explanation": "“再长”的第二音节是 zhǎng，与 chǎng 的声母不同（zh 与 ch），意思是继续生长。"}, {"text": "在上", "is_correct": false, "explanation": "“在上”的第二音节是 shàng，与 chǎng 不同，意思是在上面。"}, {"text": "在做", "is_correct": false, "explanation": "“在做”的第二音节是 zuò，与 chǎng 不同，意思是正在做事。"}], "explanations": {"在场": "正确：在场指亲身处于事情发生的现场，符合“身体在场”的说法。", "在唱": "“在唱”的第二音节是 chàng（第四声），与 chǎng（第三声）声调不同，意思是正在唱歌。", "再长": "“再长”的第二音节是 zhǎng，与 chǎng 的声母不同（zh 与 ch），意思是继续生长。", "在上": "“在上”的第二音节是 shàng，与 chǎng 不同，意思是在上面。", "在做": "“在做”的第二音节是 zuò，与 chǎng 不同，意思是正在做事。"}, "sentence_index": null, "correct_answer": "在场"}, "level_3": {"options": [{"text": "在场", "is_correct": true, "explanation": "正确：在场指亲身处于事情发生的地点，这里说“身体在场”，与“肯定”的语境相合。"}, {"text": "缺席", "is_correct": false, "explanation": "语义：“缺席”与“身体在场”的意思相反，与“肯定”的语境相违背。"}, {"text": "回避", "is_correct": false, "explanation": "语义：“回避”与“肯定”相反，身体在场不能被“回避”。"}, {"text": "站立", "is_correct": false, "explanation": "搭配：“身体”后接“在场”表示亲临现场，“站立”不能构成这种搭配。"}], "explanations": {"在场": "正确：在场指亲身处于事情发生的地点，这里说“身体在场”，与“肯定”的语境相合。", "缺席": "语义：“缺席”与“身体在场”的意思相反，与“肯定”的语境相违背。", "回避": "语义：“回避”与“肯定”相反，身体在场不能被“回避”。", "站立": "搭配：“身体”后接“在场”表示亲临现场，“站立”不能构成这种搭配。"}, "sentence_index": 0, "correct_answer": "在场"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那辆自行车也在场，没人注意到它。", "explanation": "这里不能用〈在场〉。在场只用于人，指人亲身处在某地；自行车是物品，应说“停在”。"}, {"text": "那盆花也在场，看着大家吵架。", "explanation": "这里不能用〈在场〉。在场只用于人；花是植物，不能亲身处在现场，应说“摆在”。"}, {"text": "那台电视机在场，播放了整场比赛。", "explanation": "这里不能用〈在场〉。在场只用于人；电视机是设备，不能亲身在场，应说“安装在”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5af3f3f-28b9-436c-a853-699974f0110f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12408, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "在场", "is_correct": true, "explanation": "正确：在场指亲身处于事情发生的现场。"}, {"text": "再说", "is_correct": false, "explanation": "“再说”的第二音节是 shuō，与 chǎng 不同，意思是之后再讲。"}, {"text": "在家", "is_correct": false, "explanation": "“在家”的第二音节是 jiā，与 chǎng 不同，意思是待在家里。"}, {"text": "在学", "is_correct": false, "explanation": "“在学”的第二音节是 xué，与 chǎng 不同，意思是正在学习。"}, {"text": "在写", "is_correct": false, "explanation": "“在写”的第二音节是 xiě，与 chǎng 不同，意思是正在书写。"}, {"text": "在唱", "is_correct": false, "explanation": "“在唱”的第二音节是 chàng（第四声），与 chǎng（第三声）只差声调，意思是正在唱歌。"}, {"text": "再长", "is_correct": false, "explanation": "“再长”的第二音节是 zhǎng，与 chǎng 只差声母送气与否（zh 与 ch），意思是继续生长。"}], "explanations": {"在场": "正确：在场指亲身处于事情发生的现场。", "再说": "“再说”的第二音节是 shuō，与 chǎng 不同，意思是之后再讲。", "在家": "“在家”的第二音节是 jiā，与 chǎng 不同，意思是待在家里。", "在学": "“在学”的第二音节是 xué，与 chǎng 不同，意思是正在学习。", "在写": "“在写”的第二音节是 xiě，与 chǎng 不同，意思是正在书写。", "在唱": "“在唱”的第二音节是 chàng（第四声），与 chǎng（第三声）只差声调，意思是正在唱歌。", "再长": "“再长”的第二音节是 zhǎng，与 chǎng 只差声母送气与否（zh 与 ch），意思是继续生长。"}, "sentence_index": null, "correct_answer": "在场"}, "level_3": {"options": [{"text": "在场", "is_correct": true, "explanation": "正确：在场指人已经处在会议现场，与“会议开始时，所有人都已经在场了”相合。"}, {"text": "缺席", "is_correct": false, "explanation": "语义：“缺席”与“都已经在场”相反，会议开始时所有人缺席不合句意。"}, {"text": "散场", "is_correct": false, "explanation": "语义：“散场”指活动结束后离开，会议刚开始时不能散场。"}, {"text": "撤离", "is_correct": false, "explanation": "语域：“撤离”偏正式或军事用语，与轻松的会议场景不符。"}], "explanations": {"在场": "正确：在场指人已经处在会议现场，与“会议开始时，所有人都已经在场了”相合。", "缺席": "语义：“缺席”与“都已经在场”相反，会议开始时所有人缺席不合句意。", "散场": "语义：“散场”指活动结束后离开，会议刚开始时不能散场。", "撤离": "语域：“撤离”偏正式或军事用语，与轻松的会议场景不符。"}, "sentence_index": 6, "correct_answer": "在场"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这本书也在场，一直放在桌子上。", "explanation": "这里不能用〈在场〉。在场只用于人，指人亲身处在某地；书是物品，不能亲身在场。"}, {"text": "那把钥匙也在场，躺在门口的地上。", "explanation": "这里不能用〈在场〉。在场只用于人；钥匙是物品，不能亲身在场，应说“躺在”。"}, {"text": "那份合同也在场，签了字就生效了。", "explanation": "这里不能用〈在场〉。在场只用于人；合同是文件，不能亲身在场，应说“放在”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5af3f3f-28b9-436c-a853-699974f0110f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12408, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我父亲那天很在场，目睹了整个过程。", "corrected_sentence": "我父亲那天在场，目睹了整个过程。", "error_description": "副词错误：“很在场”应改为“在场”。“在场”表示人亲身处在事情发生的现场，是不能用程度副词“很”修饰的动词，应直接说“在场”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5af3f3f-28b9-436c-a853-699974f0110f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12408, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "演出的时候，观众们都在场舞台，气氛很热烈。", "corrected_sentence": "演出的时候，观众们都在场，气氛很热烈。", "error_description": "搭配错误：“在场”是不及物动词，不能直接带处所宾语“舞台”，应删去“舞台”，说“都在场”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5af3f3f-28b9-436c-a853-699974f0110f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12409, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5af3f3f-28b9-436c-a853-699974f0110f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12409, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5af3f3f-28b9-436c-a853-699974f0110f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12409, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指物体表面给人的触觉感受或视觉、听觉上的品质。", "primary_collocate": null, "pronunciation": "zhì gǎn", "ipa": "ʈʂɻ̩˥˩ kan˨˩˦", "syllable_count": 2, "sentences": [{"text": "这些实践重新肯定了身体在场、声音质感与即兴互动所蕴含的认知深度——它们无法被完全转译为文字或数据。", "target_word": "质感", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这块布的质感很好，看起来很高级。", "target_word": "质感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张照片的质感很特别，像老电影一样。", "target_word": "质感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "设计师想让这个杯子有玻璃的质感。", "target_word": "质感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "木头家具的质感让房间变得很温暖。", "target_word": "质感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的声音很有质感，听起来很稳。", "target_word": "质感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种墙纸有石头的质感，但是很轻。", "target_word": "质感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件外套没有质感，一点也不高级。", "target_word": "质感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她喜欢有质感的东西，不太爱买便宜货。", "target_word": "质感", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这幅画用了厚厚的颜色，质感特别强。", "target_word": "质感", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "質感", "label": "繁体"}, {"form": "一种质感", "label": "量词"}], "register": "书面", "sense_fingerprint": "物体或声音、画面给人的触觉、视觉、听觉品质感", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '40485493-8204-4e56-be10-c71e2455482f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12409, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "质感", "is_correct": true, "explanation": "「质感」指声音给人的质地感受，与「身体在场」「即兴互动」一起描述这些实践的感官特点，语境吻合。"}, {"text": "价格", "is_correct": false, "explanation": "语义：「价格」指商品的钱数，声音没有价格，接在「声音」后面说不通。"}, {"text": "热量", "is_correct": false, "explanation": "搭配：「声音」一般不和「热量」搭配，句中的语境也不涉及能量。"}, {"text": "面积", "is_correct": false, "explanation": "语义：「面积」指平面的大小，声音没有面积，与「身体在场」「互动」都不协调。"}], "explanations": {"质感": "「质感」指声音给人的质地感受，与「身体在场」「即兴互动」一起描述这些实践的感官特点，语境吻合。", "价格": "语义：「价格」指商品的钱数，声音没有价格，接在「声音」后面说不通。", "热量": "搭配：「声音」一般不和「热量」搭配，句中的语境也不涉及能量。", "面积": "语义：「面积」指平面的大小，声音没有面积，与「身体在场」「互动」都不协调。"}, "sentence_index": 0, "correct_answer": "质感"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个消息的质感很重，大家都很紧张。", "explanation": "这里应该用〈分量〉。「质感」指物体表面的触感或视觉、听觉上的品质，不能用来说消息的重要程度；消息的重要程度要用「分量」。"}, {"text": "这家餐厅的服务态度质感很好，客人都很满意。", "explanation": "这里应该用〈态度〉。「质感」指物体的触感或视觉、听觉品质，不能用来形容人的服务态度；要说“服务态度很好”。"}, {"text": "我对这份工作的质感很好，很有兴趣。", "explanation": "这里应该用〈感觉〉。「质感」指物体的触感或视觉特征，不能用来说人对工作的心理感受。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5af3f3f-28b9-436c-a853-699974f0110f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12409, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "质感", "is_correct": true, "explanation": "「质感」指墙纸表面像石头的触感或外观，与后半句「但是很轻」形成对比，说的正是有石头的样子却很轻。"}, {"text": "寿命", "is_correct": false, "explanation": "语义：「寿命」指生物或物品存在的年限，不能用来形容墙纸表面的特点。"}, {"text": "数量", "is_correct": false, "explanation": "搭配：「数量」指个数多少，不能说「有石头的数量」。"}, {"text": "海拔", "is_correct": false, "explanation": "语义：「海拔」指地面高出海平面的高度，与墙纸和石头的表面特征毫不相干。"}], "explanations": {"质感": "「质感」指墙纸表面像石头的触感或外观，与后半句「但是很轻」形成对比，说的正是有石头的样子却很轻。", "寿命": "语义：「寿命」指生物或物品存在的年限，不能用来形容墙纸表面的特点。", "数量": "搭配：「数量」指个数多少，不能说「有石头的数量」。", "海拔": "语义：「海拔」指地面高出海平面的高度，与墙纸和石头的表面特征毫不相干。"}, "sentence_index": 6, "correct_answer": "质感"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这辆车的质感很快，几秒钟就跑完了一百米。", "explanation": "这里应该用〈速度〉。「质感」指物体表面的触感或视觉、听觉上的品质，不能用来说车的快慢；车的快慢要用「速度」。"}, {"text": "我对这幅画的质感很深，很难忘。", "explanation": "这里应该用〈感受〉。「质感」指物体表面的触感或视觉特征，不能用来表达人对画作的感受有多深。"}, {"text": "孩子的质感很大，压得他喘不过气。", "explanation": "这里应该用〈压力〉。「质感」不能用来说人心里的负担，「压力」才是。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5af3f3f-28b9-436c-a853-699974f0110f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12409, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这双鞋有一只很好的质感，穿起来很舒服。", "corrected_sentence": "这双鞋有一种很好的质感，穿起来很舒服。", "error_description": "「质感」是抽象名词，量词应用「种」（一种质感）。用「只」是错的，「只」用于单个或成对的具体物品。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5af3f3f-28b9-436c-a853-699974f0110f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12409, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这块石头的质感的很粗糙，摸起来扎手。", "corrected_sentence": "这块石头的质感很粗糙，摸起来扎手。", "error_description": "助词错误：“质感的很粗糙”多了一个“的”，应改为“质感很粗糙”。“质感”后面直接接形容词作谓语时不加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd5af3f3f-28b9-436c-a853-699974f0110f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
