INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12414, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "建造、搭建或安装（设备、桥梁、结构等）。", "primary_collocate": null, "pronunciation": "jià shè", "ipa": "tɕja˥˩ ʂɤ˥˩", "syllable_count": 2, "sentences": [{"text": "施工队在山谷两侧架设了一条新索道，用来运送建材。", "target_word": "架设", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们在河上架设了一座新桥。", "target_word": "架设", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里正在架设电线，明天就有电了。", "target_word": "架设", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在山顶架设了一个信号塔。", "target_word": "架设", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军人用两天时间架设好了浮桥。", "target_word": "架设", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司请人在楼顶架设网络天线。", "target_word": "架设", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程师把电缆架设在两座山之间。", "target_word": "架设", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条铁路上架设过很多座大桥。", "target_word": "架设", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们想在河边架设一条电话线。", "target_word": "架设", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了让大家看比赛，学校在操场上架设了大屏幕。", "target_word": "架设", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "架设了", "label": "完成体"}, {"form": "架设过", "label": "经历体"}, {"form": "架设好", "label": "结果补语"}], "register": "中性", "sense_fingerprint": "建造或安装桥梁、电线、设备等", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6d1d209-2497-4689-a3ce-946e569e7ac1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12414, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "架设", "is_correct": true, "explanation": "架设 jià shè：把桥梁、线路、设备等支起来或搭建、安装，是目标词。"}, {"text": "假设", "is_correct": false, "explanation": "假设 jiǎ shè 与 架设 jià shè 的第一个音节声调不同（jiǎ 为第三声，jià 为第四声），意思是假定、设想。"}, {"text": "建设", "is_correct": false, "explanation": "建设 jiàn shè 与 架设 jià shè 的第一个音节韵母不同（jiàn 多一个 n，与 jià 的 a 不同），意思是建立、建造。"}, {"text": "架势", "is_correct": false, "explanation": "架势 jià shì 与 架设 jià shè 的第二个音节韵母不同（shì 为 i，shè 为 e），意思是姿态、样子。"}], "explanations": {"架设": "架设 jià shè：把桥梁、线路、设备等支起来或搭建、安装，是目标词。", "假设": "假设 jiǎ shè 与 架设 jià shè 的第一个音节声调不同（jiǎ 为第三声，jià 为第四声），意思是假定、设想。", "建设": "建设 jiàn shè 与 架设 jià shè 的第一个音节韵母不同（jiàn 多一个 n，与 jià 的 a 不同），意思是建立、建造。", "架势": "架势 jià shì 与 架设 jià shè 的第二个音节韵母不同（shì 为 i，shè 为 e），意思是姿态、样子。"}, "sentence_index": null, "correct_answer": "架设"}, "level_3": {"options": [{"text": "架设", "is_correct": true, "explanation": "正确：“架设索道”指把索道搭建起来，与句中“用来运送建材”的用途相合。"}, {"text": "拆除", "is_correct": false, "explanation": "语义：“拆除”指拆掉，与句中“用来运送建材”的用途相反，句子说不通。"}, {"text": "炸毁", "is_correct": false, "explanation": "语义：“炸毁”指炸坏，与句中新索道用来运送建材的用途相反，句子说不通。"}, {"text": "忘记", "is_correct": false, "explanation": "搭配：“忘记”的对象应是事情或记忆，不能与“索道”这类设施搭配。"}], "explanations": {"架设": "正确：“架设索道”指把索道搭建起来，与句中“用来运送建材”的用途相合。", "拆除": "语义：“拆除”指拆掉，与句中“用来运送建材”的用途相反，句子说不通。", "炸毁": "语义：“炸毁”指炸坏，与句中新索道用来运送建材的用途相反，句子说不通。", "忘记": "搭配：“忘记”的对象应是事情或记忆，不能与“索道”这类设施搭配。"}, "sentence_index": 0, "correct_answer": "架设"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学校计划架设一座新图书馆。", "explanation": "这里应该用〈修建〉。架设多用于桥梁、电线、塔架等具体设施，图书馆这类大型建筑要用修建。"}, {"text": "工人们在屋里架设了新的地板。", "explanation": "这里应该用〈铺〉。架设指把线路、设备等支起或装好，地板应说铺。"}, {"text": "政府决定架设一座体育馆。", "explanation": "这里应该用〈修建〉。架设多用于桥梁、电线、塔架等具体设施，体育馆这类大型建筑要说修建。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d2a2bff-9fd6-4a64-bebb-e819301a0046') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12414, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "架设", "is_correct": true, "explanation": "正确：“把电缆架设在两座山之间”指把电缆架起来连接两山，符合句意。"}, {"text": "切断", "is_correct": false, "explanation": "语义：“切断”指割断，与“把电缆……在两座山之间”的铺设意思相反。"}, {"text": "烧毁", "is_correct": false, "explanation": "语义：“烧毁”指烧坏，与工程师布设电缆的目的不符，句子说不通。"}, {"text": "抛弃", "is_correct": false, "explanation": "语义：“抛弃”指丢弃，与把电缆架起来连接两山的意思不符，句子说不通。"}], "explanations": {"架设": "正确：“把电缆架设在两座山之间”指把电缆架起来连接两山，符合句意。", "切断": "语义：“切断”指割断，与“把电缆……在两座山之间”的铺设意思相反。", "烧毁": "语义：“烧毁”指烧坏，与工程师布设电缆的目的不符，句子说不通。", "抛弃": "语义：“抛弃”指丢弃，与把电缆架起来连接两山的意思不符，句子说不通。"}, "sentence_index": 6, "correct_answer": "架设"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她把茶杯架设在桌上，等水烧开。", "explanation": "这里应该用〈放〉。架设指建造或安装设施，此处只是把茶杯摆放在桌上，应说〈放〉。"}, {"text": "妈妈把花盆架设在窗台上。", "explanation": "这里应该用〈放〉。架设指建造或安装设施，此处只是把花盆摆放在窗台上，应说〈放〉。"}, {"text": "她把相框架设在书桌上。", "explanation": "这里应该用〈放〉。架设指建造或安装设施，此处只是把相框摆放在书桌上，应说〈放〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d2a2bff-9fd6-4a64-bebb-e819301a0046') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12414, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们在河口架设了过一座铁塔。", "corrected_sentence": "他们在河口架设过一座铁塔。", "error_description": "体貌错误：“过”表示经历，与“了”不能同时用于同一动词。应说“架设过一座铁塔”，不能说“架设了过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d2a2bff-9fd6-4a64-bebb-e819301a0046') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12414, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人们在工地上架设了好一台起重机。", "corrected_sentence": "工人们在工地上架设好了一台起重机。", "error_description": "补语位置错误：“好”是结果补语，应放在动词后、“了”之前，说“架设好了一台起重机”，不能说“架设了好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d2a2bff-9fd6-4a64-bebb-e819301a0046') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
