INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12417, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd65afb6c-6dd9-4e04-86e5-d2c2067f175e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12417, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "存在论是哲学中研究‘存在’本身以及世界基本构成的理论。", "primary_collocate": null, "pronunciation": "cún zài lùn", "ipa": "tsʰuən˧˥ tsaɪ˥˩ luən˥˩", "syllable_count": 3, "sentences": [{"text": "更深层而言，口头传统揭示了一种根本性的存在论：人类并非单纯生活在物理现实中，而是栖居于由故事构筑的意义网络之中。", "target_word": "存在论", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "海德格尔的存在论影响了很多哲学家。", "target_word": "存在论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位教授专门研究古希腊的存在论。", "target_word": "存在论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "存在论问的是世界到底是什么。", "target_word": "存在论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学哲学的人常常要读存在论的书。", "target_word": "存在论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在课上讲了存在论和认识论的区别。", "target_word": "存在论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "存在论认为，先要弄清什么是“存在”。", "target_word": "存在论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书用简单的话介绍了存在论。", "target_word": "存在论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，存在论是哲学最基本的部分。", "target_word": "存在论", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我对存在论很感兴趣，所以选了这门课。", "target_word": "存在论", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "存在論", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "哲学中研究存在本身与世界基本构成的理论", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84b46a45-2baa-4fa4-b1e2-7adacd8bb984') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12417, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "存在论", "is_correct": true, "explanation": "正确：存在论指研究“存在”本身的哲学理论，与“揭示了一种根本性的”语境相合。"}, {"text": "乐谱", "is_correct": false, "explanation": "语义：乐谱是记录音乐的符号，不能作为揭示世界基本构成的哲学理论。"}, {"text": "食谱", "is_correct": false, "explanation": "语义：食谱是做菜的说明，与“口头传统”“意义网络”毫不相关。"}, {"text": "时刻表", "is_correct": false, "explanation": "搭配：“根本性的”修饰理论或本质，不能说“根本性的时刻表”。"}], "explanations": {"存在论": "正确：存在论指研究“存在”本身的哲学理论，与“揭示了一种根本性的”语境相合。", "乐谱": "语义：乐谱是记录音乐的符号，不能作为揭示世界基本构成的哲学理论。", "食谱": "语义：食谱是做菜的说明，与“口头传统”“意义网络”毫不相关。", "时刻表": "搭配：“根本性的”修饰理论或本质，不能说“根本性的时刻表”。"}, "sentence_index": 0, "correct_answer": "存在论"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "存在论研究人是如何获得知识的。", "explanation": "这里应该用〈认识论〉。存在论研究“存在”本身，人如何获得知识属于认识论，不属于存在论。"}, {"text": "存在论研究恒星如何发光和演化。", "explanation": "这里应该用〈天文学〉。恒星的发光与演化属于天文学，存在论研究的是“存在”本身及世界的基本构成。"}, {"text": "存在论研究法律条文的解释原则。", "explanation": "这里应该用〈法学〉。法律条文的解释原则属于法学，存在论研究的是“存在”本身。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd65afb6c-6dd9-4e04-86e5-d2c2067f175e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12417, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "存在论", "is_correct": true, "explanation": "正确：存在论是一种哲学理论，可以“认为”先要弄清什么是“存在”，与句意相合。"}, {"text": "天气预报", "is_correct": false, "explanation": "语义：天气预报是对天气的预测，不会“认为”先要弄清什么是“存在”。"}, {"text": "食堂", "is_correct": false, "explanation": "语义：食堂是吃饭的地方，不是能提出观点的主体。"}, {"text": "身高", "is_correct": false, "explanation": "配价：“认为”要求有思考能力的主语，“身高”不能作“认为”的主语。"}], "explanations": {"存在论": "正确：存在论是一种哲学理论，可以“认为”先要弄清什么是“存在”，与句意相合。", "天气预报": "语义：天气预报是对天气的预测，不会“认为”先要弄清什么是“存在”。", "食堂": "语义：食堂是吃饭的地方，不是能提出观点的主体。", "身高": "配价：“认为”要求有思考能力的主语，“身高”不能作“认为”的主语。"}, "sentence_index": 6, "correct_answer": "存在论"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "存在论研究善恶和道德准则。", "explanation": "这里应该用〈伦理学〉。善恶与道德准则属于伦理学，存在论研究的是“存在”本身。"}, {"text": "存在论研究推理的规则。", "explanation": "这里应该用〈逻辑学〉。推理的规则属于逻辑学，不属于存在论的研究范围。"}, {"text": "存在论研究美的本质和艺术的感受。", "explanation": "这里应该用〈美学〉。美的本质与艺术感受属于美学，存在论研究的是“存在”本身。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd65afb6c-6dd9-4e04-86e5-d2c2067f175e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12417, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他这学期选修了一张存在论。", "corrected_sentence": "他这学期选修了一门存在论。", "error_description": "“存在论”作为学科应与“门”搭配；“张”用于平面的东西，不能修饰学科名称。正确说法是“一门存在论”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd65afb6c-6dd9-4e04-86e5-d2c2067f175e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12417, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他写了一张关于存在论的文章。", "corrected_sentence": "他写了一篇关于存在论的文章。", "error_description": "量词错误：“文章”应用“篇”，“张”用于平面的东西，不能修饰文章。正确说法是“一篇关于存在论的文章”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd65afb6c-6dd9-4e04-86e5-d2c2067f175e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
