INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12420, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "能深刻影响思想或情感的内在影响力", "primary_collocate": null, "pronunciation": "lì liàng", "ipa": "li˥˩ liɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这首歌有一种力量，让人重新相信生活。", "target_word": "力量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的话给了我继续走下去的力量。", "target_word": "力量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好书能给人安静而深刻的力量。", "target_word": "力量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "母亲的爱是我心里最大的力量。", "target_word": "力量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老人的故事有打动人心的力量。", "target_word": "力量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "读完这封信，我感到一股温暖的力量。", "target_word": "力量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "音乐的力量常常比语言更深。", "target_word": "力量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "信仰给了他面对困难的力量。", "target_word": "力量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这幅画有让人安静下来的力量。", "target_word": "力量", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师的鼓励成了我心里的力量。", "target_word": "力量", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一股", "label": "量词"}, {"form": "一种", "label": "量词"}], "register": "中性", "sense_fingerprint": "能深刻影响人思想和情感的内在影响力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84b46a45-2baa-4fa4-b1e2-7adacd8bb984') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12420, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "力量", "is_correct": true, "explanation": "正确。lì liàng，指能深刻影响思想和情感的内在影响力。"}, {"text": "质量", "is_correct": false, "explanation": "zhì 与 lì 声母不同（zh / l），意思是事物的好坏程度，不是影响力。"}, {"text": "技量", "is_correct": false, "explanation": "jì 与 lì 声母不同（j / l），意思是技艺水平，不是影响力。"}, {"text": "体量", "is_correct": false, "explanation": "tǐ 与 lì 声母及声调都不同，意思是体积或规模，不是影响力。"}], "explanations": {"力量": "正确。lì liàng，指能深刻影响思想和情感的内在影响力。", "质量": "zhì 与 lì 声母不同（zh / l），意思是事物的好坏程度，不是影响力。", "技量": "jì 与 lì 声母不同（j / l），意思是技艺水平，不是影响力。", "体量": "tǐ 与 lì 声母及声调都不同，意思是体积或规模，不是影响力。"}, "sentence_index": null, "correct_answer": "力量"}, "level_3": {"options": [{"text": "力量", "is_correct": true, "explanation": "正确。力量指能深刻影响情感的内在作用，与“让人重新相信生活”相合。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色是视觉属性，不能让人重新相信生活。"}, {"text": "形状", "is_correct": false, "explanation": "语义：形状是外观，不能让人重新相信生活。"}, {"text": "体积", "is_correct": false, "explanation": "搭配：“体积”不能与“让人重新相信生活”搭配，这一句说的是内在作用。"}], "explanations": {"力量": "正确。力量指能深刻影响情感的内在作用，与“让人重新相信生活”相合。", "颜色": "语义：颜色是视觉属性，不能让人重新相信生活。", "形状": "语义：形状是外观，不能让人重新相信生活。", "体积": "搭配：“体积”不能与“让人重新相信生活”搭配，这一句说的是内在作用。"}, "sentence_index": 0, "correct_answer": "力量"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他下定力量，要把这件事做到底。", "explanation": "这里应该用〈决心〉。“下定”搭配“决心”，不能搭配“力量”；力量指能影响他人或事物的作用。"}, {"text": "老师给了我一只力量，让我继续努力。", "explanation": "这里应该用〈股〉。“只”多用于动物或成对的东西，力量应说“一股”或“一种”。"}, {"text": "这辆车的力量很快，一分钟就能开过两公里。", "explanation": "这里应该用〈速度〉。“力量”指作用或影响，不能用“快”来形容；车子跑得快要说“速度”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd65afb6c-6dd9-4e04-86e5-d2c2067f175e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12420, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "力量", "is_correct": true, "explanation": "正确。力量指音乐的内在感染作用，可以比语言更深。"}, {"text": "音量", "is_correct": false, "explanation": "语义：音量指声音的大小，不能用“更深”来比较。"}, {"text": "高度", "is_correct": false, "explanation": "搭配：“深”不修饰“高度”，不能说“高度更深”。"}, {"text": "长度", "is_correct": false, "explanation": "搭配：“深”不修饰“长度”，不能说“长度更深”。"}], "explanations": {"力量": "正确。力量指音乐的内在感染作用，可以比语言更深。", "音量": "语义：音量指声音的大小，不能用“更深”来比较。", "高度": "搭配：“深”不修饰“高度”，不能说“高度更深”。", "长度": "搭配：“深”不修饰“长度”，不能说“长度更深”。"}, "sentence_index": 6, "correct_answer": "力量"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次谈话后，我心里多了一根力量。", "explanation": "这里应该用〈股〉。“根”用于细长的东西，力量应说“一股”或“一种”。"}, {"text": "他的鼓励让我胸口多了一块力量。", "explanation": "这里应该用〈股〉。“块”多用于片状或块状的东西，力量应说“一股”或“一种”。"}, {"text": "这本书给了我一把力量，让我继续前行。", "explanation": "这里应该用〈股〉。“把”用于有柄的器具，力量应说“一股”或“一种”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd65afb6c-6dd9-4e04-86e5-d2c2067f175e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12420, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她的鼓励给了我面对生活力量。", "corrected_sentence": "她的鼓励给了我面对生活的力量。", "error_description": "错误在于“力量”前的修饰成分漏了“的”。正确说法是“面对生活的力量”，名词修饰名词时要加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd65afb6c-6dd9-4e04-86e5-d2c2067f175e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12420, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这首诗有一条让人感动的力量。", "corrected_sentence": "这首诗有一股让人感动的力量。", "error_description": "量词错误：“力量”应搭配“股”或“种”，“条”用于细长或条状的东西，不能修饰力量。正确说法是“一股力量”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd65afb6c-6dd9-4e04-86e5-d2c2067f175e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
