INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12421, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "考古是通过发掘和研究古代人类活动留下的遗物、遗迹等，来了解古代社会历史的一门学科。", "primary_collocate": null, "pronunciation": "kǎo gǔ", "ipa": "kʰɑʊ˨˩˦ ku˨˩˦", "syllable_count": 2, "sentences": [{"text": "与其把考古视为挖掘文物的技艺，不如将它看作一种通过物证重建过去的推理方法。", "target_word": "考古", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "我对考古很感兴趣。", "target_word": "考古", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "哥哥大学学的是考古。", "target_word": "考古", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "考古需要很多耐心。", "target_word": "考古", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "考古工作常常在野外进行。", "target_word": "考古", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从小就喜欢历史和考古。", "target_word": "考古", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学考古的人要会画图。", "target_word": "考古", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "考古能告诉我们古人怎么生活。", "target_word": "考古", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考古是一门很有意思的学科。", "target_word": "考古", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书讲的是考古的故事。", "target_word": "考古", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "考古学", "label": "复合"}, {"form": "考古学家", "label": "复合"}], "register": "中性", "sense_fingerprint": "研究古代遗物遗迹的学科", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '576e64ee-f9ee-4e44-b7e0-41b533bdad60') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12421, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "考古", "is_correct": true, "explanation": "正确：此处“考古”指作为学科的考古，与后文“推理方法”的论述相符。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是学科，不能视为“挖掘文物的技艺”。"}, {"text": "饮食", "is_correct": false, "explanation": "语义：饮食不是学科或技艺，“把饮食视为挖掘文物的技艺”不通。"}, {"text": "体育", "is_correct": false, "explanation": "语义：体育与“挖掘文物的技艺”无关，句意不通。"}], "explanations": {"考古": "正确：此处“考古”指作为学科的考古，与后文“推理方法”的论述相符。", "天气": "语义：天气不是学科，不能视为“挖掘文物的技艺”。", "饮食": "语义：饮食不是学科或技艺，“把饮食视为挖掘文物的技艺”不通。", "体育": "语义：体育与“挖掘文物的技艺”无关，句意不通。"}, "sentence_index": 0, "correct_answer": "考古"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我大学学的是一只考古。", "explanation": "这里应该用〈门〉。「考古」作学科名时用量词「门」，「只」用于动物。"}, {"text": "我在博物馆看到一座考古。", "explanation": "量词错误：「座」用于山、楼房等建筑，考古指学科或活动，不能用「座」计量。"}, {"text": "我们正在考古古代诗歌的写作手法。", "explanation": "这里应该用〈研究〉。「考古」指挖掘古代遗存的学科或活动，不能用来指研究抽象的写作手法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97558be5-0264-4dbe-81ab-2f5e1f62d970') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12421, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "足球", "is_correct": false, "explanation": "语义：学足球的人与「会画图」的要求无关，句意不通。"}, {"text": "烹饪", "is_correct": false, "explanation": "语义：烹饪与画图无关，「学烹饪的人要会画图」不合常理。"}, {"text": "考古", "is_correct": true, "explanation": "正确：「学考古」指学习考古学科，学考古的人需要画图，符合句意。"}, {"text": "钢琴", "is_correct": false, "explanation": "搭配：「会画图」一般与美术、制图相搭，「钢琴」不构成搭配。"}], "explanations": {"足球": "语义：学足球的人与「会画图」的要求无关，句意不通。", "烹饪": "语义：烹饪与画图无关，「学烹饪的人要会画图」不合常理。", "考古": "正确：「学考古」指学习考古学科，学考古的人需要画图，符合句意。", "钢琴": "搭配：「会画图」一般与美术、制图相搭，「钢琴」不构成搭配。"}, "sentence_index": 6, "correct_answer": "考古"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家店专门卖各种考古，价格都很贵。", "explanation": "这里应该用〈古董〉。「考古」指学科或挖掘活动，不指古物实物，卖的古物应说「古董」。"}, {"text": "那位考古是我的老师。", "explanation": "「考古」是学科名，不指人，用来称呼人是词义用错，指人应说「考古学家」。"}, {"text": "工人们在施工，每天要考古两车土。", "explanation": "这里应该用〈挖掘〉。「考古」作动词时指有计划地发掘研究，一般的挖出不用「考古」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97558be5-0264-4dbe-81ab-2f5e1f62d970') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12421, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我想学一只考古。", "corrected_sentence": "我想学一门考古。", "error_description": "量词错误：「考古」作学科名，应用量词「门」。「只」用于动物，不能用于学科。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97558be5-0264-4dbe-81ab-2f5e1f62d970') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12421, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她在大学里了学考古。", "corrected_sentence": "她在大学里学了考古。", "error_description": "了的位置错误：「了」应放在动词「学」之后，应说「学了考古」，不能放在动词前面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97558be5-0264-4dbe-81ab-2f5e1f62d970') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
