INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12424, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一种象征人类普遍经验或心理的基本模式", "primary_collocate": null, "pronunciation": "yuán xíng", "ipa": "ɥɛn˧˥ ɕiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "这一反复出现的英雄形象，正是人类心理中一种象征共同经验的原型。", "target_word": "原型", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "荣格认为，英雄是一种常见的原型。", "target_word": "原型", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "很多故事里都有母亲这个原型。", "target_word": "原型", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "心理学家研究人类心理中的原型。", "target_word": "原型", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个神话反映了人类共同的原型。", "target_word": "原型", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "智慧的老人是故事里常见的原型。", "target_word": "原型", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "书中的英雄形象，体现了一种跨文化的原型。", "target_word": "原型", "complexity_tier": "T3", "furigana": "shū zhōng de yīngxióng xíngxiàng, tǐxiàn le yì zhǒng kuà wénhuà de yuánxíng.", "sentence_source": "generated"}, {"text": "不同国家的童话里，常有相似的原型。", "target_word": "原型", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "梦里出现的人物，可能来自某种原型。", "target_word": "原型", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，英雄和恶人都是文学中的原型。", "target_word": "原型", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "书面", "sense_fingerprint": "原型：荣格心理学中象征人类普遍经验的基本模式", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f775cb0c-f64a-45de-b26d-fcb784c8d131') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12424, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "原型", "is_correct": true, "explanation": "原型：指象征人类普遍经验的基本模式，与句中“象征共同经验的”所指一致。"}, {"text": "原野", "is_correct": false, "explanation": "语义：原野指空旷的土地，不能指象征共同经验的基本模式。"}, {"text": "原料", "is_correct": false, "explanation": "语义：原料指未加工的具体材料，不能指象征共同经验的抽象模式。"}, {"text": "原告", "is_correct": false, "explanation": "语义：原告指法律上提起诉讼的一方，与句意无关。"}], "explanations": {"原型": "原型：指象征人类普遍经验的基本模式，与句中“象征共同经验的”所指一致。", "原野": "语义：原野指空旷的土地，不能指象征共同经验的基本模式。", "原料": "语义：原料指未加工的具体材料，不能指象征共同经验的抽象模式。", "原告": "语义：原告指法律上提起诉讼的一方，与句意无关。"}, "sentence_index": 0, "correct_answer": "原型"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他说话很原型，总爱讲大道理。", "explanation": "这里应该用〈典型〉。“原型”是名词，不能受“很”修饰。"}, {"text": "他把这个故事原型了一遍。", "explanation": "这里应该用〈改写〉。“原型”是名词，不能作动词。"}, {"text": "这首诗里藏着一扇原型。", "explanation": "这里应该用〈个〉。“扇”用于门窗，“原型”要用“个”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e4a91d6-71e2-4710-8870-96bbf7f7d5cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12424, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "原型", "is_correct": true, "explanation": "原型：指象征人类共同经验的基本模式，与“跨文化”的用法相符。"}, {"text": "原油", "is_correct": false, "explanation": "搭配：“体现”后接抽象的意义或特征，不接“原油”。"}, {"text": "原汁", "is_correct": false, "explanation": "语义：原汁指液体的原味，不能指英雄形象所体现的模式。"}, {"text": "原木", "is_correct": false, "explanation": "语义：原木指未加工的木材，与“英雄形象”和文化特征无关。"}], "explanations": {"原型": "原型：指象征人类共同经验的基本模式，与“跨文化”的用法相符。", "原油": "搭配：“体现”后接抽象的意义或特征，不接“原油”。", "原汁": "语义：原汁指液体的原味，不能指英雄形象所体现的模式。", "原木": "语义：原木指未加工的木材，与“英雄形象”和文化特征无关。"}, "sentence_index": 6, "correct_answer": "原型"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "医生从病人身上采集了一份血液原型。", "explanation": "这里应该用〈样本〉。原型指象征普遍经验的基本模式，不指从身体上采集的实物样本。"}, {"text": "这座古寺很原型，游客都爱来参观。", "explanation": "这里应该用〈古老〉。“原型”是名词，不能受“很”修饰。"}, {"text": "他手里拿着一支原型。", "explanation": "这里应该用〈个〉。“支”用于笔、队伍等，“原型”要用“个”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e4a91d6-71e2-4710-8870-96bbf7f7d5cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12424, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "很多神话故事里都能找到这种英雄的一只原型。", "corrected_sentence": "很多神话故事里都能找到这种英雄的原型。", "error_description": "量词错误：“原型”不用“只”。错误形式：一只原型；正确形式：去掉量词，或用“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e4a91d6-71e2-4710-8870-96bbf7f7d5cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12424, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师把英雄的一根原型讲出来了。", "corrected_sentence": "老师把英雄的原型讲出来了。", "error_description": "量词错误：“根”用于细长的东西，“原型”不用“根”。错误形式：一根原型；正确形式：去掉量词，或用“个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e4a91d6-71e2-4710-8870-96bbf7f7d5cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
