INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12438, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "用纸板制成的容器，用于装东西。", "primary_collocate": null, "pronunciation": "zhǐ hé", "ipa": "ʈʂɻ̩˨˩˦ xɤ˧˥", "syllable_count": 2, "sentences": [{"text": "它出现在瓶子、纸盒上。", "target_word": "纸盒", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "他把蛋糕放进了纸盒里。", "target_word": "纸盒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个纸盒很轻，也很结实。", "target_word": "纸盒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈用旧纸盒做了一个小房子。", "target_word": "纸盒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子上有三个空纸盒。", "target_word": "纸盒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把纸盒扔到垃圾桶里。", "target_word": "纸盒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "纸盒里装着我的新鞋子。", "target_word": "纸盒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "牛奶纸盒上写着日期。", "target_word": "纸盒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在纸盒上画了画。", "target_word": "纸盒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别把纸盒放在水边。", "target_word": "纸盒", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "紙盒", "label": "繁体"}], "register": "中性", "sense_fingerprint": "纸板做的装东西的容器", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f7846ece-b54f-4e87-9fd6-ee570f2cbede') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12438, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "纸盒", "is_correct": true, "explanation": "正确：“纸盒”与“瓶子”同为可见的容器，可以并列出现在“它出现在……上”中。"}, {"text": "人", "is_correct": false, "explanation": "语义：人不是能让东西“出现”的承载物，与“瓶子”并列不通。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“在……上”不能与“空气”搭配，空气不是平面承载物。"}, {"text": "雨", "is_correct": false, "explanation": "语义：雨是天气现象，不是可以承载物品的东西，与“瓶子”并列不通。"}], "explanations": {"纸盒": "正确：“纸盒”与“瓶子”同为可见的容器，可以并列出现在“它出现在……上”中。", "人": "语义：人不是能让东西“出现”的承载物，与“瓶子”并列不通。", "空气": "搭配：“在……上”不能与“空气”搭配，空气不是平面承载物。", "雨": "语义：雨是天气现象，不是可以承载物品的东西，与“瓶子”并列不通。"}, "sentence_index": 0, "correct_answer": "纸盒"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用纸盒切菜，切得很快。", "explanation": "这里应该用〈菜刀〉。纸盒没有刃，不能切菜，切菜要用菜刀。"}, {"text": "他把汽车停进纸盒里。", "explanation": "这里应该用〈车库〉。纸盒太小，装不下汽车，停车要去车库。"}, {"text": "妈妈用纸盒烧了一锅饭。", "explanation": "这里应该用〈炊具〉。纸盒不能受热，烧饭要用能加热的炊具，纸盒只用来装东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c268c7e3-5282-4bda-b5ca-f1a38922aee8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12438, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "纸盒", "is_correct": true, "explanation": "正确：“纸盒里装着我的新鞋子”中，“纸盒”是能装东西的容器。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空里不能装鞋子，句意不通。"}, {"text": "眼睛", "is_correct": false, "explanation": "搭配：“装着”不能搭配“眼睛”，眼睛不是容器。"}, {"text": "大海", "is_correct": false, "explanation": "语义：大海不能装鞋子，与容器的意思矛盾。"}], "explanations": {"纸盒": "正确：“纸盒里装着我的新鞋子”中，“纸盒”是能装东西的容器。", "天空": "语义：天空里不能装鞋子，句意不通。", "眼睛": "搭配：“装着”不能搭配“眼睛”，眼睛不是容器。", "大海": "语义：大海不能装鞋子，与容器的意思矛盾。"}, "sentence_index": 6, "correct_answer": "纸盒"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "小鱼在纸盒里游来游去。", "explanation": "这里应该用〈鱼缸〉。纸盒不防水、装不了水，不能养鱼。"}, {"text": "他在纸盒里洗澡。", "explanation": "这里应该用〈浴缸〉。洗澡要用能盛水的浴缸，纸盒不能盛水。"}, {"text": "他在纸盒里游泳。", "explanation": "这里应该用〈游泳池〉。纸盒装不下人，也不能盛水，游泳要去游泳池。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c268c7e3-5282-4bda-b5ca-f1a38922aee8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12438, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我纸盒里放了饼干。", "corrected_sentence": "我在纸盒里放了饼干。", "error_description": "错误：表示处所的“纸盒里”前缺少介词“在”，应说“在纸盒里放了饼干”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c268c7e3-5282-4bda-b5ca-f1a38922aee8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12438, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把纸盒扁踩了。", "corrected_sentence": "他把纸盒踩扁了。", "error_description": "错误：结果补语“扁”应紧跟动词，应说“踩扁了”，不能说“扁踩了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c268c7e3-5282-4bda-b5ca-f1a38922aee8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
