INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12446, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "能够理解或识别（文字、语言等）的含义。", "primary_collocate": null, "pronunciation": "kàn de dǒng", "ipa": "kʰan˥˩ tə toŋ˨˩˦", "syllable_count": 3, "sentences": [{"text": "这个设计很简单，大家都看得懂。", "target_word": "看得懂", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "这本书有很多图片，孩子也看得懂。", "target_word": "看得懂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的字写得这么乱，谁看得懂？", "target_word": "看得懂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师讲得很清楚，所以我看得懂这篇文章。", "target_word": "看得懂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影没有字幕，你看得懂吗？", "target_word": "看得懂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他学了三年中文，现在看得懂中文报纸了。", "target_word": "看得懂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路上的标志很清楚，外国人也看得懂。", "target_word": "看得懂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张地图画得很简单，一看就看得懂。", "target_word": "看得懂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "说明书是中文的，爷爷看得懂。", "target_word": "看得懂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份表格不难，你自己一定看得懂。", "target_word": "看得懂", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "看不懂", "label": "否定"}, {"form": "看懂了", "label": "体标"}], "register": "中性", "sense_fingerprint": "能理解或识别文字内容的含义", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '734ba1be-1b8e-436a-b024-5fdfa984a06b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12446, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "看得懂", "is_correct": true, "explanation": "正确：“看得懂”表示能理解设计的含义，与“很简单”相符。"}, {"text": "听不懂", "is_correct": false, "explanation": "搭配：“听”用于声音和语言，设计是图形，不能说听不懂。"}, {"text": "看不懂", "is_correct": false, "explanation": "语义：“很简单”说明设计容易理解，与“看不懂”矛盾。"}, {"text": "学不会", "is_correct": false, "explanation": "语义：既然设计很简单，就不会是“学不会”，两者矛盾。"}], "explanations": {"看得懂": "正确：“看得懂”表示能理解设计的含义，与“很简单”相符。", "听不懂": "搭配：“听”用于声音和语言，设计是图形，不能说听不懂。", "看不懂": "语义：“很简单”说明设计容易理解，与“看不懂”矛盾。", "学不会": "语义：既然设计很简单，就不会是“学不会”，两者矛盾。"}, "sentence_index": 0, "correct_answer": "看得懂"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这张照片太模糊，我看得懂上面一共有几个人。", "explanation": "这里应该用〈数清〉。看得懂用于理解文字、图画等的含义，能不能数清人数要用数清。"}, {"text": "他说的方言太快，我看得懂。", "explanation": "这里应该用〈听懂〉。方言是口头语言，要靠听；看得懂只适用于文字和图画。"}, {"text": "雾太大，我看得懂五十米外的山。", "explanation": "这里应该用〈看清〉。这句说的是能不能看见山，不是理解它的含义，要用看清。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acb0be78-9a99-43af-b1b3-cb80d28a5a5b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12446, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "看得懂", "is_correct": true, "explanation": "正确：标志很清楚，外国人也能理解其含义。"}, {"text": "看不清", "is_correct": false, "explanation": "语义：“很清楚”说明标志容易辨认，外国人不会“看不清”，与前句矛盾。"}, {"text": "说得通", "is_correct": false, "explanation": "搭配：“说得通”用于道理和说法，标志是图形，不能说说得通。"}, {"text": "听得见", "is_correct": false, "explanation": "搭配：“听得见”指听觉，标志是视觉的，不能用听。"}], "explanations": {"看得懂": "正确：标志很清楚，外国人也能理解其含义。", "看不清": "语义：“很清楚”说明标志容易辨认，外国人不会“看不清”，与前句矛盾。", "说得通": "搭配：“说得通”用于道理和说法，标志是图形，不能说说得通。", "听得见": "搭配：“听得见”指听觉，标志是视觉的，不能用听。"}, "sentence_index": 6, "correct_answer": "看得懂"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "黑暗里我一摸就看得懂这是一把钥匙。", "explanation": "这里应该用〈知道〉。看得懂指理解文字或语言的含义，靠触觉辨认东西一般说知道。"}, {"text": "我一闻就看得懂是煤气。", "explanation": "这里应该用〈闻出〉。看得懂指理解文字或语言，气味要靠嗅觉，应该用闻出。"}, {"text": "我一看就看得懂这幅画是假的。", "explanation": "这里应该用〈看得出〉。看得懂指理解含义，判断真假、看出迹象要用看得出。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acb0be78-9a99-43af-b1b3-cb80d28a5a5b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12446, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这份合同的条款很清楚，我了看得懂。", "corrected_sentence": "这份合同的条款很清楚，我看得懂。", "error_description": "错误：“看得懂”前多加了“了”。“了”表示完成，不能放在动词之前，这里应直接说“我看得懂”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acb0be78-9a99-43af-b1b3-cb80d28a5a5b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12446, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这份报告写得很细，我的看得懂。", "corrected_sentence": "这份报告写得很细，我看得懂。", "error_description": "错误：“看得懂”前多加了“的”。“我”后应直接接动词，不能加“的”。应说“我看得懂”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acb0be78-9a99-43af-b1b3-cb80d28a5a5b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
