INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12447, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指以某一点为中心做圆周运动，或者绕着某个物体移动。", "primary_collocate": null, "pronunciation": "zhuàn quān", "ipa": "ʈʂwan˥˩ tɕʰyɛn˥", "syllable_count": 2, "sentences": [{"text": "三个箭头转圈跑，像在玩游戏。", "target_word": "转圈", "complexity_tier": "T2", "sentence_source": "mined"}, {"text": "孩子们围着大树转圈跑。", "target_word": "转圈", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小马拉着磨，一直围着磨盘转圈。", "target_word": "转圈", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师让大家围着桌子转圈走。", "target_word": "转圈", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比赛时，他们绕着操场转圈跑了五次。", "target_word": "转圈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鸟围着花园里的树转圈飞。", "target_word": "转圈", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们围着火堆转圈跳舞。", "target_word": "转圈", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他拿着地图围着湖转圈走，还是没找到路。", "target_word": "转圈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们手拉手围着老师转圈唱歌。", "target_word": "转圈", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小猫总是围着我的脚转圈。", "target_word": "转圈", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "转圈儿", "label": "儿化"}], "register": "口语", "sense_fingerprint": "绕着中心点或某个物体做圆周移动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '734ba1be-1b8e-436a-b024-5fdfa984a06b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12447, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "转圈", "is_correct": true, "explanation": "正确：“转圈”描述箭头绕着中心移动，与“像在玩游戏”相符。"}, {"text": "哭着", "is_correct": false, "explanation": "语义：箭头没有感情，不会哭着跑。"}, {"text": "笑着", "is_correct": false, "explanation": "语义：箭头不会笑，“笑着跑”与事物的性质矛盾。"}, {"text": "飞着", "is_correct": false, "explanation": "搭配：“飞”和“跑”互相矛盾，箭头不能飞着跑。"}], "explanations": {"转圈": "正确：“转圈”描述箭头绕着中心移动，与“像在玩游戏”相符。", "哭着": "语义：箭头没有感情，不会哭着跑。", "笑着": "语义：箭头不会笑，“笑着跑”与事物的性质矛盾。", "飞着": "搭配：“飞”和“跑”互相矛盾，箭头不能飞着跑。"}, "sentence_index": 0, "correct_answer": "转圈"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条路笔直，我们一路转圈往北走。", "explanation": "这里应该用〈直行〉。转圈表示绕着一个中心移动，沿着笔直的路前进要用直行。"}, {"text": "他一听到身后有响动，就转圈后退了一步。", "explanation": "这里应该用〈后退〉。转圈指绕着某个中心移动，向后退一步要用后退。"}, {"text": "他拿起书，转圈看了一遍。", "explanation": "这里应该用〈通读〉。转圈指绕圈移动，从头到尾读一遍要用通读。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acb0be78-9a99-43af-b1b3-cb80d28a5a5b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12447, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "转圈", "is_correct": true, "explanation": "正确：“转圈”描述围着火堆绕圈，与“跳舞”搭配自然。"}, {"text": "睡着", "is_correct": false, "explanation": "语义：睡着的人失去意识，不能围着火堆跳舞。"}, {"text": "躺着", "is_correct": false, "explanation": "语义：“躺着”与“跳舞”的动作矛盾，躺着无法跳舞。"}, {"text": "游着", "is_correct": false, "explanation": "搭配：“游”指在水中活动，火堆旁不能游着跳舞。"}], "explanations": {"转圈": "正确：“转圈”描述围着火堆绕圈，与“跳舞”搭配自然。", "睡着": "语义：睡着的人失去意识，不能围着火堆跳舞。", "躺着": "语义：“躺着”与“跳舞”的动作矛盾，躺着无法跳舞。", "游着": "搭配：“游”指在水中活动，火堆旁不能游着跳舞。"}, "sentence_index": 6, "correct_answer": "转圈"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条河很长，我们一路转圈往下游走。", "explanation": "这里应该用〈顺流〉。转圈表示绕着一个中心移动，沿河道一路往下游前进要用顺流。"}, {"text": "他转圈检查了每个箱子。", "explanation": "这里应该用〈逐一〉。转圈指绕圈移动，一个一个地检查要用逐一。"}, {"text": "他一听到门铃，就转圈跑出了门口。", "explanation": "这里应该用〈冲〉。转圈指绕圈移动，直接向门口奔去要用冲。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acb0be78-9a99-43af-b1b3-cb80d28a5a5b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12447, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "小狗在草地上围着石头转圈地，不停地叫。", "corrected_sentence": "小狗在草地上围着石头转圈，不停地叫。", "error_description": "错误：“地”是状语标记，要修饰后面的动词；句中“转圈地”后没有动词，应删去“地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acb0be78-9a99-43af-b1b3-cb80d28a5a5b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12447, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大家围着篝火转圈着唱歌。", "corrected_sentence": "大家围着篝火转圈唱歌。", "error_description": "错误：“转圈着唱歌”。正确：“转圈唱歌”；如果要表示正在进行，应说“转着圈唱歌”。“着”不能直接接在“转圈”后面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acb0be78-9a99-43af-b1b3-cb80d28a5a5b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
