INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12448, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指机器、程序等在一段时间内持续运行、工作。", "primary_collocate": null, "pronunciation": "pǎo", "ipa": "pʰɑʊ̯˨˩˦", "syllable_count": 1, "sentences": [{"text": "这台机器已经跑了三天三夜。", "target_word": "跑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电脑正在跑一个很大的程序。", "target_word": "跑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "服务器一直跑着，不能关机。", "target_word": "跑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洗衣机还在跑，等一会儿再开门。", "target_word": "跑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个软件在后台一直跑着。", "target_word": "跑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我让程序跑一晚上，明天看结果。", "target_word": "跑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂的生产线整天都在跑。", "target_word": "跑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个测试跑了两遍都没有出错。", "target_word": "跑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机器跑起来以后，声音很大。", "target_word": "跑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "实验在电脑上跑了一个晚上。", "target_word": "跑", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "跑了", "label": "体标"}, {"form": "跑着", "label": "体标"}, {"form": "跑过", "label": "体标"}], "register": "中性", "sense_fingerprint": "机器、程序等持续不断地运行", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c22b99d-de53-433a-91c3-3cfd2942df23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12448, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "跑", "is_correct": true, "explanation": "跑（pǎo，第三声）：机器、程序持续运行，是本题的正确答案。"}, {"text": "泡", "is_correct": false, "explanation": "泡（pào，第四声）与 pǎo 声调不同，意思是把东西浸在水里。"}, {"text": "抛", "is_correct": false, "explanation": "抛（pāo，第一声）与 pǎo 声调不同，意思是把东西扔出去。"}, {"text": "饱", "is_correct": false, "explanation": "饱（bǎo，第三声）与 pǎo 声母不同（b 与 p），意思是吃足了。"}, {"text": "袍", "is_correct": false, "explanation": "袍（páo，第二声）与 pǎo 声调不同，意思是长衣服。"}], "explanations": {"跑": "跑（pǎo，第三声）：机器、程序持续运行，是本题的正确答案。", "泡": "泡（pào，第四声）与 pǎo 声调不同，意思是把东西浸在水里。", "抛": "抛（pāo，第一声）与 pǎo 声调不同，意思是把东西扔出去。", "饱": "饱（bǎo，第三声）与 pǎo 声母不同（b 与 p），意思是吃足了。", "袍": "袍（páo，第二声）与 pǎo 声调不同，意思是长衣服。"}, "sentence_index": null, "correct_answer": "跑"}, "level_3": {"options": [{"text": "跑", "is_correct": true, "explanation": "跑：机器已经持续运行三天三夜，与句中的“已经”和“三天三夜”相合。"}, {"text": "哭", "is_correct": false, "explanation": "语义：机器不会哭，“哭了三天三夜”说的不是机器的状态。"}, {"text": "笑", "is_correct": false, "explanation": "语义：机器不会笑，这样说句子不成立。"}, {"text": "送", "is_correct": false, "explanation": "配价：“送”要求带宾语（送什么、送给谁），句中没有宾语，句子不成立。"}], "explanations": {"跑": "跑：机器已经持续运行三天三夜，与句中的“已经”和“三天三夜”相合。", "哭": "语义：机器不会哭，“哭了三天三夜”说的不是机器的状态。", "笑": "语义：机器不会笑，这样说句子不成立。", "送": "配价：“送”要求带宾语（送什么、送给谁），句中没有宾语，句子不成立。"}, "sentence_index": 0, "correct_answer": "跑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我下班前把电脑跑掉了。", "explanation": "这里应该用〈关〉。关掉电脑要用关，跑掉指快速离开，不能用于关机。"}, {"text": "我把这台机器跑到了二楼。", "explanation": "这里应该用〈搬〉。搬动机器要用搬，跑表示机器原地持续运转，不能表示把它挪到某处。"}, {"text": "那个犯人跑了三天三夜，终于被抓住了。", "explanation": "这里的“跑”是“逃跑”的意思，指人挣脱看管逃走，与机器持续运行无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ab1c25b-999f-44d7-8efd-44c987dcdbdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12448, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "跑", "is_correct": true, "explanation": "跑（pǎo，第三声）：机器、程序持续运行，是本题的正确答案。"}, {"text": "炮", "is_correct": false, "explanation": "炮（pào，第四声）与 pǎo 声调不同，意思是大炮。"}, {"text": "保", "is_correct": false, "explanation": "保（bǎo，第三声）与 pǎo 声母不同（b 与 p），意思是保护。"}, {"text": "刨", "is_correct": false, "explanation": "刨（páo，第二声）与 pǎo 声调不同，意思是用刀具削平或挖掘。"}], "explanations": {"跑": "跑（pǎo，第三声）：机器、程序持续运行，是本题的正确答案。", "炮": "炮（pào，第四声）与 pǎo 声调不同，意思是大炮。", "保": "保（bǎo，第三声）与 pǎo 声母不同（b 与 p），意思是保护。", "刨": "刨（páo，第二声）与 pǎo 声调不同，意思是用刀具削平或挖掘。"}, "sentence_index": null, "correct_answer": "跑"}, "level_3": {"options": [{"text": "跑", "is_correct": true, "explanation": "跑：生产线整天持续运行，与“整天都在”相合。"}, {"text": "停", "is_correct": false, "explanation": "语义：“整天都在”表示持续，“停”与之矛盾，句子说不通。"}, {"text": "唱", "is_correct": false, "explanation": "语义：生产线不会唱歌，这样说句子不成立。"}, {"text": "拿", "is_correct": false, "explanation": "配价：“拿”要求带宾语，句中没有宾语，句子不成立。"}], "explanations": {"跑": "跑：生产线整天持续运行，与“整天都在”相合。", "停": "语义：“整天都在”表示持续，“停”与之矛盾，句子说不通。", "唱": "语义：生产线不会唱歌，这样说句子不成立。", "拿": "配价：“拿”要求带宾语，句中没有宾语，句子不成立。"}, "sentence_index": 6, "correct_answer": "跑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我把旧程序跑掉了。", "explanation": "这里应该用〈删除〉。删去程序要用删除，跑掉指快速离开，不能表示删除。"}, {"text": "我把旧程序跑进了垃圾桶。", "explanation": "这里应该用〈扔〉。把东西丢进垃圾桶要用扔，跑只表示机器运转或人用脚快速移动，不能表示丢弃。"}, {"text": "我把包裹跑到了北京。", "explanation": "这里应该用〈寄〉。包裹不能自己移动，寄送要用寄；跑指人或动物用脚快速移动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ab1c25b-999f-44d7-8efd-44c987dcdbdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12448, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台电脑一直着跑，声音很小。", "corrected_sentence": "这台电脑一直跑着，声音很小。", "error_description": "“着”要放在动词后面：应说“跑着”，不能说“着跑”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ab1c25b-999f-44d7-8efd-44c987dcdbdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12448, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个测试完跑了，结果全部正确。", "corrected_sentence": "这个测试跑完了，结果全部正确。", "error_description": "结果补语“完”要放在动词后：应说“跑完了”，“完跑”不对。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ab1c25b-999f-44d7-8efd-44c987dcdbdd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
