INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12451, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一种用铝或铁制成的密封罐，常用于盛装碳酸饮料，瓶盖有拉环，便于开启。", "primary_collocate": null, "pronunciation": "yì lā guàn", "ipa": "i˥˩ la˥ kwan˥˩", "syllable_count": 3, "sentences": [{"text": "它告诉我们：废纸、塑料瓶和易拉罐不是废物，可以变成新东西。", "target_word": "易拉罐", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "他打开易拉罐，喝了一口可乐。", "target_word": "易拉罐", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "易拉罐的盖子上有一个拉环。", "target_word": "易拉罐", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个易拉罐里装的是冰镇汽水。", "target_word": "易拉罐", "complexity_tier": "T3", "furigana": "yì lā guàn", "sentence_source": "generated"}, {"text": "请把喝完的易拉罐放进回收箱。", "target_word": "易拉罐", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "夏天，我最喜欢喝易拉罐装的汽水。", "target_word": "易拉罐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "易拉罐是用铝做的，很轻。", "target_word": "易拉罐", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他用手拉开了易拉罐上的拉环。", "target_word": "易拉罐", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "冰箱里还有三听易拉罐饮料。", "target_word": "易拉罐", "complexity_tier": "T3", "furigana": "yì lā guàn", "sentence_source": "generated"}, {"text": "小心，易拉罐里的汽水会喷出来。", "target_word": "易拉罐", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "带拉环、装碳酸饮料的铝或铁密封罐", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '734ba1be-1b8e-436a-b024-5fdfa984a06b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12451, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "易拉罐", "is_correct": true, "explanation": "正确：句中指喝完后可以回收的金属饮料罐，正是易拉罐。"}, {"text": "蛋糕", "is_correct": false, "explanation": "语义：蛋糕是食品，吃掉就没有了，不能像塑料瓶、易拉罐那样回收再造。"}, {"text": "糟粕", "is_correct": false, "explanation": "语义：糟粕指残渣废料，与句中“不是废物、可以变成新东西”的说法矛盾，不能回收再造。"}, {"text": "猫", "is_correct": false, "explanation": "语义：猫是有生命的动物，不能“变成新东西”，与句中的说法不符。"}], "explanations": {"易拉罐": "正确：句中指喝完后可以回收的金属饮料罐，正是易拉罐。", "蛋糕": "语义：蛋糕是食品，吃掉就没有了，不能像塑料瓶、易拉罐那样回收再造。", "糟粕": "语义：糟粕指残渣废料，与句中“不是废物、可以变成新东西”的说法矛盾，不能回收再造。", "猫": "语义：猫是有生命的动物，不能“变成新东西”，与句中的说法不符。"}, "sentence_index": 0, "correct_answer": "易拉罐"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个易拉罐很大，能装下十公斤大米。", "explanation": "这里应该用〈米袋〉。易拉罐体积小，装不下十公斤大米；装大米要用米袋。"}, {"text": "他每天早上都认真地翻阅易拉罐。", "explanation": "这里应该用〈报纸〉。易拉罐是金属罐，不能用来翻阅；能翻阅的应是报纸。"}, {"text": "他用易拉罐装了一份炒饭。", "explanation": "这里应该用〈饭盒〉。易拉罐是盛饮料的金属罐，不适合用来装炒饭。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acb0be78-9a99-43af-b1b3-cb80d28a5a5b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12451, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "易拉罐", "is_correct": true, "explanation": "正确：句中指用铝制成、很轻的饮料罐，正是易拉罐。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头是天然岩石，不是用铝做的，与句中的材质说明矛盾。"}, {"text": "玻璃杯", "is_correct": false, "explanation": "语义：玻璃杯是玻璃制成的，不是用铝做的，与“用铝做的”矛盾。"}, {"text": "文献", "is_correct": false, "explanation": "搭配：“用铝做的”修饰的应是具体器物，抽象的“文献”不能说用铝做，也不能说很轻。"}], "explanations": {"易拉罐": "正确：句中指用铝制成、很轻的饮料罐，正是易拉罐。", "石头": "语义：石头是天然岩石，不是用铝做的，与句中的材质说明矛盾。", "玻璃杯": "语义：玻璃杯是玻璃制成的，不是用铝做的，与“用铝做的”矛盾。", "文献": "搭配：“用铝做的”修饰的应是具体器物，抽象的“文献”不能说用铝做，也不能说很轻。"}, "sentence_index": 6, "correct_answer": "易拉罐"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用易拉罐端着一大盆汤，走进了厨房。", "explanation": "这里应该用〈锅〉。易拉罐体积小，装不下一大盆汤；煮汤要用锅。"}, {"text": "妈妈把易拉罐挂在墙上，当作装饰画。", "explanation": "这里应该用〈画框〉。易拉罐不能当画，装饰画要用画框。"}, {"text": "易拉罐里养着一只鹦鹉。", "explanation": "这里应该用〈鸟笼〉。养鹦鹉要用鸟笼，易拉罐不能用来养鸟。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acb0be78-9a99-43af-b1b3-cb80d28a5a5b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12451, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他打开了一张易拉罐，喝了一口可乐。", "corrected_sentence": "他打开了一个易拉罐，喝了一口可乐。", "error_description": "量词错误：“易拉罐”应用“个”，不能用“张”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acb0be78-9a99-43af-b1b3-cb80d28a5a5b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12451, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把喝完易拉罐扔进了垃圾桶。", "corrected_sentence": "他把喝完的易拉罐扔进了垃圾桶。", "error_description": "定语标记错误：“喝完”修饰“易拉罐”时要加“的”，应说“喝完的易拉罐”，漏掉“的”是错误。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acb0be78-9a99-43af-b1b3-cb80d28a5a5b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
