INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12453, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "家庭；家庭生活或住所。", "primary_collocate": null, "pronunciation": "jiā", "ipa": "tɕja˥", "syllable_count": 1, "sentences": [{"text": "他家有三口人，父母和一个弟弟。", "target_word": "家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地球是我们共同的家。", "target_word": "家", "complexity_tier": "T1", "sentence_source": "mined"}, {"text": "我每天下班后都回家吃饭。", "target_word": "家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我的家在北京，离公司很近。", "target_word": "家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他离开家已经三年了。", "target_word": "家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "周末我想在家看书。", "target_word": "家", "complexity_tier": "T3", "furigana": "jiā", "sentence_source": "generated"}, {"text": "这个家有爸爸、妈妈和我。", "target_word": "家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们放学后都回到了家。", "target_word": "家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们家的窗户很大，阳光很好。", "target_word": "家", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她把家打扫得很干净。", "target_word": "家", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "家庭", "label": "复合"}, {"form": "家人", "label": "复合"}], "register": "中性", "sense_fingerprint": "家：家庭、住所（回家、我家）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f991c77-0779-429c-842a-f2b0e9d821f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12453, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "家", "is_correct": true, "explanation": "家（jiā，第一声）：家庭、住所，正确答案。"}, {"text": "假", "is_correct": false, "explanation": "假 jiǎ（第三声）与 jiā（第一声）声调不同，意思是虚假、不真实。"}, {"text": "价", "is_correct": false, "explanation": "价 jià（第四声）与 jiā（第一声）声调不同，意思是价格。"}, {"text": "架", "is_correct": false, "explanation": "架 jià（第四声）与 jiā（第一声）声调不同，意思是架子、支架。"}, {"text": "掐", "is_correct": false, "explanation": "掐 qiā 与 jiā 声母不同（q 送气，j 不送气），意思是用手指按压。"}], "explanations": {"家": "家（jiā，第一声）：家庭、住所，正确答案。", "假": "假 jiǎ（第三声）与 jiā（第一声）声调不同，意思是虚假、不真实。", "价": "价 jià（第四声）与 jiā（第一声）声调不同，意思是价格。", "架": "架 jià（第四声）与 jiā（第一声）声调不同，意思是架子、支架。", "掐": "掐 qiā 与 jiā 声母不同（q 送气，j 不送气），意思是用手指按压。"}, "sentence_index": null, "correct_answer": "家"}, "level_3": {"options": [{"text": "家", "is_correct": true, "explanation": "正确。“他家有三口人”中的“家”指家庭，符合句意。"}, {"text": "车", "is_correct": false, "explanation": "语义：“车”指交通工具，不指家庭，“他车有三口人”不成立。"}, {"text": "班", "is_correct": false, "explanation": "语义：“班”指班级，不能说“他班有三口人，父母和一个弟弟”。"}, {"text": "队", "is_correct": false, "explanation": "语义：“队”指团队，不能指父母和弟弟组成的家庭。"}], "explanations": {"家": "正确。“他家有三口人”中的“家”指家庭，符合句意。", "车": "语义：“车”指交通工具，不指家庭，“他车有三口人”不成立。", "班": "语义：“班”指班级，不能说“他班有三口人，父母和一个弟弟”。", "队": "语义：“队”指团队，不能指父母和弟弟组成的家庭。"}, "sentence_index": 0, "correct_answer": "家"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们在北京有一辆家，很温暖。", "explanation": "这里应该用〈个〉。家作名词时量词用“个”，“辆”只用于车辆，不能用于家。"}, {"text": "她在家的柜台前排队。", "explanation": "这里应该用〈银行〉。“家”指家人共同生活的地方，不能作为办理业务的场所。"}, {"text": "这个家每年生产十万台机器。", "explanation": "这里应该用〈工厂〉。“家”指家人共同生活的地方，不能指生产机器的场所。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e4422ba-ff47-4991-a7ee-68f058b78842') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12453, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "家", "is_correct": true, "explanation": "家（jiā，第一声）：家庭、住所，正确答案。"}, {"text": "江", "is_correct": false, "explanation": "江 jiāng 与 jiā 韵母不同（多了 ng），意思是江河。"}, {"text": "尖", "is_correct": false, "explanation": "尖 jiān 与 jiā 韵母不同（多了 n），意思是尖锐。"}, {"text": "甲", "is_correct": false, "explanation": "甲 jiǎ（第三声）与 jiā（第一声）声调不同，意思是盔甲、指甲等。"}, {"text": "驾", "is_correct": false, "explanation": "驾 jià（第四声）与 jiā（第一声）声调不同，意思是驾驶。"}], "explanations": {"家": "家（jiā，第一声）：家庭、住所，正确答案。", "江": "江 jiāng 与 jiā 韵母不同（多了 ng），意思是江河。", "尖": "尖 jiān 与 jiā 韵母不同（多了 n），意思是尖锐。", "甲": "甲 jiǎ（第三声）与 jiā（第一声）声调不同，意思是盔甲、指甲等。", "驾": "驾 jià（第四声）与 jiā（第一声）声调不同，意思是驾驶。"}, "sentence_index": null, "correct_answer": "家"}, "level_3": {"options": [{"text": "家", "is_correct": true, "explanation": "家：指家庭，“这个家有爸爸、妈妈和我”符合句意。"}, {"text": "城", "is_correct": false, "explanation": "语义：“城”指城市，不能有爸爸、妈妈和我，“这个城有爸爸、妈妈和我”不成立。"}, {"text": "猫", "is_correct": false, "explanation": "语义：“猫”指动物，不能说“这个猫有爸爸、妈妈和我”，与句意矛盾。"}, {"text": "国", "is_correct": false, "explanation": "搭配：“这个国”不成词，应说“这个国家”，且国家不能说有爸爸、妈妈。"}], "explanations": {"家": "家：指家庭，“这个家有爸爸、妈妈和我”符合句意。", "城": "语义：“城”指城市，不能有爸爸、妈妈和我，“这个城有爸爸、妈妈和我”不成立。", "猫": "语义：“猫”指动物，不能说“这个猫有爸爸、妈妈和我”，与句意矛盾。", "国": "搭配：“这个国”不成词，应说“这个国家”，且国家不能说有爸爸、妈妈。"}, "sentence_index": 6, "correct_answer": "家"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们在上海买了一座家，很温暖。", "explanation": "这里应该用〈个〉。“座”多用于山、桥、大楼等大型固定物，不能用于家。"}, {"text": "飞机在家降落。", "explanation": "这里应该用〈机场〉。“家”是家人生活的地方，不能作为飞机降落的场所。"}, {"text": "他们昨天买了一张家。", "explanation": "这里应该用〈个〉。“张”用于纸、桌子等扁平物，不能用于家。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e4422ba-ff47-4991-a7ee-68f058b78842') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12453, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个的家很和睦。", "corrected_sentence": "这个家很和睦。", "error_description": "多出“的”：“这个”后面直接接名词“家”，中间不加“的”，应说“这个家”，不能说“这个的家”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e4422ba-ff47-4991-a7ee-68f058b78842') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12453, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这张家很大。", "corrected_sentence": "这个家很大。", "error_description": "错误形式：“这张家”；正确形式：“这个家”。“家”的量词是“个”，“张”用于纸、桌子等扁平物，不能用于家。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e4422ba-ff47-4991-a7ee-68f058b78842') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
