INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12454, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "爱惜指因重视而不糟蹋、不浪费，常用于对物品、时间、感情等。", "primary_collocate": null, "pronunciation": "ài xī", "ipa": "ai˥˩ ɕi˥", "syllable_count": 2, "sentences": [{"text": "我们要爱惜时间，好好学习。", "target_word": "爱惜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他很爱惜这本旧书。", "target_word": "爱惜", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "奶奶一直很爱惜粮食，一粒米也不浪费。", "target_word": "爱惜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸送我的手表，我一直很爱惜。", "target_word": "爱惜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你应该爱惜自己的身体。", "target_word": "爱惜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他爱惜着这份难得的友情。", "target_word": "爱惜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子很爱惜新买的书包。", "target_word": "爱惜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请爱惜公共的东西。", "target_word": "爱惜", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他很爱惜自己的名声，从不说假话。", "target_word": "爱惜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师爱惜人才，常常帮助学生。", "target_word": "爱惜", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "爱惜了", "label": "体标"}, {"form": "爱惜着", "label": "体标"}, {"form": "爱惜过", "label": "体标"}], "register": "中性", "sense_fingerprint": "爱惜：因重视而不糟蹋、不浪费（物品、时间、感情）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f991c77-0779-429c-842a-f2b0e9d821f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12454, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "爱惜", "is_correct": true, "explanation": "爱惜：重视而不浪费，“我们要爱惜时间，好好学习”符合句意。"}, {"text": "浪费", "is_correct": false, "explanation": "语义：“浪费时间”与“好好学习”的意思相反，句意矛盾。"}, {"text": "挥霍", "is_correct": false, "explanation": "语义：“挥霍”指随意花费，与“好好学习”的要求相反，句意矛盾。"}, {"text": "虚度", "is_correct": false, "explanation": "语义：“虚度时间”表示白白过去，与“好好学习”矛盾。"}], "explanations": {"爱惜": "爱惜：重视而不浪费，“我们要爱惜时间，好好学习”符合句意。", "浪费": "语义：“浪费时间”与“好好学习”的意思相反，句意矛盾。", "挥霍": "语义：“挥霍”指随意花费，与“好好学习”的要求相反，句意矛盾。", "虚度": "语义：“虚度时间”表示白白过去，与“好好学习”矛盾。"}, "sentence_index": 0, "correct_answer": "爱惜"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师爱惜了他迟到的行为。", "explanation": "这里应该用〈批评〉。“爱惜”表示重视而不糟蹋，不能用来表示批评。"}, {"text": "我很爱惜吃这个蛋糕。", "explanation": "这里应该用〈喜欢〉。“爱惜”表示重视而不糟蹋，不能直接用在“吃”这类动作前面表示喜好。"}, {"text": "他故意爱惜了公共长椅。", "explanation": "这里应该用〈毁坏〉。“爱惜”表示重视而不糟蹋，不能用来表示故意破坏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e4422ba-ff47-4991-a7ee-68f058b78842') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12454, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "爱惜", "is_correct": true, "explanation": "爱惜：重视而不糟蹋，“孩子很爱惜新买的书包”符合句意。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”是饮食动作，不能用于书包，句意不通。"}, {"text": "撕", "is_correct": false, "explanation": "语义：“孩子很撕新买的书包”描述的是破坏行为，与句意相反。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”是烹饪动作，不能用于书包，句意不通。"}], "explanations": {"爱惜": "爱惜：重视而不糟蹋，“孩子很爱惜新买的书包”符合句意。", "吃": "语义：“吃”是饮食动作，不能用于书包，句意不通。", "撕": "语义：“孩子很撕新买的书包”描述的是破坏行为，与句意相反。", "煮": "语义：“煮”是烹饪动作，不能用于书包，句意不通。"}, "sentence_index": 6, "correct_answer": "爱惜"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把一大杯水全爱惜了。", "explanation": "这里应该用〈倒掉〉。“爱惜”表示重视而不糟蹋，不能用来表示把东西丢弃。"}, {"text": "这个爱惜很好笑，我们都很喜欢。", "explanation": "这里应该用〈玩笑〉。“爱惜”是表示重视而不糟蹋的动词，不能用来形容有趣与否。"}, {"text": "他很爱惜地摔碎了这块玉。", "explanation": "这里“爱惜”表示重视而不糟蹋，与“摔碎”的破坏性矛盾；如果是不小心，应说〈不小心〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e4422ba-ff47-4991-a7ee-68f058b78842') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12454, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们要爱惜得粮食。", "corrected_sentence": "我们要爱惜粮食。", "error_description": "错误形式：“爱惜得粮食”；正确形式：“爱惜粮食”。“爱惜”后直接带宾语，不能加补语“得”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e4422ba-ff47-4991-a7ee-68f058b78842') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12454, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "请大家爱惜了身边的树木。", "corrected_sentence": "请大家爱惜身边的树木。", "error_description": "错误形式：“爱惜了”；正确形式：“爱惜”。“请”引出的祈使句一般不用“了”，应直接说“爱惜身边的树木”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e4422ba-ff47-4991-a7ee-68f058b78842') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
