INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12456, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "像晴朗天空的颜色。", "primary_collocate": null, "pronunciation": "lán", "ipa": "lan˧˥", "syllable_count": 1, "sentences": [{"text": "看到这个标志，就把可回收的东西放在蓝颜色的垃圾桶里。", "target_word": "蓝", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "今天的天空很蓝。", "target_word": "蓝", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我喜欢那件像天空一样的蓝衬衫。", "target_word": "蓝", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "海水又清又蓝，很漂亮。", "target_word": "蓝", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他的书包是蓝的，像天空一样。", "target_word": "蓝", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "雨后，天空变得更蓝了。", "target_word": "蓝", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妹妹穿着一条像海水一样的蓝裙子。", "target_word": "蓝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这支笔写出来的字像天空一样蓝。", "target_word": "蓝", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她把墙刷成了蓝的，像大海一样。", "target_word": "蓝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "湖水很蓝，周围的山很绿。", "target_word": "蓝", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "蓝色", "label": "复合"}, {"form": "蓝天", "label": "复合"}, {"form": "蓝蓝", "label": "重叠"}, {"form": "藍", "label": "繁体"}], "register": "中性", "sense_fingerprint": "蓝：像晴朗天空的颜色", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f991c77-0779-429c-842a-f2b0e9d821f8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12456, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "蓝", "is_correct": true, "explanation": "蓝（lán）：像晴朗天空的颜色，是本词条的读音与意义。"}, {"text": "男", "is_correct": false, "explanation": "nán 与 lán 声调相同（均为阳平），声母 n 与 l 不同，意思是男人。"}, {"text": "南", "is_correct": false, "explanation": "nán 与 lán 声母不同，意思是南方。"}, {"text": "懒", "is_correct": false, "explanation": "lǎn（上声）与 lán（阳平）声调不同，意思是懒惰。"}, {"text": "烂", "is_correct": false, "explanation": "làn（去声）与 lán（阳平）声调不同，意思是腐烂。"}], "explanations": {"蓝": "蓝（lán）：像晴朗天空的颜色，是本词条的读音与意义。", "男": "nán 与 lán 声调相同（均为阳平），声母 n 与 l 不同，意思是男人。", "南": "nán 与 lán 声母不同，意思是南方。", "懒": "lǎn（上声）与 lán（阳平）声调不同，意思是懒惰。", "烂": "làn（去声）与 lán（阳平）声调不同，意思是腐烂。"}, "sentence_index": null, "correct_answer": "蓝"}, "level_3": {"options": [{"text": "蓝", "is_correct": true, "explanation": "蓝修饰“颜色”，表示像晴朗天空的颜色，与“放在……颜色的垃圾桶里”的句意相符。"}, {"text": "圆", "is_correct": false, "explanation": "语义：圆指形状，不指颜色，不能说“圆颜色”。"}, {"text": "甜", "is_correct": false, "explanation": "语义：“甜”指味道，不能修饰颜色，句意不通。"}, {"text": "硬", "is_correct": false, "explanation": "搭配：“硬”形容质地，不修饰颜色。"}], "explanations": {"蓝": "蓝修饰“颜色”，表示像晴朗天空的颜色，与“放在……颜色的垃圾桶里”的句意相符。", "圆": "语义：圆指形状，不指颜色，不能说“圆颜色”。", "甜": "语义：“甜”指味道，不能修饰颜色，句意不通。", "硬": "搭配：“硬”形容质地，不修饰颜色。"}, "sentence_index": 0, "correct_answer": "蓝"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他抬头看着蓝，陷入了沉思。", "explanation": "这里应该用〈天空〉或〈蓝天〉。“蓝”是形容词，只表示颜色，不能单独指天空。"}, {"text": "我最喜欢这只蓝，它让我觉得很平静。", "explanation": "这里应该用〈种〉。颜色类名词的量词是“种”，不用“只”。"}, {"text": "这篇文章写得很蓝，读起来让人很舒服。", "explanation": "这里应该用〈通顺〉或〈生动〉。在本义项中，“蓝”只指颜色，不用来评价文章的风格。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e4422ba-ff47-4991-a7ee-68f058b78842') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12456, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "蓝", "is_correct": true, "explanation": "蓝（lán）：像晴朗天空的颜色，是本词条的读音与意义。"}, {"text": "难", "is_correct": false, "explanation": "nán（阳平）与 lán（阳平）声调相同，声母 n 与 l 不同，意思是困难。"}, {"text": "狼", "is_correct": false, "explanation": "韵母 an 与 ang 不同（láng），意思是狼。"}, {"text": "滥", "is_correct": false, "explanation": "làn（去声）与 lán（阳平）声调不同，意思是泛滥。"}, {"text": "赖", "is_correct": false, "explanation": "韵母 an 与 ai 不同（lài），意思是赖皮、抵赖。"}], "explanations": {"蓝": "蓝（lán）：像晴朗天空的颜色，是本词条的读音与意义。", "难": "nán（阳平）与 lán（阳平）声调相同，声母 n 与 l 不同，意思是困难。", "狼": "韵母 an 与 ang 不同（láng），意思是狼。", "滥": "làn（去声）与 lán（阳平）声调不同，意思是泛滥。", "赖": "韵母 an 与 ai 不同（lài），意思是赖皮、抵赖。"}, "sentence_index": null, "correct_answer": "蓝"}, "level_3": {"options": [{"text": "蓝", "is_correct": true, "explanation": "蓝修饰“裙子”，表示与“像海水一样”相符的颜色。"}, {"text": "红", "is_correct": false, "explanation": "语义：海水不是红色，与“像海水一样”矛盾。"}, {"text": "紫", "is_correct": false, "explanation": "语义：海水不呈紫色，与“像海水一样”矛盾。"}, {"text": "粉", "is_correct": false, "explanation": "语义：海水不呈粉色，与“像海水一样”矛盾。"}], "explanations": {"蓝": "蓝修饰“裙子”，表示与“像海水一样”相符的颜色。", "红": "语义：海水不是红色，与“像海水一样”矛盾。", "紫": "语义：海水不呈紫色，与“像海水一样”矛盾。", "粉": "语义：海水不呈粉色，与“像海水一样”矛盾。"}, "sentence_index": 6, "correct_answer": "蓝"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他摔了一跤，膝盖蓝了一大片。", "explanation": "这里指淤伤发青，应说〈青〉。“蓝”没有这个义项。"}, {"text": "这个方案很蓝，我们明天就开始做。", "explanation": "这里应该用〈可行〉。“蓝”没有“可行”的意思，这里是误用。"}, {"text": "他的衣服是蓝的，可是他的脾气很蓝。", "explanation": "“蓝”的引申义“忧伤”只用于情绪，不用来形容脾气，这里是词义误用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e4422ba-ff47-4991-a7ee-68f058b78842') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12456, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "窗外是一个蓝天。", "corrected_sentence": "窗外是一片蓝天。", "error_description": "量词错误：“蓝天”指大片的天空，应用量词“片”，不能用“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e4422ba-ff47-4991-a7ee-68f058b78842') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12456, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那片海看起来蓝很。", "corrected_sentence": "那片海看起来很蓝。", "error_description": "语序错误：程度副词“很”应放在形容词“蓝”前面，应说“很蓝”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e4422ba-ff47-4991-a7ee-68f058b78842') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
