INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12460, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "对人或事物有爱护、重视、挂念的感情。", "primary_collocate": null, "pronunciation": "guān xīn", "ipa": "kwan˥ ɕin˥", "syllable_count": 2, "sentences": [{"text": "当时，人们开始关心环境污染问题。", "target_word": "关心", "complexity_tier": "T2", "sentence_source": "mined"}, {"text": "妈妈总是很关心我的学习。", "target_word": "关心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他很关心同事，常常问他们累不累。", "target_word": "关心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "谢谢你关心我，我已经好多了。", "target_word": "关心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师很关心每一个学生的健康。", "target_word": "关心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们应该多关心身边的老人。", "target_word": "关心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他只关心自己的工作，不关心家人。", "target_word": "关心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "奶奶一直关心着我的生活。", "target_word": "关心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不太关心足球比赛的结果。", "target_word": "关心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "邻居们都很关心这位生病的老人。", "target_word": "关心", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "关心了", "label": "体标"}, {"form": "关心着", "label": "体标"}, {"form": "关心关心", "label": "重叠"}, {"form": "關心", "label": "繁体"}], "register": "中性", "sense_fingerprint": "关心：对人或事物爱护、重视、挂念", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42917911-9350-48ef-8d24-179b3d6d9c51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12460, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "关心", "is_correct": true, "explanation": "正确：“关心”表示对环境问题的重视和挂念，与“人们开始……”的语境相符。"}, {"text": "解雇", "is_correct": false, "explanation": "配价：“解雇”的宾语是人，不能用于“环境污染问题”。"}, {"text": "装饰", "is_correct": false, "explanation": "语义：“装饰”指美化物体，与环境污染问题的语义不符。"}, {"text": "夸耀", "is_correct": false, "explanation": "语义：“夸耀”指炫耀自己的长处，用于环境污染问题语义不通。"}], "explanations": {"关心": "正确：“关心”表示对环境问题的重视和挂念，与“人们开始……”的语境相符。", "解雇": "配价：“解雇”的宾语是人，不能用于“环境污染问题”。", "装饰": "语义：“装饰”指美化物体，与环境污染问题的语义不符。", "夸耀": "语义：“夸耀”指炫耀自己的长处，用于环境污染问题语义不通。"}, "sentence_index": 0, "correct_answer": "关心"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "出门前，我关心了一下灯。", "explanation": "这里应该用〈关闭〉。关心表示对人或事物的挂念，不能表示把灯或开关停下来。"}, {"text": "妈妈每天用关心扫房间。", "explanation": "这里应该用〈扫帚〉。“关心”表示挂念，不能当作打扫的工具。"}, {"text": "他周末去关心博物馆。", "explanation": "这里应该用〈参观〉。关心表示对人或事的挂念，不能表示到某个地方去看。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c63ad206-6711-4c57-aa10-a7e5bfa72a30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12460, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "关心", "is_correct": true, "explanation": "正确：“他只关心自己的工作”说明对工作的挂念，与后半句“不关心家人”形成对比。"}, {"text": "掩埋", "is_correct": false, "explanation": "语义：“掩埋”指盖住或埋入，不能用于对工作的挂念。"}, {"text": "拆除", "is_correct": false, "explanation": "搭配：“拆除”的对象是建筑物，不能用于“工作”。"}, {"text": "点燃", "is_correct": false, "explanation": "语义：“点燃”指使物体燃烧，与工作的语义不相容。"}], "explanations": {"关心": "正确：“他只关心自己的工作”说明对工作的挂念，与后半句“不关心家人”形成对比。", "掩埋": "语义：“掩埋”指盖住或埋入，不能用于对工作的挂念。", "拆除": "搭配：“拆除”的对象是建筑物，不能用于“工作”。", "点燃": "语义：“点燃”指使物体燃烧，与工作的语义不相容。"}, "sentence_index": 6, "correct_answer": "关心"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人用关心拧紧了这台机器。", "explanation": "这里应该用〈扳手〉。“关心”表示挂念，不能当作拧螺丝的工具。"}, {"text": "我一眼就关心了他。", "explanation": "这里应该用〈认出〉。关心不表示辨认出某人。"}, {"text": "这个学生关心了三遍课文。", "explanation": "这里应该用〈背诵〉。关心表示心里挂念或重视，不能表示把文字记在脑子里并能复述。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c63ad206-6711-4c57-aa10-a7e5bfa72a30') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
