INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12463, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "否认", "is_correct": true, "explanation": "“承认”与“否认”是反义词，与句中“肯认”的承认之义相对。"}, {"text": "挑选", "is_correct": false, "explanation": "与“认”无反义关系，“挑选”指从多个中选择。"}, {"text": "鼓励", "is_correct": false, "explanation": "与“认”无反义关系，“鼓励”指给人信心或支持。"}, {"text": "收回", "is_correct": false, "explanation": "与“认”无反义关系，“收回”指拿回原先给出的东西。"}], "correct_answer": "否认", "explanations": {"否认": "“承认”与“否认”是反义词，与句中“肯认”的承认之义相对。", "挑选": "与“认”无反义关系，“挑选”指从多个中选择。", "鼓励": "与“认”无反义关系，“鼓励”指给人信心或支持。", "收回": "与“认”无反义关系，“收回”指拿回原先给出的东西。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00acfa89-1445-4ee6-b5cb-064cf11c3dde') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12463, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "表示通过视觉或心理活动识别、接受或承认某人、某物或某种关系。", "primary_collocate": null, "pronunciation": "rèn", "ipa": "ʐən˥˩", "syllable_count": 1, "sentences": [{"text": "这件事是我做的，我认。", "target_word": "认", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不认这笔账，说钱已经还了。", "target_word": "认", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我只认这个牌子，别的都不买。", "target_word": "认", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很小就没了爸爸，后来认了一个干爹。", "target_word": "认", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都认他当我们的队长。", "target_word": "认", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她认我做妹妹，对我特别好。", "target_word": "认", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只狗只认主人，别人叫它也不理。", "target_word": "认", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他欠了钱却不认，大家都很生气。", "target_word": "认", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个规矩我不认，我们换一个。", "target_word": "认", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "只要你肯认，我们就不怪你。", "target_word": "认", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "认了", "label": "体标"}, {"form": "认过", "label": "体标"}, {"form": "认错", "label": "复合"}, {"form": "認", "label": "繁体"}], "register": "中性", "sense_fingerprint": "接受、承认某人、某事或某种关系", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9757e9d-1d75-48ad-ba0e-2752e1a658ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12463, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "认", "is_correct": true, "explanation": "认 rèn，读第四声，意思是承认或认作。"}, {"text": "人", "is_correct": false, "explanation": "rén 与 rèn 声调不同（第二声与第四声），意思是人。"}, {"text": "忍", "is_correct": false, "explanation": "rěn 与 rèn 声调不同（第三声与第四声），意思是忍耐。"}, {"text": "润", "is_correct": false, "explanation": "rùn 与 rèn 韵母不同（-un 与 -en），意思是滋润。"}], "explanations": {"认": "认 rèn，读第四声，意思是承认或认作。", "人": "rén 与 rèn 声调不同（第二声与第四声），意思是人。", "忍": "rěn 与 rèn 声调不同（第三声与第四声），意思是忍耐。", "润": "rùn 与 rèn 韵母不同（-un 与 -en），意思是滋润。"}, "sentence_index": null, "correct_answer": "认"}, "level_3": {"options": [{"text": "认", "is_correct": true, "explanation": "“认”表示承认，与“这件事是我做的”的语境相符。"}, {"text": "反对", "is_correct": false, "explanation": "语义：“这件事是我做的，我反对”前后矛盾，与承认事实不符。"}, {"text": "同意", "is_correct": false, "explanation": "语义：“同意”表示赞成，不能用来表示对自己所做之事的承认。"}, {"text": "批评", "is_correct": false, "explanation": "配价：“批评”需要受事对象，“我批评”后无宾语，且与句意不符。"}], "explanations": {"认": "“认”表示承认，与“这件事是我做的”的语境相符。", "反对": "语义：“这件事是我做的，我反对”前后矛盾，与承认事实不符。", "同意": "语义：“同意”表示赞成，不能用来表示对自己所做之事的承认。", "批评": "配价：“批评”需要受事对象，“我批评”后无宾语，且与句意不符。"}, "sentence_index": 0, "correct_answer": "认"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他认了一整天的书，眼睛都累了。", "explanation": "这里应该用〈读〉。“认”表示通过视觉识别事物，不表示长时间阅读，阅读要说“读书”。"}, {"text": "我们一致认这个方法很好。", "explanation": "这里应该用〈认为〉。“认”单独不能表示“觉得”，要说“认为”。"}, {"text": "他很小就没了爸爸，后来认了一场大病，身体很弱。", "explanation": "这里应该用〈得〉。“认”表示识别或承认，不能和“大病”搭配，患病要说“得”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00acfa89-1445-4ee6-b5cb-064cf11c3dde') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12463, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "认", "is_correct": true, "explanation": "“认”表示承认、接受，与“只认主人，不认别人”的语境相符。"}, {"text": "吃", "is_correct": false, "explanation": "语义：狗“吃”主人不符合常识，与句意不符。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”的对象通常是物品，“洗主人”不自然。"}, {"text": "卖", "is_correct": false, "explanation": "语义：“卖主人”不符合句中“只……不……”的对比，句意荒谬。"}], "explanations": {"认": "“认”表示承认、接受，与“只认主人，不认别人”的语境相符。", "吃": "语义：狗“吃”主人不符合常识，与句意不符。", "洗": "搭配：“洗”的对象通常是物品，“洗主人”不自然。", "卖": "语义：“卖主人”不符合句中“只……不……”的对比，句意荒谬。"}, "sentence_index": 6, "correct_answer": "认"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "只要你肯认一顿饭，我们就不怪你。", "explanation": "这里应该用〈吃〉。“认”表示识别或承认，不能和“一顿饭”搭配，吃饭要说“吃”。"}, {"text": "我们一致认他的方法很好。", "explanation": "这里应该用〈认为〉。“认”单独不能表示“觉得”。"}, {"text": "大家都为他认了一个生日，气氛很热闹。", "explanation": "这里应该用〈过〉。“认”表示识别或承认，不能和“生日”搭配，庆祝生日要说“过生日”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00acfa89-1445-4ee6-b5cb-064cf11c3dde') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12463, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他终于错了认，大家都松了一口气。", "corrected_sentence": "他终于认了错，大家都松了一口气。", "error_description": "语序错误：“认错”是动宾结构，“认”在前、“错”在后，不能说“错了认”，应说“认了错”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00acfa89-1445-4ee6-b5cb-064cf11c3dde') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12463, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他不认了错，大家都很生气。", "corrected_sentence": "他不认错了，大家都很生气。", "error_description": "“了”位置错误：“认错”是动宾词，“了”不能插在“认”和“错”中间；否定时应说“不认错了”，表示不再认错。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00acfa89-1445-4ee6-b5cb-064cf11c3dde') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
