INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12464, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "图案指由线条、形状、颜色等构成的、用于装饰或表示的图形。", "primary_collocate": null, "pronunciation": "tú àn", "ipa": "tʰu˧˥ an˥˩", "syllable_count": 2, "sentences": [{"text": "为了鼓励大家分类垃圾，一位设计师画了这个简单又容易认的图案。", "target_word": "图案", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "这件衣服上有一个可爱的小熊图案。", "target_word": "图案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她喜欢买有花图案的杯子。", "target_word": "图案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地毯上的图案是用红色和黄色画的。", "target_word": "图案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个图案由线条和圆圈组成。", "target_word": "图案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "设计师在盘子上画了一个新图案。", "target_word": "图案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "墙上的图案看起来像一只鸟。", "target_word": "图案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你想在帽子上印什么图案？", "target_word": "图案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块布的图案很漂亮，颜色也好看。", "target_word": "图案", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在纸上画了很多有趣的图案。", "target_word": "图案", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "种", "label": "量词"}, {"form": "圖案", "label": "繁体"}], "register": "中性", "sense_fingerprint": "由线条、形状、颜色构成的装饰或标识图形", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9757e9d-1d75-48ad-ba0e-2752e1a658ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12464, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "图案", "is_correct": true, "explanation": "正确：图案指由线条、形状构成的图形，设计师画出“简单又容易认”的图形正是图案。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“画”的对象是可见的图形，味道不能被画出来。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：歌曲是声音作品，不是可以画出来的图形，与“容易认”的图形义也不搭。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格是金额，不能被画出来，也不是能被“认”出的图形。"}], "explanations": {"图案": "正确：图案指由线条、形状构成的图形，设计师画出“简单又容易认”的图形正是图案。", "味道": "搭配：“画”的对象是可见的图形，味道不能被画出来。", "歌曲": "语义：歌曲是声音作品，不是可以画出来的图形，与“容易认”的图形义也不搭。", "价格": "语义：价格是金额，不能被画出来，也不是能被“认”出的图形。"}, "sentence_index": 0, "correct_answer": "图案"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他们制定了一个新图案，准备下个月实施。", "explanation": "这里应该用〈方案〉。图案指装饰或标识性的图样，制定计划、方案时不能用图案，应说“方案”。"}, {"text": "医生在屏幕上看到了清晰的图案，判断病人的肺没有问题。", "explanation": "这里应该用〈图像〉。图像指X光、扫描等得到的影像，图案是装饰或标识性图样，不能指医学影像。"}, {"text": "他用一个新图案算出了今天的税额。", "explanation": "这里应该用〈公式〉。图案是装饰或标识性图样，不能用来计算，算税额要用“公式”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00acfa89-1445-4ee6-b5cb-064cf11c3dde') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12464, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "图案", "is_correct": true, "explanation": "正确：墙上的图案是绘制的图形，看起来像一只鸟，符合语境。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：声音不能附着在墙上，也不能“看起来像一只鸟”。"}, {"text": "温度", "is_correct": false, "explanation": "语义：温度是数值，没有可以“看起来像”的形状。"}, {"text": "价钱", "is_correct": false, "explanation": "配价：“看起来像”要求有形体的主语，价钱不能充当这个主语。"}], "explanations": {"图案": "正确：墙上的图案是绘制的图形，看起来像一只鸟，符合语境。", "声音": "搭配：声音不能附着在墙上，也不能“看起来像一只鸟”。", "温度": "语义：温度是数值，没有可以“看起来像”的形状。", "价钱": "配价：“看起来像”要求有形体的主语，价钱不能充当这个主语。"}, "sentence_index": 6, "correct_answer": "图案"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这张图案显示了今年每个月的销售额。", "explanation": "这里应该用〈图表〉。图表用于展示数据，图案是装饰或标识性图样，不能用来显示销售额。"}, {"text": "工程师看了这张图案，决定加固大楼的结构。", "explanation": "这里应该用〈图纸〉。图纸用于工程设计，图案不用于技术性的结构设计。"}, {"text": "这部小说的图案很复杂，读者需要仔细推理才能看懂。", "explanation": "这里应该用〈情节〉。图案指装饰或标识性的图样，不能指小说中的故事发展，说“情节很复杂”才对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00acfa89-1445-4ee6-b5cb-064cf11c3dde') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12464, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条围巾上织着两只漂亮的图案。", "corrected_sentence": "这条围巾上织着两个漂亮的图案。", "error_description": "量词错误：“图案”应用“个”计量，“只”用于动物等，不能用来计量图案。正确说法是“两个漂亮的图案”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00acfa89-1445-4ee6-b5cb-064cf11c3dde') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12464, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这块围裙上的图案绣很精致。", "corrected_sentence": "这块围裙上的图案绣得很精致。", "error_description": "补语结构错误：表示程度的补语前必须加“得”，“绣很精致”不成立，应为“绣得很精致”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00acfa89-1445-4ee6-b5cb-064cf11c3dde') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12467, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00acfa89-1445-4ee6-b5cb-064cf11c3dde') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
