INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12467, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指过去使用过的、已经不再新或不再常用的物品。", "primary_collocate": null, "pronunciation": "jiù wù", "ipa": "tɕjou˥˩ u˥˩", "syllable_count": 2, "sentences": [{"text": "第一个箭头是减少扔掉的东西，第二个是把旧物再用，第三个是把垃圾变成新东西。", "target_word": "旧物", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "奶奶家的阁楼里放着很多旧物。", "target_word": "旧物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把不用的旧物送给了朋友。", "target_word": "旧物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "搬家以前，我们先整理了旧物。", "target_word": "旧物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些旧物虽然不新，但是很有用。", "target_word": "旧物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小区里有地方回收旧物。", "target_word": "旧物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喜欢在周末去市场买旧物。", "target_word": "旧物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈用旧物做了一个漂亮的花盆。", "target_word": "旧物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件旧物是爷爷留下来的。", "target_word": "旧物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子长大了，我们把旧物捐给了需要的人。", "target_word": "旧物", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "件", "label": "量词"}, {"form": "旧物改造", "label": "复合"}, {"form": "舊物", "label": "繁体"}], "register": "通用", "sense_fingerprint": "不再新、不常用的旧东西，可整理、回收或再利用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd9757e9d-1d75-48ad-ba0e-2752e1a658ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12467, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "旧物", "is_correct": true, "explanation": "正确：旧物指已不新、不常用的旧东西，“把旧物再用”即重新利用，与箭头说明一致。"}, {"text": "美食", "is_correct": false, "explanation": "语义：美食是可以吃的食物，不是可以“再用”的物品。"}, {"text": "新品", "is_correct": false, "explanation": "语义：新品指新出的产品，与“再用”的旧物相反，与“减少扔掉”的语境矛盾。"}, {"text": "宠物", "is_correct": false, "explanation": "搭配：“再用”不能用于宠物，宠物是生命，不能像物品那样被再利用。"}], "explanations": {"旧物": "正确：旧物指已不新、不常用的旧东西，“把旧物再用”即重新利用，与箭头说明一致。", "美食": "语义：美食是可以吃的食物，不是可以“再用”的物品。", "新品": "语义：新品指新出的产品，与“再用”的旧物相反，与“减少扔掉”的语境矛盾。", "宠物": "搭配：“再用”不能用于宠物，宠物是生命，不能像物品那样被再利用。"}, "sentence_index": 0, "correct_answer": "旧物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在同学聚会上见到了很多旧物，大家都很开心。", "explanation": "这里应该用〈老朋友〉。旧物指过去用过的物品，不能指以前认识的人，见老朋友应说“老朋友”。"}, {"text": "这次地震的旧物非常严重，很多房子都倒了。", "explanation": "这里应该用〈灾情〉。“旧物”指过去用过的物品，不能指地震造成的破坏，描述灾情应说“灾情”。"}, {"text": "我奶奶年纪大了，已经是旧物了，身体不太好。", "explanation": "这里应该用〈老人〉或〈年老〉。旧物指过去用过的东西，不能指人；说人年纪大要用“老”或“老人”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00acfa89-1445-4ee6-b5cb-064cf11c3dde') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12467, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "旧物", "is_correct": true, "explanation": "正确：旧物是过去用过、不再新的物品，“去市场买旧物”符合二手市场的语境。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“买”的对象是商品，空气不能用“买”。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是气象状况，不是可以购买的东西。"}, {"text": "节日", "is_correct": false, "explanation": "语义：节日是时间段，不是商品，不能去市场买。"}], "explanations": {"旧物": "正确：旧物是过去用过、不再新的物品，“去市场买旧物”符合二手市场的语境。", "空气": "搭配：“买”的对象是商品，空气不能用“买”。", "天气": "语义：天气是气象状况，不是可以购买的东西。", "节日": "语义：节日是时间段，不是商品，不能去市场买。"}, "sentence_index": 6, "correct_answer": "旧物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次考试他犯了很多旧物。", "explanation": "这里应该用〈错误〉。旧物指过去用过的物品，不能被“犯”，犯错误应说“错误”。"}, {"text": "父亲去世后，他的旧物是我一直想继承的事业。", "explanation": "这里应该用〈事业〉。旧物指过去用过的物品，不能指需要继承的事业。"}, {"text": "妈妈的旧物是一首很好听的歌。", "explanation": "这里应该用〈歌曲〉。“旧物”指过去用过的物品，不能指一首歌，应说“歌曲”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00acfa89-1445-4ee6-b5cb-064cf11c3dde') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12467, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我在箱子里找到一条旧物。", "corrected_sentence": "我在箱子里找到一件旧物。", "error_description": "量词错误：“旧物”应用“件”计量，“条”用于细长物，不能用来计量旧物。正确说法是“一件旧物”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00acfa89-1445-4ee6-b5cb-064cf11c3dde') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12467, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那家店把旧物卖很便宜。", "corrected_sentence": "那家店把旧物卖得很便宜。", "error_description": "补语结构错误：表示程度的补语前必须加“得”，“卖很便宜”不成立，应为“卖得很便宜”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00acfa89-1445-4ee6-b5cb-064cf11c3dde') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
