INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12477, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "指涉及或影响全世界各个国家和地区的性质或现象。", "primary_collocate": null, "pronunciation": "quán qiú xìng", "ipa": "tɕʰɥɛn˧˥ tɕʰiou˧˥ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "20世纪中叶，随着工业化进程的加速与消费主义的兴起，废物管理问题逐渐成为全球性挑战。", "target_word": "全球性", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "气候变化是一个全球性问题。", "target_word": "全球性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次疫情有很强的全球性。", "target_word": "全球性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要共同面对全球性的挑战。", "target_word": "全球性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经济危机的全球性让每个国家都受到影响。", "target_word": "全球性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海洋污染是全球性的环境问题。", "target_word": "全球性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家们在北京讨论全球性的粮食问题。", "target_word": "全球性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都知道，疫情具有全球性。", "target_word": "全球性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，环保是一个全球性的话题。", "target_word": "全球性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种病毒的全球性传播让医院很忙。", "target_word": "全球性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "涉及或影响全世界各国的性质，常作定语，如全球性问题、全球性挑战", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63007dea-14d8-4e2d-8986-b9c20904b4ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12477, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "全球性", "is_correct": true, "explanation": "全球性修饰“挑战”，指影响遍及全世界，与句中工业化和消费主义这类全球性趋势相合。"}, {"text": "地方性", "is_correct": false, "explanation": "语义：句中讲的是席卷各地的普遍趋势，“地方性”指局限于某一地方，与之矛盾。"}, {"text": "突发性", "is_correct": false, "explanation": "语义：“突发性”指突然出现，与句中“逐渐成为”所表示的渐进过程不符。"}, {"text": "偶然性", "is_correct": false, "explanation": "搭配：“偶然性”说的是事情发生的随机性，不用来修饰“挑战”这类有规模的对象。"}], "explanations": {"全球性": "全球性修饰“挑战”，指影响遍及全世界，与句中工业化和消费主义这类全球性趋势相合。", "地方性": "语义：句中讲的是席卷各地的普遍趋势，“地方性”指局限于某一地方，与之矛盾。", "突发性": "语义：“突发性”指突然出现，与句中“逐渐成为”所表示的渐进过程不符。", "偶然性": "搭配：“偶然性”说的是事情发生的随机性，不用来修饰“挑战”这类有规模的对象。"}, "sentence_index": 0, "correct_answer": "全球性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们小区的停车问题是全球性的。", "explanation": "这里用错了范围。“全球性”指影响遍及全世界，小区的停车问题只限于一个小区，应说“地方性”。"}, {"text": "我们班的一次小测验是全球性的。", "explanation": "这里用错了范围。小测验只在班里进行，远没有全世界的范围，应说“班内的”。"}, {"text": "这家小面馆的名气是全球性的。", "explanation": "这里用错了范围。小面馆只在本地有名，名气没有遍及全世界，应说“地方性”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20915f57-310d-4435-8f8b-d9051973edfe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12477, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "全球性", "is_correct": true, "explanation": "全球性修饰“粮食问题”，指问题影响全世界，与“专家们讨论”的范围相合。"}, {"text": "个人性", "is_correct": false, "explanation": "语义：“个人性”指只涉及个人，与“专家们在北京讨论”的公共议题相矛盾。"}, {"text": "家族性", "is_correct": false, "explanation": "语义：“家族性”指限于一个家族的范围，与句中讨论的粮食问题不符。"}, {"text": "随机性", "is_correct": false, "explanation": "搭配：“随机性”说的是事情出现的不确定性，粮食问题是长期结构性的，不用这个词修饰。"}], "explanations": {"全球性": "全球性修饰“粮食问题”，指问题影响全世界，与“专家们讨论”的范围相合。", "个人性": "语义：“个人性”指只涉及个人，与“专家们在北京讨论”的公共议题相矛盾。", "家族性": "语义：“家族性”指限于一个家族的范围，与句中讨论的粮食问题不符。", "随机性": "搭配：“随机性”说的是事情出现的不确定性，粮食问题是长期结构性的，不用这个词修饰。"}, "sentence_index": 6, "correct_answer": "全球性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "世界经济正在走向全球性。", "explanation": "这里应该用〈全球化〉。“走向”后接的是过程，“全球化”指走向全球的进程；“全球性”只表示事物的范围性质。"}, {"text": "我们的复习内容很全球性，每一课都复习到了。", "explanation": "这里应该用〈全面〉。“全球性”指影响遍及全世界，复习内容的完整要用“全面”，不能用“全球性”。"}, {"text": "这位同学的性格很全球性。", "explanation": "这里误把〈全球性〉当成描写性格的词。“全球性”只说事情或现象的影响范围遍及全世界，形容人的性格应改用〈开朗〉之类的词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20915f57-310d-4435-8f8b-d9051973edfe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12477, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是一项很全球性的任务。", "corrected_sentence": "这是一项全球性的任务。", "error_description": "错误形式“很全球性的任务”。“全球性”修饰名词时前面不能再加程度副词“很”，应去掉“很”，改为“全球性的任务”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20915f57-310d-4435-8f8b-d9051973edfe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12477, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个问题全球性的。", "corrected_sentence": "这个问题是全球性的。", "error_description": "错误形式“这个问题全球性的”，正确形式“这个问题是全球性的”。“全球性的”作谓语时，前面要加“是”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20915f57-310d-4435-8f8b-d9051973edfe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12478, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "冗长", "is_correct": true, "explanation": "冗长与“简洁”相反，指话语或文字过长、不精炼。"}, {"text": "繁忙", "is_correct": false, "explanation": "繁忙指事情多、忙碌，与话语或文章的简繁无关。"}, {"text": "响亮", "is_correct": false, "explanation": "响亮形容声音大而清楚，与表达的简繁无关。"}, {"text": "柔和", "is_correct": false, "explanation": "柔和形容温和、不刺激，与表达的简繁无关。"}], "correct_answer": "冗长", "explanations": {"冗长": "冗长与“简洁”相反，指话语或文字过长、不精炼。", "繁忙": "繁忙指事情多、忙碌，与话语或文章的简繁无关。", "响亮": "响亮形容声音大而清楚，与表达的简繁无关。", "柔和": "柔和形容温和、不刺激，与表达的简繁无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20915f57-310d-4435-8f8b-d9051973edfe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12478, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20915f57-310d-4435-8f8b-d9051973edfe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12478, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指（说话、写文章或事物本身）简明扼要，没有多余的内容。", "primary_collocate": null, "pronunciation": "jiǎn jié", "ipa": "tɕjɛn˨˩˦ tɕjɛ˧˥", "syllable_count": 2, "sentences": [{"text": "在此背景下，一个简洁而富有深意的视觉符号应运而生——三箭头循环标志，它不仅成为现代环保主义的图腾，更承载了人类对可持续发展的集体渴望。", "target_word": "简洁", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "老师的讲话很简洁。", "target_word": "简洁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这篇文章写得简洁，也很清楚。", "target_word": "简洁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你用简洁的话说一下你的想法。", "target_word": "简洁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的回答简洁有力。", "target_word": "简洁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份报告太长了，应该写得更简洁。", "target_word": "简洁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司的介绍要简洁，不要写太多。", "target_word": "简洁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他发的短信总是很简洁。", "target_word": "简洁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这句话说得很简洁，大家都听懂了。", "target_word": "简洁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "写信时语言要简洁一点。", "target_word": "简洁", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "说话、文章、表达简明扼要，没有多余的话", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63007dea-14d8-4e2d-8986-b9c20904b4ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12478, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "简洁", "is_correct": true, "explanation": "jiǎn jié，指说话或写文章简明扼要，没有多余的话。"}, {"text": "简介", "is_correct": false, "explanation": "jié 与 jiè 声调不同（第二声与第四声），意思是简要的介绍。"}, {"text": "间接", "is_correct": false, "explanation": "jiǎn 与 jiàn、jié 与 jiē 声调都不同，意思是不直接。"}, {"text": "紧接", "is_correct": false, "explanation": "jiǎn 与 jǐn 只差一个元音 a（jiǎn 为 ian，jǐn 为 in），意思是紧跟着。"}], "explanations": {"简洁": "jiǎn jié，指说话或写文章简明扼要，没有多余的话。", "简介": "jié 与 jiè 声调不同（第二声与第四声），意思是简要的介绍。", "间接": "jiǎn 与 jiàn、jié 与 jiē 声调都不同，意思是不直接。", "紧接": "jiǎn 与 jǐn 只差一个元音 a（jiǎn 为 ian，jǐn 为 in），意思是紧跟着。"}, "sentence_index": null, "correct_answer": "简洁"}, "level_3": {"options": [{"text": "简洁", "is_correct": true, "explanation": "简洁修饰“视觉符号”，指形式简明，与“富有深意”搭配自然。"}, {"text": "冗长", "is_correct": false, "explanation": "语义：“冗长”指篇幅过长，与“视觉符号”的凝练形象矛盾。"}, {"text": "啰嗦", "is_correct": false, "explanation": "语域：“啰嗦”口语色彩较重，与这句书面语的语气不符。"}, {"text": "杂乱", "is_correct": false, "explanation": "语义：“杂乱”指纷乱无序，与“富有深意”的凝练意味不符。"}], "explanations": {"简洁": "简洁修饰“视觉符号”，指形式简明，与“富有深意”搭配自然。", "冗长": "语义：“冗长”指篇幅过长，与“视觉符号”的凝练形象矛盾。", "啰嗦": "语域：“啰嗦”口语色彩较重，与这句书面语的语气不符。", "杂乱": "语义：“杂乱”指纷乱无序，与“富有深意”的凝练意味不符。"}, "sentence_index": 0, "correct_answer": "简洁"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这道菜的味道很简洁。", "explanation": "这里应该用〈鲜〉或〈香〉之类形容味道的词。“简洁”形容说话、写文章或事物简明扼要，不能用来形容味道。"}, {"text": "他很简洁地跑完了一百米。", "explanation": "这里应该用〈快〉之类形容速度的词。“简洁”只形容说话、写文章等表达方式，不能形容跑步的速度。"}, {"text": "他这次的考试成绩很简洁。", "explanation": "这里应该用〈好〉或〈高〉之类形容成绩的词。“简洁”形容说话或文章不啰嗦，不能用来形容成绩。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20915f57-310d-4435-8f8b-d9051973edfe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12478, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "简洁", "is_correct": true, "explanation": "jiǎn jié，指说话或写文章简明扼要，没有多余的话。"}, {"text": "减价", "is_correct": false, "explanation": "jié 与 jià 韵母不同（ie 与 ia），意思是降低价格。"}, {"text": "剪接", "is_correct": false, "explanation": "jié 与 jiē 声调不同，意思是把影片剪开再接起来。"}, {"text": "剪辑", "is_correct": false, "explanation": "jié 与 jí 韵母不同（ie 与 i），意思是对影片或录音进行剪裁编辑。"}], "explanations": {"简洁": "jiǎn jié，指说话或写文章简明扼要，没有多余的话。", "减价": "jié 与 jià 韵母不同（ie 与 ia），意思是降低价格。", "剪接": "jié 与 jiē 声调不同，意思是把影片剪开再接起来。", "剪辑": "jié 与 jí 韵母不同（ie 与 i），意思是对影片或录音进行剪裁编辑。"}, "sentence_index": null, "correct_answer": "简洁"}, "level_3": {"options": [{"text": "简洁", "is_correct": true, "explanation": "简洁修饰“介绍”，指不啰嗦，与“不要写太多”相合。"}, {"text": "详细", "is_correct": false, "explanation": "语义：“详细”指内容周全，与“不要写太多”的要求相反。"}, {"text": "凌乱", "is_correct": false, "explanation": "语义：“凌乱”指杂乱无序，与“简洁”的要求相反，不能用来要求介绍。"}, {"text": "繁杂", "is_correct": false, "explanation": "语义：“繁杂”指头绪多，与“不要写太多”的要求冲突。"}], "explanations": {"简洁": "简洁修饰“介绍”，指不啰嗦，与“不要写太多”相合。", "详细": "语义：“详细”指内容周全，与“不要写太多”的要求相反。", "凌乱": "语义：“凌乱”指杂乱无序，与“简洁”的要求相反，不能用来要求介绍。", "繁杂": "语义：“繁杂”指头绪多，与“不要写太多”的要求冲突。"}, "sentence_index": 6, "correct_answer": "简洁"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次演出的时间很简洁，只有十分钟。", "explanation": "这里应该用〈简短〉。“简洁”形容说话或文章不啰嗦，时间的长短要用“简短”。"}, {"text": "今天的天气很简洁。", "explanation": "这里应该用〈晴朗〉之类形容天气的词。“简洁”形容说话、写文章或说明简明扼要，不能用来形容天气。"}, {"text": "这栋楼的价钱很简洁。", "explanation": "这里应该用〈便宜〉或〈贵〉之类形容价钱的词。“简洁”形容说话或文章不啰嗦，不能用来形容价钱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20915f57-310d-4435-8f8b-d9051973edfe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12478, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他简洁的回答了问题。", "corrected_sentence": "他简洁地回答了问题。", "error_description": "错误形式“简洁的回答”，正确形式“简洁地回答”。“简洁”修饰动词“回答”时要用“地”，“的”只用于修饰名词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20915f57-310d-4435-8f8b-d9051973edfe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12478, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他写很简洁。", "corrected_sentence": "他写得很简洁。", "error_description": "错误形式“写很简洁”，正确形式“写得很简洁”。“简洁”作补语说明“写”的状态，动词和补语之间要用“得”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20915f57-310d-4435-8f8b-d9051973edfe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12479, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "贫穷", "is_correct": true, "explanation": "“富有”的反义词，指没有钱或财产。"}, {"text": "聪明", "is_correct": false, "explanation": "不是反义词：“聪明”指头脑灵活，与财富无关。"}, {"text": "美丽", "is_correct": false, "explanation": "不是反义词：“美丽”形容外貌好看，与财产无关。"}, {"text": "安静", "is_correct": false, "explanation": "不是反义词：“安静”指没有声音、不吵闹，与财富无关。"}], "correct_answer": "贫穷", "explanations": {"贫穷": "“富有”的反义词，指没有钱或财产。", "聪明": "不是反义词：“聪明”指头脑灵活，与财富无关。", "美丽": "不是反义词：“美丽”形容外貌好看，与财产无关。", "安静": "不是反义词：“安静”指没有声音、不吵闹，与财富无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20915f57-310d-4435-8f8b-d9051973edfe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12479, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "贫困", "is_correct": true, "explanation": "“富有”的反义词，指缺少钱财、生活困难。"}, {"text": "温柔", "is_correct": false, "explanation": "不是反义词：“温柔”形容性情和气，与财富无关。"}, {"text": "冷静", "is_correct": false, "explanation": "不是反义词：“冷静”形容情绪稳定，与财富无关。"}, {"text": "亲切", "is_correct": false, "explanation": "不是反义词：“亲切”形容态度温和、让人感到近，与财富无关。"}], "correct_answer": "贫困", "explanations": {"贫困": "“富有”的反义词，指缺少钱财、生活困难。", "温柔": "不是反义词：“温柔”形容性情和气，与财富无关。", "冷静": "不是反义词：“冷静”形容情绪稳定，与财富无关。", "亲切": "不是反义词：“亲切”形容态度温和、让人感到近，与财富无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20915f57-310d-4435-8f8b-d9051973edfe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12479, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "拥有大量的金钱、物质或资源。", "primary_collocate": null, "pronunciation": "fù yǒu", "ipa": "fu˥˩ jou˨˩˦", "syllable_count": 2, "sentences": [{"text": "他的家庭很富有。", "target_word": "富有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家很富有，人们生活得好。", "target_word": "富有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是一个富有的商人。", "target_word": "富有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "富有的人也要努力工作。", "target_word": "富有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他年轻时不富有，现在很富有了。", "target_word": "富有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的爸爸很富有，买了一套大房子。", "target_word": "富有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们家虽然富有，但是生活很简单。", "target_word": "富有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的朋友出生在一个富有的家庭。", "target_word": "富有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她嫁给了一位富有的老板。", "target_word": "富有", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "石油让这个小国变得富有。", "target_word": "富有", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "人、家庭、国家拥有大量金钱、财产或资源，生活富足", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63007dea-14d8-4e2d-8986-b9c20904b4ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12479, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "富有", "is_correct": true, "explanation": "正确答案：fù yǒu，指拥有大量金钱或资源。"}, {"text": "互有", "is_correct": false, "explanation": "hù 与 fù 声母不同（h／f），意思是互相拥有，与“富有”不同。"}, {"text": "固有", "is_correct": false, "explanation": "gù 与 fù 声母不同（g／f），意思是本来就有，与“富有”不同。"}, {"text": "复又", "is_correct": false, "explanation": "yòu 与 yǒu 声调不同（第四声与第三声），意思是又、再一次，与“富有”不同。"}], "explanations": {"富有": "正确答案：fù yǒu，指拥有大量金钱或资源。", "互有": "hù 与 fù 声母不同（h／f），意思是互相拥有，与“富有”不同。", "固有": "gù 与 fù 声母不同（g／f），意思是本来就有，与“富有”不同。", "复又": "yòu 与 yǒu 声调不同（第四声与第三声），意思是又、再一次，与“富有”不同。"}, "sentence_index": null, "correct_answer": "富有"}, "level_3": {"options": [{"text": "富有", "is_correct": true, "explanation": "与“很”搭配，形容家庭拥有大量财产，符合句意。"}, {"text": "聪明", "is_correct": false, "explanation": "语义：“聪明”形容人的智力，不能用来形容家庭。"}, {"text": "高", "is_correct": false, "explanation": "体貌：“高”形容人或物的身高、高度，不用来形容家庭。"}, {"text": "害羞", "is_correct": false, "explanation": "语义：“害羞”形容人的心理状态，不能用来形容家庭。"}], "explanations": {"富有": "与“很”搭配，形容家庭拥有大量财产，符合句意。", "聪明": "语义：“聪明”形容人的智力，不能用来形容家庭。", "高": "体貌：“高”形容人或物的身高、高度，不用来形容家庭。", "害羞": "语义：“害羞”形容人的心理状态，不能用来形容家庭。"}, "sentence_index": 0, "correct_answer": "富有"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个月他的工资富有了。", "explanation": "这里应该用〈增加〉。富有形容人或家庭拥有大量钱财，工资数额变多要用增加。"}, {"text": "这次比赛的奖品很富有。", "explanation": "这里应该用〈丰厚〉。富有形容人或家庭拥有的钱财，奖品、报酬的数额要用丰厚。"}, {"text": "这个国家的工业很富有。", "explanation": "这里应该用〈发达〉。富有指人或家庭的财富，工业的兴旺要用发达。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20915f57-310d-4435-8f8b-d9051973edfe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12479, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "富有", "is_correct": true, "explanation": "与“虽然……但是”呼应，表示家境富足，与“生活很简单”形成对比。"}, {"text": "瘦", "is_correct": false, "explanation": "体貌：“瘦”形容人的体型，不用来形容一家的状况。"}, {"text": "勇敢", "is_correct": false, "explanation": "语义：“勇敢”是人的品质，不能用来形容家庭。"}, {"text": "饿", "is_correct": false, "explanation": "语义：“饿”指人的生理需要，家庭不能说饿。"}], "explanations": {"富有": "与“虽然……但是”呼应，表示家境富足，与“生活很简单”形成对比。", "瘦": "体貌：“瘦”形容人的体型，不用来形容一家的状况。", "勇敢": "语义：“勇敢”是人的品质，不能用来形容家庭。", "饿": "语义：“饿”指人的生理需要，家庭不能说饿。"}, "sentence_index": 6, "correct_answer": "富有"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这所学校的教学质量富有了。", "explanation": "这里应该用〈提高〉。富有形容人或家庭的财富，教学质量这类水平要用提高。"}, {"text": "这家公司的年纪很富有。", "explanation": "这里应该用〈长〉。富有指拥有的财富多，公司成立的年数要用“长”。"}, {"text": "这家公司的规模富有了。", "explanation": "这里应该用〈扩大〉。富有说人或家庭的财富，公司规模的扩张要用扩大。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20915f57-310d-4435-8f8b-d9051973edfe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12479, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那位商人在当地很富有钱。", "corrected_sentence": "那位商人在当地很富有。", "error_description": "错误形式“很富有钱”，正确形式“很富有”。“富有”是形容词，后面不能直接带名词“钱”作宾语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20915f57-310d-4435-8f8b-d9051973edfe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12479, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个村子在改革以后变很富有。", "corrected_sentence": "这个村子在改革以后变得很富有。", "error_description": "错误形式“变很富有”，正确形式“变得很富有”。“变得”后接形容词作补语，“得”不能省略。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20915f57-310d-4435-8f8b-d9051973edfe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
