INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12480, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指深刻、含蓄的意义或内涵。", "primary_collocate": null, "pronunciation": "shēn yì", "ipa": "ʂən˥ i˥˩", "syllable_count": 2, "sentences": [{"text": "在此背景下，一个简洁而富有深意的视觉符号应运而生——三箭头循环标志，它不仅成为现代环保主义的图腾，更承载了人类对可持续发展的集体渴望。", "target_word": "深意", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这首诗很短，却藏着深意。", "target_word": "深意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你能看懂这幅画的深意吗？", "target_word": "深意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个故事的深意，孩子慢慢才会懂。", "target_word": "深意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个名字有深意，不是随便取的。", "target_word": "深意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "读完这篇文章，我明白了作者的深意。", "target_word": "深意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他送我这本旧书，一定有深意。", "target_word": "深意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这幅画的颜色很简单，却有一层深意。", "target_word": "深意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座老房子的每扇窗户都有深意。", "target_word": "深意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "导演在电影的最后一幕里留下了深意。", "target_word": "深意", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "层", "label": "量词"}], "register": "书面", "sense_fingerprint": "作品、符号、故事等所包含的深刻而含蓄的意义", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63007dea-14d8-4e2d-8986-b9c20904b4ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12480, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "深意", "is_correct": true, "explanation": "正确答案：shēn yì，指深刻、含蓄的意义或内涵。"}, {"text": "真意", "is_correct": false, "explanation": "zhēn 与 shēn 声母不同（zh／sh），意思是真实的意图，与“深意”不同。"}, {"text": "生意", "is_correct": false, "explanation": "shēng 与 shēn 韵尾不同（ng／n），意思是买卖或生计，与“深意”不同。"}, {"text": "深夜", "is_correct": false, "explanation": "yè 与 yì 韵母不同（e／i），意思是夜深的时候，与“深意”不同。"}], "explanations": {"深意": "正确答案：shēn yì，指深刻、含蓄的意义或内涵。", "真意": "zhēn 与 shēn 声母不同（zh／sh），意思是真实的意图，与“深意”不同。", "生意": "shēng 与 shēn 韵尾不同（ng／n），意思是买卖或生计，与“深意”不同。", "深夜": "yè 与 yì 韵母不同（e／i），意思是夜深的时候，与“深意”不同。"}, "sentence_index": null, "correct_answer": "深意"}, "level_3": {"options": [{"text": "深意", "is_correct": true, "explanation": "与“富有”搭配，指作品中深刻含蓄的内涵，符合句意。"}, {"text": "体温", "is_correct": false, "explanation": "语义：“体温”是生理指标，不能被“富有”修饰。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“富有”后接抽象的内涵，不能接“价格”。"}, {"text": "寿命", "is_correct": false, "explanation": "搭配：“富有”后不接“寿命”这类时间概念。"}], "explanations": {"深意": "与“富有”搭配，指作品中深刻含蓄的内涵，符合句意。", "体温": "语义：“体温”是生理指标，不能被“富有”修饰。", "价格": "搭配：“富有”后接抽象的内涵，不能接“价格”。", "寿命": "搭配：“富有”后不接“寿命”这类时间概念。"}, "sentence_index": 0, "correct_answer": "深意"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这盏灯的深意很亮。", "explanation": "这里应该用〈亮度〉。深意指作品或话语中的深刻内涵，灯光的明亮程度要用亮度。"}, {"text": "这种药的深意很大。", "explanation": "这里应该用〈作用〉。深意指作品或符号中深刻含蓄的内涵，药物的效果要说作用。"}, {"text": "这口井的深意很大。", "explanation": "这里应该用〈深度〉。深意指抽象的内涵，井的深浅要用深度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20915f57-310d-4435-8f8b-d9051973edfe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12480, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "深意", "is_correct": true, "explanation": "与“一定有”搭配，书中藏着深刻的内涵，符合句意。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：“脾气”是人的性格，书不能有脾气。"}, {"text": "性别", "is_correct": false, "explanation": "搭配：“有性别”只用于人或生物，不用于一本旧书。"}, {"text": "体温", "is_correct": false, "explanation": "语义：旧书没有体温，不能用“体温”来形容书。"}], "explanations": {"深意": "与“一定有”搭配，书中藏着深刻的内涵，符合句意。", "脾气": "语义：“脾气”是人的性格，书不能有脾气。", "性别": "搭配：“有性别”只用于人或生物，不用于一本旧书。", "体温": "语义：旧书没有体温，不能用“体温”来形容书。"}, "sentence_index": 6, "correct_answer": "深意"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台机器的深意很高。", "explanation": "这里应该用〈效率〉。深意指作品或符号中的深刻内涵，机器的工作速度要说效率。"}, {"text": "他对工作的深意很认真。", "explanation": "这里应该用〈态度〉。深意指内涵，人做事的认真程度要说态度。"}, {"text": "这批产品的深意很好。", "explanation": "这里应该用〈质量〉。深意指作品或话语中的内涵，产品的好坏要用质量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20915f57-310d-4435-8f8b-d9051973edfe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12480, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这部电影里有很多只深意。", "corrected_sentence": "这部电影里有很多层深意。", "error_description": "量词错误：深意应说“层”。“只”不能用于抽象的意义，应改为“很多层深意”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20915f57-310d-4435-8f8b-d9051973edfe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12480, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这篇小说里有一片深意。", "corrected_sentence": "这篇小说里有一层深意。", "error_description": "量词错误：深意应说“一层深意”；“片”用于树叶、土地这类平面的东西，不能用于深意。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20915f57-310d-4435-8f8b-d9051973edfe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
