INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12481, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一种用图形表示某种意义或概念的视觉标记", "primary_collocate": null, "pronunciation": "fú hào", "ipa": "fu˧˥ xɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "联合国环境规划署在1972年斯德哥尔摩人类环境会议后，将此类标准化符号纳入全球环境治理的技术建议之中。", "target_word": "符号", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "它不再仅指向物理层面的材料再生，更被赋予伦理与政治维度——消费者通过识别此符号，参与一场隐性的公民实践，表达对过度生产模式的反思。", "target_word": "符号", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这个符号表示这里可以回收。", "target_word": "符号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "瓶子下面有一个三角形的符号。", "target_word": "符号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "红色的叉号是禁止的符号。", "target_word": "符号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你知道这个符号是什么意思吗？", "target_word": "符号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地图上的每个符号都有自己的意思。", "target_word": "符号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "衣服的标签上有一个洗衣的符号。", "target_word": "符号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厕所门上的符号很容易看懂。", "target_word": "符号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "心形是爱的符号，很多人都知道。", "target_word": "符号", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "用图形表示某种意义的视觉标志，如回收标志、禁止标志", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63007dea-14d8-4e2d-8986-b9c20904b4ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12481, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "符号", "is_correct": true, "explanation": "符号：用图形表示意义的标准化标记，可以纳入“技术建议”。"}, {"text": "舞蹈", "is_correct": false, "explanation": "语义：舞蹈不是可以标准化并纳入环境治理技术建议的对象，句意不成立。"}, {"text": "心情", "is_correct": false, "explanation": "搭配：“标准化”不能修饰“心情”，心情也不能纳入技术建议。"}, {"text": "乐器", "is_correct": false, "explanation": "语义：乐器与环境治理的标准化建议不相关，句子语境不成立。"}], "explanations": {"符号": "符号：用图形表示意义的标准化标记，可以纳入“技术建议”。", "舞蹈": "语义：舞蹈不是可以标准化并纳入环境治理技术建议的对象，句意不成立。", "心情": "搭配：“标准化”不能修饰“心情”，心情也不能纳入技术建议。", "乐器": "语义：乐器与环境治理的标准化建议不相关，句子语境不成立。"}, "sentence_index": 0, "correct_answer": "符号"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这片草原的符号一望无际。", "explanation": "这里应该用〈景色〉。符号指用图形表示意义的标记，不能用来形容草原的景色。"}, {"text": "他给这个计划起了一个符号，只有我们几个人知道。", "explanation": "这里应该用〈代号〉。符号指用图形表示意义的标记，不能用来给计划起代号。"}, {"text": "他脸上露出一个开心的符号。", "explanation": "这里应该用〈表情〉。表情指脸上的神情，符号不能指面部的神情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20915f57-310d-4435-8f8b-d9051973edfe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12481, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "符号", "is_correct": true, "explanation": "符号：地图上用来表示地物的标记，每个都有自己的意思。"}, {"text": "声音", "is_correct": false, "explanation": "语义：地图上不会有声音，“声音有意思”的说法与地图无关。"}, {"text": "味道", "is_correct": false, "explanation": "语义：地图是视觉材料，味道不能标在地图上。"}, {"text": "脚步", "is_correct": false, "explanation": "搭配：“脚步”不能出现在地图的标记系统中，与“意思”的搭配也不成立。"}], "explanations": {"符号": "符号：地图上用来表示地物的标记，每个都有自己的意思。", "声音": "语义：地图上不会有声音，“声音有意思”的说法与地图无关。", "味道": "语义：地图是视觉材料，味道不能标在地图上。", "脚步": "搭配：“脚步”不能出现在地图的标记系统中，与“意思”的搭配也不成立。"}, "sentence_index": 6, "correct_answer": "符号"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这箱苹果的符号是五公斤。", "explanation": "这里应该用〈重量〉。符号是用图形表示意义的标记，不能用来说明物体的重量。"}, {"text": "她的符号很温柔。", "explanation": "这里应该用〈眼神〉。“温柔”形容神情，符号不能被形容为温柔。"}, {"text": "他的符号是王小明。", "explanation": "这里应该用〈姓名〉。符号是用图形表示意义的标记，不能用来指人的名字。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20915f57-310d-4435-8f8b-d9051973edfe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12481, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "包装袋上印着一条回收符号。", "corrected_sentence": "包装袋上印着一个回收符号。", "error_description": "量词错误：符号应该用量词“个”，不能用“条”。“条”用于细长的东西，与“符号”不搭。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20915f57-310d-4435-8f8b-d9051973edfe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12481, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我看见路边有一只符号。", "corrected_sentence": "我看见路边有一个符号。", "error_description": "量词错误：“符号”应该用“个”，不能用“只”。“只”多用于动物或成对的东西。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20915f57-310d-4435-8f8b-d9051973edfe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
