INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12482, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a54e2e0-9d56-4d45-81a7-812fd28216ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12482, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "顺应时机而产生。", "primary_collocate": null, "pronunciation": "yìng yùn ér shēng", "ipa": "iŋ˥˩ yn˥˩ ɚ˧˥ ʂəŋ˥", "syllable_count": 4, "sentences": [{"text": "在此背景下，一个简洁而富有深意的视觉符号应运而生——三箭头循环标志，它不仅成为现代环保主义的图腾，更承载了人类对可持续发展的集体渴望。", "target_word": "应运而生", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "有鉴于此，自制家庭堆肥系统应运而生，成为连接个体实践与生态伦理的微观技术路径。", "target_word": "应运而生", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "手机出现后，很多新的软件应运而生。", "target_word": "应运而生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城市里的人越来越忙，外卖行业应运而生。", "target_word": "应运而生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网络发展很快，网上购物应运而生。", "target_word": "应运而生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家想骑车上班，共享单车应运而生。", "target_word": "应运而生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "需要的人多了，新的职业应运而生。", "target_word": "应运而生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人越来越多，养老服务应运而生。", "target_word": "应运而生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生要学英语，很多网课应运而生。", "target_word": "应运而生", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "环保越来越重要，新的回收办法应运而生。", "target_word": "应运而生", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "顺应时代或需要而出现", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '144bdcb8-b634-4814-93d5-bb47c40a03fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12482, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "应运而生", "is_correct": true, "explanation": "正确：“应运而生”表示顺应时代需要而出现，与“成为图腾”的语境相符。"}, {"text": "烟消云散", "is_correct": false, "explanation": "语义：“烟消云散”表示消失，与“成为现代环保主义的图腾”矛盾。"}, {"text": "迎刃而解", "is_correct": false, "explanation": "配价：“迎刃而解”需要“问题”作主语，不能用于“视觉符号”。"}, {"text": "不翼而飞", "is_correct": false, "explanation": "语义：“不翼而飞”表示突然消失，与“承载了人类的渴望”矛盾。"}], "explanations": {"应运而生": "正确：“应运而生”表示顺应时代需要而出现，与“成为图腾”的语境相符。", "烟消云散": "语义：“烟消云散”表示消失，与“成为现代环保主义的图腾”矛盾。", "迎刃而解": "配价：“迎刃而解”需要“问题”作主语，不能用于“视觉符号”。", "不翼而飞": "语义：“不翼而飞”表示突然消失，与“承载了人类的渴望”矛盾。"}, "sentence_index": 0, "correct_answer": "应运而生"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的妹妹是去年夏天应运而生的。", "explanation": "〈诞生〉。说人的出生要用“诞生”，“应运而生”指顺应需要而出现的事物。"}, {"text": "这种病毒在城市里应运而生。", "explanation": "〈出现〉。说疾病或坏事的出现要用“出现”，“应运而生”带褒义，指顺应需要而出现的积极事物。"}, {"text": "这次事故是由管理松懈应运而生的。", "explanation": "〈产生〉。说事故或问题的产生要用“产生”，“应运而生”不用于这种情形。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a54e2e0-9d56-4d45-81a7-812fd28216ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12482, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "应运而生", "is_correct": true, "explanation": "正确：“应运而生”表示顺应需要而出现，与“需要的人多了”的语境相符。"}, {"text": "销声匿迹", "is_correct": false, "explanation": "语义：“销声匿迹”表示消失，与“需要的人多了”的趋势矛盾。"}, {"text": "应声而倒", "is_correct": false, "explanation": "搭配：“应声而倒”指随声倒下，不用于说职业的出现。"}, {"text": "日渐衰落", "is_correct": false, "explanation": "语义：“日渐衰落”表示减少，与“需要的人多了”的语境相反。"}], "explanations": {"应运而生": "正确：“应运而生”表示顺应需要而出现，与“需要的人多了”的语境相符。", "销声匿迹": "语义：“销声匿迹”表示消失，与“需要的人多了”的趋势矛盾。", "应声而倒": "搭配：“应声而倒”指随声倒下，不用于说职业的出现。", "日渐衰落": "语义：“日渐衰落”表示减少，与“需要的人多了”的语境相反。"}, "sentence_index": 6, "correct_answer": "应运而生"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "雨水应运而生，把地面全都打湿了。", "explanation": "〈降落〉。说雨水落下要用“降落”或“下”，“应运而生”指顺应需要而出现的事物，不用于自然现象。"}, {"text": "一场大火应运而生，烧毁了很多房子。", "explanation": "〈发生〉。说火灾等灾害的出现要用“发生”，“应运而生”带褒义，指顺应需要而出现的积极事物，不用于灾害。"}, {"text": "我的朋友应运而生，突然出现在我家门口。", "explanation": "〈来访〉。说人突然来到要用“来访”，“应运而生”指顺应需要而产生的事物，不用于描写人的到来。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a54e2e0-9d56-4d45-81a7-812fd28216ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12482, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "电脑普及后，很多新的游戏应运而生一种风潮。", "corrected_sentence": "电脑普及后，很多新的游戏应运而生。", "error_description": "错误：“应运而生一种风潮”。正确：“应运而生”。“应运而生”是不及物动词，后面不能直接带宾语，应去掉“一种风潮”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a54e2e0-9d56-4d45-81a7-812fd28216ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12482, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "城市变大后，一种新的服务被应运而生。", "corrected_sentence": "城市变大后，一种新的服务应运而生。", "error_description": "错误：“被应运而生”。正确：“应运而生”。“应运而生”是不及物动词，不能用“被”字句，应去掉“被”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a54e2e0-9d56-4d45-81a7-812fd28216ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
