INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12483, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "图腾是原始社会中被当作祖先或保护神的动物、植物或其他自然物，用作民族或部落的标志和象征。", "primary_collocate": null, "pronunciation": "tú téng", "ipa": "tʰu˧˥ tʰɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "这个部落的人在营地中央竖起一根刻着动物的木柱，那是他们的图腾。", "target_word": "图腾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个部落把老鹰当作自己的图腾。", "target_word": "图腾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古代人相信图腾可以保护整个部落。", "target_word": "图腾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的图腾是一条大蛇，没人敢伤害蛇。", "target_word": "图腾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这个民族的传说中，熊是祖先，也是图腾。", "target_word": "图腾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多古老的民族都有自己的图腾。", "target_word": "图腾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人们在布上画了他们部落的图腾。", "target_word": "图腾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种植物是那个家族世代崇拜的图腾。", "target_word": "图腾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旗子上的狼头图案，就是这个民族的图腾。", "target_word": "图腾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人给孩子讲了图腾和祖先的故事。", "target_word": "图腾", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "圖騰", "label": "繁体"}], "register": "中性", "sense_fingerprint": "原始社会中作为部落祖先或保护神的标志性动植物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e537b3a3-a277-4ca0-8ff4-0623d2e2b09c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12483, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "语法", "is_correct": false, "explanation": "语义：“语法”指语言的规则，不能指部落的标记。"}, {"text": "货币", "is_correct": false, "explanation": "语义：“货币”是流通的钱，不能指部落的标记。"}, {"text": "病毒", "is_correct": false, "explanation": "语义：“病毒”指致病微生物，不能指部落的标记。"}, {"text": "图腾", "is_correct": true, "explanation": "正确：图腾指被当作标志和象征的动植物或自然物，这里指部落刻在木柱上的标记。"}], "explanations": {"语法": "语义：“语法”指语言的规则，不能指部落的标记。", "货币": "语义：“货币”是流通的钱，不能指部落的标记。", "病毒": "语义：“病毒”指致病微生物，不能指部落的标记。", "图腾": "正确：图腾指被当作标志和象征的动植物或自然物，这里指部落刻在木柱上的标记。"}, "sentence_index": 0, "correct_answer": "图腾"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用图腾切菜，很快就把菜切好了。", "explanation": "这里应该用〈菜刀〉。图腾是部落或民族的标志和象征，不是切菜的工具，切菜要用〈菜刀〉。"}, {"text": "爷爷把一个图腾挂在胸前，每天都要看一看时间。", "explanation": "这里应该用〈怀表〉。图腾是部落的标志和象征，不是计时的器具，看时间要说〈怀表〉。"}, {"text": "这位将军的书桌上放着图腾，随时准备接听。", "explanation": "这里应该用〈电话〉。图腾是部落的标志和象征，不能用来接听；接听要说〈电话〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47b9e66b-ac6d-424c-9f31-f2277208a258') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12483, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "方言", "is_correct": false, "explanation": "语义：“方言”指地方话，不是能画在布上的标志，与“部落的……”也不搭。"}, {"text": "账户", "is_correct": false, "explanation": "搭配：“画”不能接“账户”作宾语，“账户”指银行或网络上的账号。"}, {"text": "病历", "is_correct": false, "explanation": "语义：“病历”是医院记录病情的文件，不是部落的标志。"}, {"text": "图腾", "is_correct": true, "explanation": "正确：图腾指被当作标志的事物，这里说人们在布上画了部落的图腾。"}], "explanations": {"方言": "语义：“方言”指地方话，不是能画在布上的标志，与“部落的……”也不搭。", "账户": "搭配：“画”不能接“账户”作宾语，“账户”指银行或网络上的账号。", "病历": "语义：“病历”是医院记录病情的文件，不是部落的标志。", "图腾": "正确：图腾指被当作标志的事物，这里说人们在布上画了部落的图腾。"}, "sentence_index": 6, "correct_answer": "图腾"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师在黑板上画了一辆图腾。", "explanation": "这里应该用〈个〉。“辆”用于车辆，图腾的量词应为〈个〉。"}, {"text": "那家工厂新买了一台图腾。", "explanation": "这里应该用〈个〉。“台”多用于机器和设备，图腾不用“台”来计量。"}, {"text": "妈妈在墙上挂了一把图腾。", "explanation": "这里应该用〈个〉。“把”多用于带柄的器具，图腾不用“把”来计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47b9e66b-ac6d-424c-9f31-f2277208a258') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12483, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那个部落有一只很古老的图腾。", "corrected_sentence": "那个部落有一个很古老的图腾。", "error_description": "量词错误：“图腾”的量词应为“个”，不能说“一只”（“只”多用于动物或成对的东西）。正确说法：那个部落有一个很古老的图腾。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47b9e66b-ac6d-424c-9f31-f2277208a258') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12483, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些图腾们都很古老，颜色很鲜艳。", "corrected_sentence": "这些图腾都很古老，颜色很鲜艳。", "error_description": "词尾错误：“图腾”是事物，不加“们”；“们”只用于人或拟人的名词，且“这些”已表示复数。正确说法：这些图腾都很古老，颜色很鲜艳。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47b9e66b-ac6d-424c-9f31-f2277208a258') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
