INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12487, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "地球日是一个全球性的环保活动日，旨在唤起人们保护地球、改善环境的意识，通常定在每年的4月22日。", "primary_collocate": null, "pronunciation": "dì qiú rì", "ipa": "ti˥˩ t͡ɕʰiou˧˥ ɻ̩˥˩", "syllable_count": 3, "sentences": [{"text": "这一设计的起源可追溯至1970年美国首届“地球日”活动，当时包装行业亟需一种公众易于识别的标识，以区分可回收材料与普通垃圾。", "target_word": "地球日", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "每年四月二十二日是地球日。", "target_word": "地球日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地球日那天，我们在学校种了树。", "target_word": "地球日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年的地球日，社区组织了环保活动。", "target_word": "地球日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地球日提醒大家要保护环境。", "target_word": "地球日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们公司在地球日关灯一小时。", "target_word": "地球日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在地球日给我们讲了环保知识。", "target_word": "地球日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地球日的主题每年都不一样。", "target_word": "地球日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多城市会在地球日举办环保活动。", "target_word": "地球日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在地球日，爸爸骑自行车去上班。", "target_word": "地球日", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "每年4月22日的全球环保纪念日", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e537b3a3-a277-4ca0-8ff4-0623d2e2b09c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12487, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "地球日", "is_correct": true, "explanation": "正确：地球日指每年4月22日的全球环保纪念日，这里指1970年美国首届“地球日”活动的名称，填入此处正确。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”不能作为一次环保活动的名称，“首届颜色活动”不通。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”只用于人，不能用来指一次活动。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：“脾气”指性情，不能用来指一次活动。"}], "explanations": {"地球日": "正确：地球日指每年4月22日的全球环保纪念日，这里指1970年美国首届“地球日”活动的名称，填入此处正确。", "颜色": "语义：“颜色”不能作为一次环保活动的名称，“首届颜色活动”不通。", "身高": "体貌：“身高”只用于人，不能用来指一次活动。", "脾气": "语义：“脾气”指性情，不能用来指一次活动。"}, "sentence_index": 0, "correct_answer": "地球日"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们学校在一只地球日举办了演讲比赛。", "explanation": "这里的量词应该用〈个〉。“只”用于动物，“地球日”是节日，要用“个”。"}, {"text": "我们每天都在地球日做环保。", "explanation": "这里应该用〈每年〉。“地球日”每年只有一次，指一个特定的日子，不能与“每天”搭配。"}, {"text": "我的地球日是六月一号。", "explanation": "这里应该用〈生日〉。“地球日”是全球性的纪念日，不属于个人，个人的日子要说“生日”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47b9e66b-ac6d-424c-9f31-f2277208a258') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12487, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "地球日", "is_correct": true, "explanation": "地球日是环保纪念日，“老师在……给我们讲了环保知识”中表示时间，填入此处正确。"}, {"text": "体重", "is_correct": false, "explanation": "体貌：“体重”只用于人或动物，不能说“老师在体重给我们讲课”。"}, {"text": "学历", "is_correct": false, "explanation": "配价：“学历”需要有人作为持有者，不能表示讲课的时间。"}, {"text": "性格", "is_correct": false, "explanation": "语义：“性格”指人的个性，不能表示讲课的时间，句子不通。"}], "explanations": {"地球日": "地球日是环保纪念日，“老师在……给我们讲了环保知识”中表示时间，填入此处正确。", "体重": "体貌：“体重”只用于人或动物，不能说“老师在体重给我们讲课”。", "学历": "配价：“学历”需要有人作为持有者，不能表示讲课的时间。", "性格": "语义：“性格”指人的个性，不能表示讲课的时间，句子不通。"}, "sentence_index": 6, "correct_answer": "地球日"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这本书的地球日很轻。", "explanation": "这里应该用〈重量〉。“很轻”说的是重量，“地球日”是纪念日，不能用来说轻重。"}, {"text": "这位长辈的地球日很大了。", "explanation": "这里应该用〈年龄〉。“很大”说的是年纪，“地球日”是日子，不能用来说人的年纪大。"}, {"text": "妈妈在地球日的厨房里做饭。", "explanation": "这里的错误在于地点。“地球日”是日期，不是地点，不能说“地球日的厨房”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47b9e66b-ac6d-424c-9f31-f2277208a258') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12487, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今年的一只地球日很特别。", "corrected_sentence": "今年的地球日很特别。", "error_description": "量词错误。“地球日”是日子，不能用“只”（只用于动物）。正确说法是“今年的地球日很特别”，去掉“一只”即可。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47b9e66b-ac6d-424c-9f31-f2277208a258') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12487, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "每年地球日们那天，学校都会组织活动。", "corrected_sentence": "每年地球日那天，学校都会组织活动。", "error_description": "词缀错误：“地球日”是日子，不能加“们”表示复数。正确说法是“每年地球日那天，学校都会组织活动”，去掉“们”即可。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47b9e66b-ac6d-424c-9f31-f2277208a258') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
