INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12489, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "迫切地需要。", "primary_collocate": null, "pronunciation": "jí xū", "ipa": "t͡ɕi˧˥ ɕy˥", "syllable_count": 2, "sentences": [{"text": "当时包装行业亟需一种标识。", "target_word": "亟需", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "灾区亟需大量的饮用水和药品。", "target_word": "亟需", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家医院亟需更多的医生。", "target_word": "亟需", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山区的孩子亟需有人帮助他们。", "target_word": "亟需", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司亟需一位懂技术的负责人。", "target_word": "亟需", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "当前亟需解决的问题是资金不足。", "target_word": "亟需", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老年人亟需更好的医疗服务。", "target_word": "亟需", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市亟需改善交通。", "target_word": "亟需", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农村亟需年轻的人才。", "target_word": "亟需", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "受灾群众亟需得到及时的救助。", "target_word": "亟需", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "迫切地需要某物或某人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e537b3a3-a277-4ca0-8ff4-0623d2e2b09c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12489, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "拒绝", "is_correct": false, "explanation": "语义：拒绝是不接受，与“亟需”表示的迫切需要相反。"}, {"text": "亟需", "is_correct": true, "explanation": "亟需：迫切地需要，与“当时包装行业……一种标识”的语境相符。"}, {"text": "嘲笑", "is_correct": false, "explanation": "语义：嘲笑是讥笑，与设计标识的实际需要不符。"}, {"text": "忘记", "is_correct": false, "explanation": "搭配：“忘记”一般跟事情或信息搭配，不能说“忘记一种标识”。"}], "explanations": {"拒绝": "语义：拒绝是不接受，与“亟需”表示的迫切需要相反。", "亟需": "亟需：迫切地需要，与“当时包装行业……一种标识”的语境相符。", "嘲笑": "语义：嘲笑是讥笑，与设计标识的实际需要不符。", "忘记": "搭配：“忘记”一般跟事情或信息搭配，不能说“忘记一种标识”。"}, "sentence_index": 0, "correct_answer": "亟需"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天都亟需喝水，已经习惯了。", "explanation": "这里应该用〈需要〉。亟需强调迫切，指紧急的需求；日常的需要不用亟需。"}, {"text": "我亟需明天不下雨。", "explanation": "这里应该用〈希望〉。亟需的对象是具体的需求，不能接表示愿望的分句。"}, {"text": "我亟需一瓶矿泉水，待会儿再喝。", "explanation": "这里应该用〈想要〉。亟需含有马上要的意思，与“待会儿再喝”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47b9e66b-ac6d-424c-9f31-f2277208a258') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12489, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "扔掉", "is_correct": false, "explanation": "语义：扔掉是丢弃，与“老年人需要更好的服务”的语境相反。"}, {"text": "亟需", "is_correct": true, "explanation": "亟需：迫切地需要，“老年人亟需更好的医疗服务”指老年人迫切需要它。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”的宾语不能是“医疗服务”，两者不搭配。"}, {"text": "修剪", "is_correct": false, "explanation": "搭配：“修剪”的对象是枝叶等，不能与“医疗服务”搭配。"}], "explanations": {"扔掉": "语义：扔掉是丢弃，与“老年人需要更好的服务”的语境相反。", "亟需": "亟需：迫切地需要，“老年人亟需更好的医疗服务”指老年人迫切需要它。", "唱": "搭配：“唱”的宾语不能是“医疗服务”，两者不搭配。", "修剪": "搭配：“修剪”的对象是枝叶等，不能与“医疗服务”搭配。"}, "sentence_index": 6, "correct_answer": "亟需"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我亟需他一定会成功。", "explanation": "这里应该用〈认为〉。亟需表示迫切的需要，不能接“他一定会成功”这样的判断。"}, {"text": "他很亟需帮助别人。", "explanation": "这里应该用〈愿意〉。亟需表示迫切的需要，不表示主观的意愿。"}, {"text": "我亟需明年换工作。", "explanation": "这里应该用〈打算〉。亟需强调现在迫切的需要，与“明年”的计划矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47b9e66b-ac6d-424c-9f31-f2277208a258') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12489, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "孩子们亟需了老师的帮助。", "corrected_sentence": "孩子们亟需老师的帮助。", "error_description": "“亟需”后面不能加“了”，“亟需”本身已表示现在的需求；应说“孩子们亟需老师的帮助”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47b9e66b-ac6d-424c-9f31-f2277208a258') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12489, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们暂时没亟需更多的资金。", "corrected_sentence": "我们暂时不亟需更多的资金。", "error_description": "否定词错误：“亟需”表示现在的需求，应用“不”否定，说“不亟需”，不说“没亟需”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '47b9e66b-ac6d-424c-9f31-f2277208a258') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12490, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "难于", "is_correct": true, "explanation": "正确答案。难于与易于互为反义，都表示做起来难度的高低。"}, {"text": "进行", "is_correct": false, "explanation": "与“易于”无反义关系，“进行”表示开展某种活动，不涉及难易。"}, {"text": "保持", "is_correct": false, "explanation": "与“易于”无反义关系，“保持”表示维持原状，不涉及难易。"}, {"text": "运用", "is_correct": false, "explanation": "与“易于”无反义关系，“运用”表示使用，不涉及难易。"}], "correct_answer": "难于", "explanations": {"难于": "正确答案。难于与易于互为反义，都表示做起来难度的高低。", "进行": "与“易于”无反义关系，“进行”表示开展某种活动，不涉及难易。", "保持": "与“易于”无反义关系，“保持”表示维持原状，不涉及难易。", "运用": "与“易于”无反义关系，“运用”表示使用，不涉及难易。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dc33abe-674a-44f2-909c-f7d4ddb94590') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12490, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "难于", "is_correct": true, "explanation": "正确答案。难于与易于互为反义，都表示做起来难度的高低。"}, {"text": "观察", "is_correct": false, "explanation": "与“易于”无反义关系，“观察”表示仔细看，不涉及难易。"}, {"text": "思考", "is_correct": false, "explanation": "与“易于”无反义关系，“思考”表示动脑筋，不涉及难易。"}, {"text": "拥有", "is_correct": false, "explanation": "与“易于”无反义关系，“拥有”表示占有，不涉及难易。"}], "correct_answer": "难于", "explanations": {"难于": "正确答案。难于与易于互为反义，都表示做起来难度的高低。", "观察": "与“易于”无反义关系，“观察”表示仔细看，不涉及难易。", "思考": "与“易于”无反义关系，“思考”表示动脑筋，不涉及难易。", "拥有": "与“易于”无反义关系，“拥有”表示占有，不涉及难易。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dc33abe-674a-44f2-909c-f7d4ddb94590') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12490, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "property", "definition": "指做起来不费力，难度小。", "primary_collocate": null, "pronunciation": "yì yú", "ipa": "i˥˩ y˧˥", "syllable_count": 2, "sentences": [{"text": "这一设计的起源可追溯至1970年美国首届“地球日”活动，当时包装行业亟需一种公众易于识别的标识，以区分可回收材料与普通垃圾。", "target_word": "易于", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这种饼干易于保存。", "target_word": "易于", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这本书的语言简单，易于理解。", "target_word": "易于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个软件易于使用，老人也能学会。", "target_word": "易于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "塑料易于加工，所以很多玩具都用它做。", "target_word": "易于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "规则简单、易于掌握的游戏更受新手欢迎。", "target_word": "易于", "complexity_tier": "T3", "furigana": "guī zé jiǎn dān 、 yì yú zhǎng wò de yóu xì gèng shòu xīn shǒu huān yíng 。", "sentence_source": "generated"}, {"text": "这种布料易于清洗，不会很快变脏。", "target_word": "易于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的方法易于学习，大家都愿意试一试。", "target_word": "易于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "说明书要写得简单，易于看懂。", "target_word": "易于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个词很短，易于记住。", "target_word": "易于", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "易於", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "易于+动词：做起来不费力，难度小", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de0af34a-b903-4db2-b774-445d6bfb1c29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12490, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "易于", "is_correct": true, "explanation": "正确答案。易于（yì yú）表示做起来不费力。"}, {"text": "意欲", "is_correct": false, "explanation": "第二个音节 yù（第四声）与 yú（第二声）声调不同，意思是“想要”。"}, {"text": "立于", "is_correct": false, "explanation": "lì 与 yì 声母不同，意思是“站立在”。"}, {"text": "一语", "is_correct": false, "explanation": "yī（第一声）与 yì（第四声）声调不同，yǔ 与 yú 声调也不同，意思是“一句话”。"}, {"text": "异域", "is_correct": false, "explanation": "第二个音节 yù（第四声）与 yú（第二声）声调不同，意思是“外国、异乡”。"}], "explanations": {"易于": "正确答案。易于（yì yú）表示做起来不费力。", "意欲": "第二个音节 yù（第四声）与 yú（第二声）声调不同，意思是“想要”。", "立于": "lì 与 yì 声母不同，意思是“站立在”。", "一语": "yī（第一声）与 yì（第四声）声调不同，yǔ 与 yú 声调也不同，意思是“一句话”。", "异域": "第二个音节 yù（第四声）与 yú（第二声）声调不同，意思是“外国、异乡”。"}, "sentence_index": null, "correct_answer": "易于"}, "level_3": {"options": [{"text": "易于", "is_correct": true, "explanation": "正确答案。“公众易于识别”表示标识容易被辨认，与后句“以区分”相合。"}, {"text": "善于", "is_correct": false, "explanation": "搭配：“善于”说人擅长做某事，不能用来修饰“标识”的可识别性。"}, {"text": "勇于", "is_correct": false, "explanation": "搭配：“勇于”表示敢于做某事，不说“公众勇于识别的标识”。"}, {"text": "难以", "is_correct": false, "explanation": "语义：“难以识别”与“以区分”的目的相反，标识应当便于辨认。"}], "explanations": {"易于": "正确答案。“公众易于识别”表示标识容易被辨认，与后句“以区分”相合。", "善于": "搭配：“善于”说人擅长做某事，不能用来修饰“标识”的可识别性。", "勇于": "搭配：“勇于”表示敢于做某事，不说“公众勇于识别的标识”。", "难以": "语义：“难以识别”与“以区分”的目的相反，标识应当便于辨认。"}, "sentence_index": 0, "correct_answer": "易于"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是个热心人，总是乐于帮助别人，可每次帮完都累得说不出话。", "explanation": "这里应该用〈乐于〉。易于说做起来不费力，与“累得说不出话”矛盾；说愿意做某事要用乐于。"}, {"text": "妹妹易于画画，每次都要画上一整天才画得出一张。", "explanation": "这里应该用〈善于〉。易于说做起来不费力，与“画上一整天”矛盾；说人擅长某件事要用善于。"}, {"text": "他易于改了合同，没有告诉任何人。", "explanation": "这里应该用〈擅自〉。易于说事情做起来不费力，说未经许可就做某事要用擅自。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dc33abe-674a-44f2-909c-f7d4ddb94590') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12490, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "易于", "is_correct": true, "explanation": "正确答案。易于（yì yú）表示做起来不费力。"}, {"text": "利于", "is_correct": false, "explanation": "lì 与 yì 声母不同，意思是“有利于”。"}, {"text": "依于", "is_correct": false, "explanation": "yī（第一声）与 yì（第四声）声调不同，意思是“依靠、取决于”。"}, {"text": "意语", "is_correct": false, "explanation": "第二个音节 yǔ（第三声）与 yú（第二声）声调不同，意思是“意大利语”。"}], "explanations": {"易于": "正确答案。易于（yì yú）表示做起来不费力。", "利于": "lì 与 yì 声母不同，意思是“有利于”。", "依于": "yī（第一声）与 yì（第四声）声调不同，意思是“依靠、取决于”。", "意语": "第二个音节 yǔ（第三声）与 yú（第二声）声调不同，意思是“意大利语”。"}, "sentence_index": null, "correct_answer": "易于"}, "level_3": {"options": [{"text": "易于", "is_correct": true, "explanation": "正确答案。“易于清洗”与后句“不会很快变脏”相合，说明布料好洗。"}, {"text": "精于", "is_correct": false, "explanation": "搭配：“精于”说人在某方面很熟练，不能用来修饰布料的清洗。"}, {"text": "勤于", "is_correct": false, "explanation": "搭配：“勤于”说人勤奋，不能用来修饰布料的清洗。"}, {"text": "疏于", "is_correct": false, "explanation": "搭配：“疏于”表示疏忽、忽视，不能用来修饰布料的清洗。"}], "explanations": {"易于": "正确答案。“易于清洗”与后句“不会很快变脏”相合，说明布料好洗。", "精于": "搭配：“精于”说人在某方面很熟练，不能用来修饰布料的清洗。", "勤于": "搭配：“勤于”说人勤奋，不能用来修饰布料的清洗。", "疏于": "搭配：“疏于”表示疏忽、忽视，不能用来修饰布料的清洗。"}, "sentence_index": 6, "correct_answer": "易于"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这道题他算了一整天，易于算出来了。", "explanation": "这里应该用〈终于〉。易于说事情做起来不费力，说经过一番努力最后达成要用终于；句中“算了一整天”说明并不轻松，与易于矛盾。"}, {"text": "我易于早起，可每天都累得要命。", "explanation": "这里应该用〈习惯〉。易于说做起来不费力，与“累得要命”矛盾；说一个人习惯某种行为要用习惯。"}, {"text": "她易于弹钢琴，每次练琴都累得直掉眼泪。", "explanation": "这里应该用〈擅长〉。易于说做起来不费力，与“累得直掉眼泪”矛盾；说人擅长某件事要用擅长。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dc33abe-674a-44f2-909c-f7d4ddb94590') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12490, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台机器易于了维修，一般人也能修。", "corrected_sentence": "这台机器易于维修，一般人也能修。", "error_description": "错误形式：“易于了维修”。正确形式：“易于维修”。易于是修饰动词的状语，后面不能直接加“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dc33abe-674a-44f2-909c-f7d4ddb94590') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12490, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这套方法很易于掌握，初学者很快就能用。", "corrected_sentence": "这套方法易于掌握，初学者很快就能用。", "error_description": "错误形式：“很易于掌握”。正确形式：“易于掌握”。易于本身已表示“容易”，不能再用“很”修饰。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dc33abe-674a-44f2-909c-f7d4ddb94590') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
