INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12494, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dc33abe-674a-44f2-909c-f7d4ddb94590') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12494, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "不加隐蔽，让所有人都能知道或看到。", "primary_collocate": null, "pronunciation": "gōng kāi", "ipa": "kʊŋ˥ kʰaɪ˥", "syllable_count": 2, "sentences": [{"text": "这场比赛是公开的，谁都可以去看。", "target_word": "公开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在公开场合从不说这件事。", "target_word": "公开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个活动对所有人公开，不用花钱。", "target_word": "公开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是一个公开的秘密，大家都知道。", "target_word": "公开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司的账目是公开的，员工可以查。", "target_word": "公开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师当着大家的面公开表扬了他。", "target_word": "公开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市长公开道歉，大家都看到了。", "target_word": "公开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个会议不公开，记者不能进去。", "target_word": "公开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他公开说自己不喜欢这份工作。", "target_word": "公开", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们公开地谈了这件事，没有躲着人。", "target_word": "公开", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "公开课", "label": "复合"}, {"form": "公开信", "label": "复合"}, {"form": "公开化", "label": "复合"}], "register": "中性", "sense_fingerprint": "公开|不隐蔽，所有人都能知道或看到", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de0af34a-b903-4db2-b774-445d6bfb1c29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12494, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "私人", "is_correct": false, "explanation": "语义：“私人”指只限个人，与“谁都可以去看”相矛盾。"}, {"text": "高贵", "is_correct": false, "explanation": "搭配：“高贵”多用于形容人或物品的品格，不用来形容比赛。"}, {"text": "公开", "is_correct": true, "explanation": "“公开”指不隐蔽、人人可以参与或观看，与“谁都可以去看”相符。"}, {"text": "隐蔽", "is_correct": false, "explanation": "语义：“隐蔽”指不让人看见，与“谁都可以去看”相矛盾。"}], "explanations": {"私人": "语义：“私人”指只限个人，与“谁都可以去看”相矛盾。", "高贵": "搭配：“高贵”多用于形容人或物品的品格，不用来形容比赛。", "公开": "“公开”指不隐蔽、人人可以参与或观看，与“谁都可以去看”相符。", "隐蔽": "语义：“隐蔽”指不让人看见，与“谁都可以去看”相矛盾。"}, "sentence_index": 0, "correct_answer": "公开"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的心事很公开，谁都看不出来。", "explanation": "这里应该用〈隐秘〉。公开指不隐蔽、让人知道，心事不被人察觉要用“隐秘”。"}, {"text": "这种颜色很公开，很多人都喜欢。", "explanation": "这里应该用〈鲜艳〉。公开指不隐蔽、让人知道，不能用来形容颜色，应说鲜艳。"}, {"text": "这件衣服很公开，穿在身上很舒服。", "explanation": "这里应该用〈宽松〉。公开指不隐蔽、让人知道，不能用来形容衣服的松紧，应说宽松。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dc33abe-674a-44f2-909c-f7d4ddb94590') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12494, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "偷偷", "is_correct": false, "explanation": "语义：“偷偷”指暗中进行，与“大家都看到了”相矛盾。"}, {"text": "尽情", "is_correct": false, "explanation": "搭配：“尽情”修饰尽情享受的动作，不能修饰“道歉”。"}, {"text": "私下", "is_correct": false, "explanation": "语义：“私下”指不当众，与“大家都看到了”相矛盾。"}, {"text": "公开", "is_correct": true, "explanation": "“公开道歉”指当众致歉，与“大家都看到了”相符。"}], "explanations": {"偷偷": "语义：“偷偷”指暗中进行，与“大家都看到了”相矛盾。", "尽情": "搭配：“尽情”修饰尽情享受的动作，不能修饰“道歉”。", "私下": "语义：“私下”指不当众，与“大家都看到了”相矛盾。", "公开": "“公开道歉”指当众致歉，与“大家都看到了”相符。"}, "sentence_index": 6, "correct_answer": "公开"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他长得很公开，一眼就能看见。", "explanation": "这里应该用〈高大〉。公开指不隐蔽、让人知道，不能用来形容人的身材。"}, {"text": "这把椅子很公开，坐上去很硌人。", "explanation": "这里应该用〈硬〉。公开指不隐蔽、让人知道，不能用来形容椅子的软硬，应说硬。"}, {"text": "这首歌的声音很公开。", "explanation": "这里应该用〈清脆〉。公开指不隐蔽、让人知道，不能用来形容声音。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dc33abe-674a-44f2-909c-f7d4ddb94590') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12494, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次会议的内容是公开地，记者可以报道。", "corrected_sentence": "这次会议的内容是公开的，记者可以报道。", "error_description": "错误形式：“是公开地”；正确形式：“是公开的”。作谓语的形容词后用“的”，“地”用于修饰动词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dc33abe-674a-44f2-909c-f7d4ddb94590') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12494, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些报告是公开地，谁都可以下载。", "corrected_sentence": "这些报告是公开的，谁都可以下载。", "error_description": "错误形式：“是公开地”。正确形式：“是公开的”。作谓语的形容词后用“的”，“地”用于修饰动词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dc33abe-674a-44f2-909c-f7d4ddb94590') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
