INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12495, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "通过公告、通知等方式收集大家的意见、建议或物品。", "primary_collocate": null, "pronunciation": "zhēng jí", "ipa": "ʈʂɤŋ˥ tɕi˧˥", "syllable_count": 2, "sentences": [{"text": "经过公开征集，年轻平面设计师的提案最终胜出：三条首尾相连的箭头构成莫比乌斯环的变体，既暗示物质的无限循环，又通过动态线条传递持续运动的能量感。", "target_word": "征集", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "学校正在征集学生的建议。", "target_word": "征集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司向大家征集新产品的名字。", "target_word": "征集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图书馆征集了很多旧书。", "target_word": "征集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在网上征集照片。", "target_word": "征集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "社区征集了居民对公园改造的意见。", "target_word": "征集", "complexity_tier": "T3", "furigana": "shè qū zhēng jí le jū mín duì gōng yuán gǎi zào de yì jiàn", "sentence_source": "generated"}, {"text": "这次比赛向全国征集作品。", "target_word": "征集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电视台昨天开始征集观众的意见。", "target_word": "征集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师征集了大家的想法。", "target_word": "征集", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "博物馆想征集一些老物品。", "target_word": "征集", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "征集了", "label": "体标"}, {"form": "征集过", "label": "体标"}, {"form": "征集令", "label": "复合"}], "register": "书面", "sense_fingerprint": "征集|通过公告收集意见、建议或物品", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'de0af34a-b903-4db2-b774-445d6bfb1c29') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12495, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "征集", "is_correct": true, "explanation": "正确答案：征集（zhēng jí），通过公告收集大家的意见、建议或物品。"}, {"text": "中级", "is_correct": false, "explanation": "zhōng 与 zhēng 韵母不同（ong 与 eng），意思是中级。"}, {"text": "争执", "is_correct": false, "explanation": "zhí 与 jí 声母不同（zh 与 j），意思是争论、纠纷。"}, {"text": "政绩", "is_correct": false, "explanation": "zhèng 与 zhēng 声调不同，jì 与 jí 声调也不同，意思是政绩。"}, {"text": "症结", "is_correct": false, "explanation": "jié 与 jí 韵母不同（ie 与 i），意思是问题的关键所在。"}], "explanations": {"征集": "正确答案：征集（zhēng jí），通过公告收集大家的意见、建议或物品。", "中级": "zhōng 与 zhēng 韵母不同（ong 与 eng），意思是中级。", "争执": "zhí 与 jí 声母不同（zh 与 j），意思是争论、纠纷。", "政绩": "zhèng 与 zhēng 声调不同，jì 与 jí 声调也不同，意思是政绩。", "症结": "jié 与 jí 韵母不同（ie 与 i），意思是问题的关键所在。"}, "sentence_index": null, "correct_answer": "征集"}, "level_3": {"options": [{"text": "征集", "is_correct": true, "explanation": "正确答案：“经过公开征集”指公开征求提案，与后文提案胜出的语境相符。"}, {"text": "拍卖", "is_correct": false, "explanation": "语义：“拍卖”是把拍品卖出，提案不是拍品，不能经过公开拍卖而胜出。"}, {"text": "出售", "is_correct": false, "explanation": "语义：“出售”针对商品，提案不能拿来出售，与比赛胜出的意思不符。"}, {"text": "批改", "is_correct": false, "explanation": "搭配：“批改”多用于作业、文章，不说公开批改提案。"}], "explanations": {"征集": "正确答案：“经过公开征集”指公开征求提案，与后文提案胜出的语境相符。", "拍卖": "语义：“拍卖”是把拍品卖出，提案不是拍品，不能经过公开拍卖而胜出。", "出售": "语义：“出售”针对商品，提案不能拿来出售，与比赛胜出的意思不符。", "批改": "搭配：“批改”多用于作业、文章，不说公开批改提案。"}, "sentence_index": 0, "correct_answer": "征集"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在超市征集了一箱牛奶。", "explanation": "这里应该用〈购买〉。征集是通过公告请大家提供东西或意见，个人在超市买东西要用购买。"}, {"text": "税务局征集了很多税。", "explanation": "这里应该用〈征收〉。税款要依法强制征收，不是请大家自愿提出，不能用征集。"}, {"text": "妈妈征集了我的意见。", "explanation": "这里应该用〈征求〉。征集面向大众公开收集，只向某个人问意见要用征求。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dc33abe-674a-44f2-909c-f7d4ddb94590') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12495, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "征集", "is_correct": true, "explanation": "正确答案：征集（zhēng jí），通过公告收集大家的意见、建议或物品。"}, {"text": "升级", "is_correct": false, "explanation": "shēng 与 zhēng 声母不同（sh 与 zh），意思是提高等级。"}, {"text": "终极", "is_correct": false, "explanation": "zhōng 与 zhēng 韵母不同（ong 与 eng），意思是最后的、最高的。"}, {"text": "正极", "is_correct": false, "explanation": "zhèng 与 zhēng 声调不同，意思是电池或电路的正极。"}, {"text": "整机", "is_correct": false, "explanation": "zhěng 与 zhēng 声调不同，jī 与 jí 声调也不同，意思是完整的机器。"}], "explanations": {"征集": "正确答案：征集（zhēng jí），通过公告收集大家的意见、建议或物品。", "升级": "shēng 与 zhēng 声母不同（sh 与 zh），意思是提高等级。", "终极": "zhōng 与 zhēng 韵母不同（ong 与 eng），意思是最后的、最高的。", "正极": "zhèng 与 zhēng 声调不同，意思是电池或电路的正极。", "整机": "zhěng 与 zhēng 声调不同，jī 与 jí 声调也不同，意思是完整的机器。"}, "sentence_index": null, "correct_answer": "征集"}, "level_3": {"options": [{"text": "征集", "is_correct": true, "explanation": "正确答案：“向全国征集作品”指面向全国公开征求参赛作品，与“作品”搭配。"}, {"text": "销毁", "is_correct": false, "explanation": "语义：“销毁”是毁掉，与比赛面向全国征集作品的意思相反。"}, {"text": "嘲笑", "is_correct": false, "explanation": "搭配：“嘲笑”针对人或言行，不能嘲笑作品向全国征集。"}, {"text": "歧视", "is_correct": false, "explanation": "搭配：“歧视”针对人群，不能说歧视作品。"}], "explanations": {"征集": "正确答案：“向全国征集作品”指面向全国公开征求参赛作品，与“作品”搭配。", "销毁": "语义：“销毁”是毁掉，与比赛面向全国征集作品的意思相反。", "嘲笑": "搭配：“嘲笑”针对人或言行，不能嘲笑作品向全国征集。", "歧视": "搭配：“歧视”针对人群，不能说歧视作品。"}, "sentence_index": 6, "correct_answer": "征集"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "很多居民向图书馆征集了旧书。", "explanation": "这里应该用〈捐赠〉。征集的一方是组织者，居民捐出旧书要用捐赠，不能说居民向图书馆征集。"}, {"text": "政府征集了三块土地。", "explanation": "这里应该用〈征用〉。征集是公开请大家提出，土地被政府强制使用要用征用。"}, {"text": "他终于征集了这座高山。", "explanation": "这里应该用〈征服〉。征集的对象是东西或意见，不能用于高山。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dc33abe-674a-44f2-909c-f7d4ddb94590') ON CONFLICT (sense_id, 