INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12495, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "市政府认真的征集了三条建议。", "corrected_sentence": "市政府认真地征集了三条建议。", "error_description": "“认真”作状语修饰动词“征集”，应用“地”，不能用“的”。应改为“市政府认真地征集了三条建议”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dc33abe-674a-44f2-909c-f7d4ddb94590') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12496, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "年老", "is_correct": true, "explanation": "正确答案：“年老”与“年轻”在年龄义上构成反义。"}, {"text": "简单", "is_correct": false, "explanation": "“简单”是形容词，但与“年轻”没有反义关系。"}, {"text": "热情", "is_correct": false, "explanation": "“热情”是形容词，与“年轻”的年龄义无反义关系。"}, {"text": "安静", "is_correct": false, "explanation": "“安静”是“吵闹”的反义词，与“年轻”无反义关系。"}], "correct_answer": "年老", "explanations": {"年老": "正确答案：“年老”与“年轻”在年龄义上构成反义。", "简单": "“简单”是形容词，但与“年轻”没有反义关系。", "热情": "“热情”是形容词，与“年轻”的年龄义无反义关系。", "安静": "“安静”是“吵闹”的反义词，与“年轻”无反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dc33abe-674a-44f2-909c-f7d4ddb94590') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
