INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12503, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "环形或圆圈形状的物体。", "primary_collocate": null, "pronunciation": "huán", "ipa": "xwan˧˥", "syllable_count": 1, "sentences": [{"text": "经过公开征集，年轻平面设计师的提案最终胜出：三条首尾相连的箭头围成了一个环，既暗示物质的无限循环，又通过动态线条传递持续运动的能量感。", "target_word": "环", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "请把钥匙挂在这个环上。", "target_word": "环", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她用铁丝弯成了一个环。", "target_word": "环", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这只鸟的腿上有一个环。", "target_word": "环", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们在草地上滚着一个环。", "target_word": "环", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门上的环已经很旧了。", "target_word": "环", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "绳子的一头有一个环。", "target_word": "环", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把线绕成一个小环。", "target_word": "环", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个环是用铁做的。", "target_word": "环", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "杯子底下有一个金属环。", "target_word": "环", "complexity_tier": "T3", "furigana": "huán", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个环", "label": "量词"}, {"form": "環", "label": "繁体"}], "register": "中性", "sense_fingerprint": "环形、圆圈形状的物体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '142dd450-e208-4e20-a103-c67974c95972') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12503, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "环", "is_correct": true, "explanation": "环：huán（第二声），指环形或圆圈形的物体，是正确答案。"}, {"text": "欢", "is_correct": false, "explanation": "huān（第一声）与 huán（第二声）声调不同，意思是高兴、喜欢。"}, {"text": "换", "is_correct": false, "explanation": "huàn（第四声）与 huán（第二声）声调不同，意思是交换、更换。"}, {"text": "黄", "is_correct": false, "explanation": "huáng 与 huán 韵尾不同（-ng 与 -n），意思是黄色。"}, {"text": "悬", "is_correct": false, "explanation": "xuán 与 huán 声母不同（x 与 h），意思是悬挂、悬空。"}], "explanations": {"环": "环：huán（第二声），指环形或圆圈形的物体，是正确答案。", "欢": "huān（第一声）与 huán（第二声）声调不同，意思是高兴、喜欢。", "换": "huàn（第四声）与 huán（第二声）声调不同，意思是交换、更换。", "黄": "huáng 与 huán 韵尾不同（-ng 与 -n），意思是黄色。", "悬": "xuán 与 huán 声母不同（x 与 h），意思是悬挂、悬空。"}, "sentence_index": null, "correct_answer": "环"}, "level_3": {"options": [{"text": "环", "is_correct": true, "explanation": "“三条箭头围成了一个环”，环是首尾相连围成的环形图形，符合句意。"}, {"text": "灯", "is_correct": false, "explanation": "语义：“灯”不是几何图形，“围成了一个灯”说不通。"}, {"text": "树", "is_correct": false, "explanation": "语义：树不是能被箭头围成的图形，“围成了一个树”说不通。"}, {"text": "琴", "is_correct": false, "explanation": "语义：“琴”是乐器，与箭头围成的图形无关。"}], "explanations": {"环": "“三条箭头围成了一个环”，环是首尾相连围成的环形图形，符合句意。", "灯": "语义：“灯”不是几何图形，“围成了一个灯”说不通。", "树": "语义：树不是能被箭头围成的图形，“围成了一个树”说不通。", "琴": "语义：“琴”是乐器，与箭头围成的图形无关。"}, "sentence_index": 0, "correct_answer": "环"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的朋友环很小，只有几个人。", "explanation": "这里应该用〈圈〉。“朋友圈”指交往的范围，“环”只指环形物或环节，不指人群。"}, {"text": "她用笔把答案环了出来。", "explanation": "这里应该用〈圈〉。“圈出”指用笔画圈把字句标出来；“环”作动词只表示环绕，不指用笔画圈。"}, {"text": "他昨天环了我一百块钱。", "explanation": "这里应该用〈还〉。“还钱”的“还”同音（huán），但字形与意义都不同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9c27c4a-e020-4fe3-9b5d-444551d16f67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12503, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "环", "is_correct": true, "explanation": "环：huán（第二声），指环形或圆圈形的物体，是正确答案。"}, {"text": "缓", "is_correct": false, "explanation": "huǎn（第三声）与 huán（第二声）声调不同，意思是缓慢。"}, {"text": "唤", "is_correct": false, "explanation": "huàn（第四声）与 huán（第二声）声调不同，意思是呼唤。"}, {"text": "全", "is_correct": false, "explanation": "quán 与 huán 声母不同（q 与 h），意思是全部。"}, {"text": "患", "is_correct": false, "explanation": "huàn（第四声）与 huán（第二声）声调不同，意思是患病、忧虑。"}], "explanations": {"环": "环：huán（第二声），指环形或圆圈形的物体，是正确答案。", "缓": "huǎn（第三声）与 huán（第二声）声调不同，意思是缓慢。", "唤": "huàn（第四声）与 huán（第二声）声调不同，意思是呼唤。", "全": "quán 与 huán 声母不同（q 与 h），意思是全部。", "患": "huàn（第四声）与 huán（第二声）声调不同，意思是患病、忧虑。"}, "sentence_index": null, "correct_answer": "环"}, "level_3": {"options": [{"text": "环", "is_correct": true, "explanation": "“绳子的一头有一个环”，环是绳子端头的环形物，符合句意。"}, {"text": "车", "is_correct": false, "explanation": "语义：“车”是交通工具，绳子的一头不可能有一辆车。"}, {"text": "杯", "is_correct": false, "explanation": "语义：“杯”是容器，不是绳子端头的环形物，句意不通。"}, {"text": "鞋", "is_correct": false, "explanation": "搭配：“鞋”一般用“只／双”计量，不说“一个鞋”。"}], "explanations": {"环": "“绳子的一头有一个环”，环是绳子端头的环形物，符合句意。", "车": "语义：“车”是交通工具，绳子的一头不可能有一辆车。", "杯": "语义：“杯”是容器，不是绳子端头的环形物，句意不通。", "鞋": "搭配：“鞋”一般用“只／双”计量，不说“一个鞋”。"}, "sentence_index": 6, "correct_answer": "环"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在这个环里很有名。", "explanation": "这里应该用〈圈子〉。“圈子”指一群人或某个范围，“环”只指环形物或环节，不指人群。"}, {"text": "他把借的书环给了图书馆。", "explanation": "这里应该用〈还〉。“还书”的“还”同音（huán），但字形与意义都不同。"}, {"text": "农民把牛环在棚里。", "explanation": "这里应该用〈圈〉。“圈”可指把牲口关进圈栏，“环”作动词只表示环绕，不指关牲口。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9c27c4a-e020-4fe3-9b5d-444551d16f67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12503, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我想买一根环送给她。", "corrected_sentence": "我想买一个环送给她。", "error_description": "量词错误：“环”是圆形物，应该用量词“个”，不能用“根”（“根”用于细长条状的东西）。正确说法是“一个环”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9c27c4a-e020-4fe3-9b5d-444551d16f67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12503, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她买了三只环送给朋友。", "corrected_sentence": "她买了三个环送给朋友。", "error_description": "量词错误：“只”多用于动物或成对物件中的一个，环是圆形物，应用“个”。正确说法是“三个环”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9c27c4a-e020-4fe3-9b5d-444551d16f67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
