INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12504, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "变体指同一事物在形式、内容等方面的变异形态。", "primary_collocate": null, "pronunciation": "biàn tǐ", "ipa": "pjɛn˥˩ tʰi˨˩", "syllable_count": 2, "sentences": [{"text": "经过公开征集，年轻平面设计师的提案最终胜出：三条首尾相连的箭头构成莫比乌斯环的变体，既暗示物质的无限循环，又通过动态线条传递持续运动的能量感。", "target_word": "变体", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "如今，在碳中和议程与循环经济政策的推动下，其象征意义仍在持续重构——新一代变体设计开始融入生物降解指示、碳足迹数据乃至动态二维码，预示着静态符号向智能信息接口的演进。", "target_word": "变体", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这个字有两种变体。", "target_word": "变体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种病毒出现了新的变体。", "target_word": "变体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首歌是老歌的一个变体。", "target_word": "变体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个故事有很多变体。", "target_word": "变体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他设计了这个标志的变体。", "target_word": "变体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们公司用了这个图案的变体。", "target_word": "变体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个词的变体在南方很常见。", "target_word": "变体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新变体比原来的病毒传得快。", "target_word": "变体", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种变体", "label": "量词"}, {"form": "變體", "label": "繁体"}], "register": "中性", "sense_fingerprint": "同一事物在形式或内容上产生变异的形态", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '142dd450-e208-4e20-a103-c67974c95972') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12504, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "变体", "is_correct": true, "explanation": "“莫比乌斯环的变体”指同一图形在形式上的变异形态，符合句意。"}, {"text": "歌", "is_correct": false, "explanation": "语义：“莫比乌斯环的歌”说不通，歌不是图形的形式。"}, {"text": "床", "is_correct": false, "explanation": "语义：床与几何图形的形式变异无关，句意不通。"}, {"text": "汤", "is_correct": false, "explanation": "搭配：“莫比乌斯环的”后面不能接“汤”这类食物。"}], "explanations": {"变体": "“莫比乌斯环的变体”指同一图形在形式上的变异形态，符合句意。", "歌": "语义：“莫比乌斯环的歌”说不通，歌不是图形的形式。", "床": "语义：床与几何图形的形式变异无关，句意不通。", "汤": "搭配：“莫比乌斯环的”后面不能接“汤”这类食物。"}, "sentence_index": 0, "correct_answer": "变体"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今年夏天的天气变体很大。", "explanation": "这里应该用〈变化〉。变体指同一事物形式上的变异形态，不指天气的变动过程。"}, {"text": "这个月的物价变体很厉害。", "explanation": "这里应该用〈波动〉。变体指同一事物形式上的变异形态，不指物价的起伏。"}, {"text": "这种病毒很快就变体了。", "explanation": "这里应该用〈变异〉。变体是名词，不能作动词谓语，动词要说“变异”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9c27c4a-e020-4fe3-9b5d-444551d16f67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12504, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "变体", "is_correct": true, "explanation": "“他设计了这个标志的变体”，指标志在形式上的变异形态，符合句意。"}, {"text": "雨", "is_correct": false, "explanation": "语义：“设计了……的雨”说不通，雨不是可以设计的对象。"}, {"text": "病", "is_correct": false, "explanation": "搭配：“设计”的对象是图形、作品，不能说“设计……的病”。"}, {"text": "雾", "is_correct": false, "explanation": "语义：雾不是标志，“标志的雾”说不通。"}], "explanations": {"变体": "“他设计了这个标志的变体”，指标志在形式上的变异形态，符合句意。", "雨": "语义：“设计了……的雨”说不通，雨不是可以设计的对象。", "病": "搭配：“设计”的对象是图形、作品，不能说“设计……的病”。", "雾": "语义：雾不是标志，“标志的雾”说不通。"}, "sentence_index": 6, "correct_answer": "变体"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的性格有了很大的变体。", "explanation": "这里应该用〈转变〉。变体指形式上的变异形态，不用来说性格的转变过程。"}, {"text": "这个金属雕塑因为高温变体了。", "explanation": "这里应该用〈变形〉。变体是名词，不能作动词谓语，动词要说“变形”。"}, {"text": "这个机器的零件变体了。", "explanation": "这里应该用〈更换〉。“变体”指同一事物的变异形态，不能用作“换掉”的动词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9c27c4a-e020-4fe3-9b5d-444551d16f67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12504, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他找到了一只变体。", "corrected_sentence": "他找到了一种变体。", "error_description": "量词错误：“只”多用于动物或成对物件中的一个，变体应用“种”。正确说法是“一种变体”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9c27c4a-e020-4fe3-9b5d-444551d16f67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12504, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个标志有一条变体。", "corrected_sentence": "这个标志有一种变体。", "error_description": "量词错误：“条”用于线状或条状的东西，变体应用“种”。正确说法是“一种变体”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a9c27c4a-e020-4fe3-9b5d-444551d16f67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12505, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3184cbfb-ccef-4da5-9b5b-262a5981fc67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12505, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3184cbfb-ccef-4da5-9b5b-262a5981fc67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12505, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "可以被回收和重复使用的物理材料", "primary_collocate": null, "pronunciation": "wù zhì", "ipa": "u⁵¹ ʈʂʅ⁵¹", "syllable_count": 2, "sentences": [{"text": "经过公开征集，年轻平面设计师的提案最终胜出：三条首尾相连的箭头构成莫比乌斯环的变体，既暗示物质的无限循环，又通过动态线条传递持续运动的能量感。", "target_word": "物质", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "废旧电池中的有用物质可以回收再利用。", "target_word": "物质", "complexity_tier": "T3", "furigana": "fèi jiù diàn chí zhōng de yǒu yòng wù zhì kě yǐ huí shōu zài lì yòng", "sentence_source": "generated"}, {"text": "这些有机物质经过处理后可以重复使用。", "target_word": "物质", "complexity_tier": "T3", "furigana": "zhè xiē yǒu jī wù zhì jīng guò chǔ lǐ hòu kě yǐ chóng fù shǐ yòng", "sentence_source": "generated"}, {"text": "工厂把回收的有用物质加工成新产品。", "target_word": "物质", "complexity_tier": "T3", "furigana": "gōng chǎng bǎ huí shōu de yǒu yòng wù zhì jiā gōng chéng xīn chǎn pǐn", "sentence_source": "generated"}, {"text": "这些物质不能直接丢进垃圾桶。", "target_word": "物质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "废纸中的纤维物质可以回收再利用。", "target_word": "物质", "complexity_tier": "T3", "furigana": "fèi zhǐ zhōng de xiān wéi wù zhì kě yǐ huí shōu zài lì yòng", "sentence_source": "generated"}, {"text": "回收站收集各种可以再用的物质。", "target_word": "物质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把能回收的物质放进蓝色箱子。", "target_word": "物质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种有用物质用完后还能重新利用。", "target_word": "物质", "complexity_tier": "T3", "furigana": "zhè zhǒng yǒu yòng wù zhì yòng wán hòu hái néng chóng xīn lì yòng", "sentence_source": "generated"}, {"text": "旧衣服中的纤维物质也可以重新利用。", "target_word": "物质", "complexity_tier": "T3", "furigana": "jiù yī fu zhōng de xiān wéi wù zhì yě kě yǐ chóng xīn lì yòng", "sentence_source": "generated"}], "morphological_forms": [{"form": "物质文明", "label": "复合"}, {"form": "物質", "label": "繁体"}], "register": "中性", "sense_fingerprint": "可回收、可重复使用的物理材料", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a822219-d160-4040-9f20-f9a414303bd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12505, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "物质", "is_correct": true, "explanation": "物质（wù zhì）指可以被回收和重复使用的物理材料。"}, {"text": "务实", "is_correct": false, "explanation": "务实（wù shí）与物质（wù zhì）的第二音节声母不同（shí 为 sh，zhì 为 zh），意思是注重实际。"}, {"text": "误植", "is_correct": false, "explanation": "误植（wù zhí）第二音节 zhí 为第二声，与 zhì（第四声）声调不同，意思是排版时出现的错字。"}, {"text": "无知", "is_correct": false, "explanation": "无知（wú zhī）第一音节 wú 为第二声，与 wù（第四声）声调不同，意思是缺乏知识。"}, {"text": "误事", "is_correct": false, "explanation": "误事（wù shì）第二音节 shì 与 zhì 声母不同（sh 与 zh），意思是耽误事情。"}], "explanations": {"物质": "物质（wù zhì）指可以被回收和重复使用的物理材料。", "务实": "务实（wù shí）与物质（wù zhì）的第二音节声母不同（shí 为 sh，zhì 为 zh），意思是注重实际。", "误植": "误植（wù zhí）第二音节 zhí 为第二声，与 zhì（第四声）声调不同，意思是排版时出现的错字。", "无知": "无知（wú zhī）第一音节 wú 为第二声，与 wù（第四声）声调不同，意思是缺乏知识。", "误事": "误事（wù shì）第二音节 shì 与 zhì 声母不同（sh 与 zh），意思是耽误事情。"}, "sentence_index": null, "correct_answer": "物质"}, "level_3": {"options": [{"text": "物质", "is_correct": true, "explanation": "物质：指可回收、可重复使用的物理材料，与“无限循环”的语境相合。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格与莫比乌斯环所暗示的循环无关，句子说的是材料的循环。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“循环”一般不与“颜色”搭配，颜色也不能被“暗示”为无限循环。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是具体家具，不能作为抽象循环的对象。"}], "explanations": {"物质": "物质：指可回收、可重复使用的物理材料，与“无限循环”的语境相合。", "价格": "语义：价格与莫比乌斯环所暗示的循环无关，句子说的是材料的循环。", "颜色": "搭配：“循环”一般不与“颜色”搭配，颜色也不能被“暗示”为无限循环。", "桌子": "语义：桌子是具体家具，不能作为抽象循环的对象。"}, "sentence_index": 0, "correct_answer": "物质"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件衣服的物质很好，穿起来很舒服。", "explanation": "这里应该用〈质地〉。“物质”指可回收利用的物理材料，这里用来说衣服面料的好坏，是误用的义项；说布料好坏要用“质地”。"}, {"text": "他不追求物质，只关心精神生活。", "explanation": "这里应该用〈财富〉。「物质」在这里指物质财富，不是可回收利用的材料。"}, {"text": "这只物质可以回收再利用。", "explanation": "这里应该用〈种〉。“物质”是一类材料，量词用“种”；“只”多用于动物或成对物品中的单个。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3184cbfb-ccef-4da5-9b5b-262a5981fc67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12505, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "物质", "is_correct": true, "explanation": "物质（wù zhì）指可以被回收和重复使用的物理材料。"}, {"text": "武士", "is_correct": false, "explanation": "武士（wǔ shì）第一音节为第三声，第二音节声母为 sh（zhì 为 zh），意思是古代的战士。"}, {"text": "污渍", "is_correct": false, "explanation": "污渍（wū zì）第一音节为第一声，第二音节声母为 z（zhì 为 zh），意思是污迹。"}, {"text": "舞姿", "is_correct": false, "explanation": "舞姿（wǔ zī）两个音节的声调都与物质不同，第二音节声母为 z，意思是舞蹈的姿态。"}], "explanations": {"物质": "物质（wù zhì）指可以被回收和重复使用的物理材料。", "武士": "武士（wǔ shì）第一音节为第三声，第二音节声母为 sh（zhì 为 zh），意思是古代的战士。", "污渍": "污渍（wū zì）第一音节为第一声，第二音节声母为 z（zhì 为 zh），意思是污迹。", "舞姿": "舞姿（wǔ zī）两个音节的声调都与物质不同，第二音节声母为 z，意思是舞蹈的姿态。"}, "sentence_index": null, "correct_answer": "物质"}, "level_3": {"options": [{"text": "物质", "is_correct": true, "explanation": "物质：指可回收、可重复使用的物理材料，与“可以再用”相合。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气无法被回收站收集，也不是可以再用的物品。"}, {"text": "食品", "is_correct": false, "explanation": "语义：食品吃掉后就没有了，不能“再用”。"}, {"text": "时光", "is_correct": false, "explanation": "搭配：“收集”一般搭配具体物品，不说收集“时光”。"}], "explanations": {"物质": "物质：指可回收、可重复使用的物理材料，与“可以再用”相合。", "空气": "语义：空气无法被回收站收集，也不是可以再用的物品。", "食品": "语义：食品吃掉后就没有了，不能“再用”。", "时光": "搭配：“收集”一般搭配具体物品，不说收集“时光”。"}, "sentence_index": 6, "correct_answer": "物质"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他家境不好，物质条件很差，只好靠亲戚接济。", "explanation": "这里应该用〈经济条件〉。「物质条件」指生活的经济状况，不是可回收利用的材料。"}, {"text": "设计师用回收的旧布做物质，设计了一批包包。", "explanation": "这里应该用〈素材〉。“物质”指可回收利用的物理材料，用旧布做成包包的原料要说“素材”，不能说“做物质”。"}, {"text": "这条物质很旧，可以回收。", "explanation": "这里应该用〈种〉。“条”多用于细长的物件，“物质”是一类材料，量词用“种”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3184cbfb-ccef-4da5-9b5b-262a5981fc67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12505, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "回收中心把收来的三只物质分开存放。", "corrected_sentence": "回收中心把收来的三种物质分开存放。", "error_description": "量词错误：“物质”指一类材料，应该用量词“种”，不能用“只”。正确说法是“三种物质”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3184cbfb-ccef-4da5-9b5b-262a5981fc67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12505, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们以前回收着这种物质。", "corrected_sentence": "我们以前回收过这种物质。", "error_description": "体标错误：“以前”指过去的经历，表示曾经做过某事应用“过”，不能用表示持续的“着”。正确说法是“回收过这种物质”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3184cbfb-ccef-4da5-9b5b-262a5981fc67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
