INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12506, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3184cbfb-ccef-4da5-9b5b-262a5981fc67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12506, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指绘画、图形或物体表面细长而连续的痕迹或轮廓。", "primary_collocate": null, "pronunciation": "xiàn tiáo", "ipa": "ɕjɛn⁵¹ tʰjɑʊ³⁵", "syllable_count": 2, "sentences": [{"text": "经过公开征集，年轻平面设计师的提案最终胜出：三条首尾相连的箭头构成莫比乌斯环的变体，既暗示物质的无限循环，又通过动态线条传递持续运动的能量感。", "target_word": "线条", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "这幅画的线条很简单。", "target_word": "线条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用黑笔画出了清楚的线条。", "target_word": "线条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆车的线条很漂亮。", "target_word": "线条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说画人像时线条要流畅。", "target_word": "线条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "墙上有一些弯弯的线条。", "target_word": "线条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件衣服的线条让她显得很高。", "target_word": "线条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子在纸上画了很多线条。", "target_word": "线条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座楼的线条很直，看起来很现代。", "target_word": "线条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "画家用细细的线条画出了山。", "target_word": "线条", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "線條", "label": "繁体"}], "register": "中性", "sense_fingerprint": "绘画、图形或物体表面细长连续的痕迹或轮廓", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a822219-d160-4040-9f20-f9a414303bd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12506, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "线条", "is_correct": true, "explanation": "线条：指画面或物体表面细长连续的轮廓，与“动态”搭配，可以传递运动感。"}, {"text": "味道", "is_correct": false, "explanation": "语义：味道属于味觉，不能通过动态的设计来传递。"}, {"text": "面容", "is_correct": false, "explanation": "体貌：“面容”指人的脸，不能用于设计中的线条。"}, {"text": "温度", "is_correct": false, "explanation": "语义：温度是感觉的量，不能被画成可见的动态线条。"}], "explanations": {"线条": "线条：指画面或物体表面细长连续的轮廓，与“动态”搭配，可以传递运动感。", "味道": "语义：味道属于味觉，不能通过动态的设计来传递。", "面容": "体貌：“面容”指人的脸，不能用于设计中的线条。", "温度": "语义：温度是感觉的量，不能被画成可见的动态线条。"}, "sentence_index": 0, "correct_answer": "线条"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这根线条很长，可以拿来缝衣服。", "explanation": "这里应该用〈线〉。“线条”指画出或设计出的线，缝衣服的实物线要用“线”。"}, {"text": "这条公交线条很长，途经很多站。", "explanation": "这里应该用〈线路〉。“线条”指画面或物体表面的线痕，公交的走向要用“线路”。"}, {"text": "墙上有一座线条，很漂亮。", "explanation": "这里量词用错了，应该用〈条〉。线条是细长的痕迹，量词用“条”；“座”多用于山、楼、桥等大型物体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3184cbfb-ccef-4da5-9b5b-262a5981fc67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12506, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "线条", "is_correct": true, "explanation": "线条：指衣服的轮廓或设计线条，与“让她显得很高”的语境相合。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：衣服没有年龄，不能让人显得很高。"}, {"text": "名字", "is_correct": false, "explanation": "语义：衣服的名字不会让人显得很高。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：“身高”只用于人或动物，不能说衣服的身高。"}], "explanations": {"线条": "线条：指衣服的轮廓或设计线条，与“让她显得很高”的语境相合。", "年龄": "语义：衣服没有年龄，不能让人显得很高。", "名字": "语义：衣服的名字不会让人显得很高。", "身高": "搭配：“身高”只用于人或动物，不能说衣服的身高。"}, "sentence_index": 6, "correct_answer": "线条"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "墙上拉着几根线条，通着电。", "explanation": "这里应该用〈电线〉。“线条”指画出或设计出的线痕，墙上通电的实物线要用“电线”。"}, {"text": "画家用细细的一块线条画出了山。", "explanation": "这里量词用错了，应该用〈条〉。“块”用于成块的东西，线条是细长的，应该用“条”。"}, {"text": "画家用细细的一把线条画出了山。", "explanation": "这里量词用错了，应该用〈条〉。“把”用于有柄可握的东西，线条不用“把”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3184cbfb-ccef-4da5-9b5b-262a5981fc67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12506, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这幅素描里有三只线条很有力。", "corrected_sentence": "这幅素描里有三条线条很有力。", "error_description": "量词错误：“线条”是细长的痕迹，应该用量词“条”，不能用“只”。正确说法是“三条线条”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3184cbfb-ccef-4da5-9b5b-262a5981fc67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12506, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "画家以前过画这样的线条。", "corrected_sentence": "画家以前画过这样的线条。", "error_description": "“过”的位置错误：动态助词“过”应紧跟动词，应说“画过”，不能放在动词之前。正确说法是“画过这样的线条”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3184cbfb-ccef-4da5-9b5b-262a5981fc67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12509, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7deeda03-da33-4b74-a27c-2bf61f5f2016') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
