INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12510, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "function", "definition": "不用，不必", "primary_collocate": null, "pronunciation": "wú xū", "ipa": "u˧˥ ɕy˥", "syllable_count": 2, "sentences": [{"text": "此设计之精妙在于其多层次的象征意义——几何结构本身即是一种无需语言解释的全球通用语，而绿色的选择则强化了其与自然、生态的关联。", "target_word": "无需", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "在这家酒店住宿，无需提前付款。", "target_word": "无需", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小孩坐地铁无需买票。", "target_word": "无需", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个软件无需下载，打开网页就能用。", "target_word": "无需", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你已经准备好了，无需再担心。", "target_word": "无需", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "办理这项业务无需带身份证。", "target_word": "无需", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家餐厅的菜价很实惠，顾客无需提前预订。", "target_word": "无需", "complexity_tier": "T3", "furigana": "zhè jiā cān tīng de cài jià hěn shí huì, gù kè wú xū tí qián yù dìng.", "sentence_source": "generated"}, {"text": "我们住得很近，无需坐车。", "target_word": "无需", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "会员无需排队，可以直接进去。", "target_word": "无需", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "无需道歉，这不是你的错。", "target_word": "无需", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "书面语中表示没有必要做某事，相当于“不用、不必”，后面常接动词短语", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a822219-d160-4040-9f20-f9a414303bd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12510, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "无需", "is_correct": true, "explanation": "正确：「无需」表示不必，句意是几何结构本身不需要语言来解释。"}, {"text": "依赖", "is_correct": false, "explanation": "语义：「依赖」表示靠某物才能成立，与「几何结构本身即是」的自足含义相悖。"}, {"text": "离不开", "is_correct": false, "explanation": "语义：「离不开」表示不能缺少，与「全球通用语」无需语言辅助的设定相悖。"}, {"text": "需要", "is_correct": false, "explanation": "搭配：「全球通用语」的特点是无需解释，说「需要语言解释」与句中的设定正相反。"}], "explanations": {"无需": "正确：「无需」表示不必，句意是几何结构本身不需要语言来解释。", "依赖": "语义：「依赖」表示靠某物才能成立，与「几何结构本身即是」的自足含义相悖。", "离不开": "语义：「离不开」表示不能缺少，与「全球通用语」无需语言辅助的设定相悖。", "需要": "搭配：「全球通用语」的特点是无需解释，说「需要语言解释」与句中的设定正相反。"}, "sentence_index": 0, "correct_answer": "无需"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "公共场所请无需吸烟。", "explanation": "这里应该用〈不要〉。「无需」表示没有必要，不表示禁止，「请无需吸烟」只是说不必吸烟，意思不对。"}, {"text": "电梯里无需蹦跳。", "explanation": "这里应该用〈禁止〉。电梯里「禁止蹦跳」是提醒不要蹦跳，「无需」只表示不必，句子变成「不必蹦跳」，意思不对。"}, {"text": "司机无需酒后驾车。", "explanation": "这里应该用〈禁止〉。酒后驾车本应被禁止，「无需」只表示不必，句子却说司机不必酒后驾车，意思不对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3184cbfb-ccef-4da5-9b5b-262a5981fc67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12510, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "无需", "is_correct": true, "explanation": "正确：「无需」表示不必，句意是顾客不用提前预订。"}, {"text": "必须", "is_correct": false, "explanation": "语义：「必须」表示强制要求，与「无需」正相反，句子会变成必须预订。"}, {"text": "务必", "is_correct": false, "explanation": "语义：「务必」表示一定要，与「无需」的“不必”正相反，句子会变成顾客一定要提前预订。"}, {"text": "只好", "is_correct": false, "explanation": "语义：「只好」表示迫不得已，与「菜价很实惠」的轻松语境不符，也与「无需」的意思相反。"}], "explanations": {"无需": "正确：「无需」表示不必，句意是顾客不用提前预订。", "必须": "语义：「必须」表示强制要求，与「无需」正相反，句子会变成必须预订。", "务必": "语义：「务必」表示一定要，与「无需」的“不必”正相反，句子会变成顾客一定要提前预订。", "只好": "语义：「只好」表示迫不得已，与「菜价很实惠」的轻松语境不符，也与「无需」的意思相反。"}, "sentence_index": 6, "correct_answer": "无需"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "乘客无需系安全带。", "explanation": "这里应该用〈必须〉。安全带是要求必须系的，「无需」表示不必，句子变成「乘客不必系安全带」，与原意相反。"}, {"text": "消防演习时，大家无需撤离。", "explanation": "这里应该用〈应该〉。消防演习时大家应该撤离，「无需」表示不必，句子却说大家不必撤离，意思不对。"}, {"text": "考试期间，学生无需保持安静。", "explanation": "这里应该用〈要求〉。考试期间对学生有保持安静的要求，「无需」表示不必，与「要求」的意思相反，句子说学生不必保持安静，意思不对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3184cbfb-ccef-4da5-9b5b-262a5981fc67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12510, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这份资料不无需打印，直接发给我就行。", "corrected_sentence": "这份资料无需打印，直接发给我就行。", "error_description": "「无需」本身已表示否定，前面不能再加「不」。应去掉「不」，改为「无需打印」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3184cbfb-ccef-4da5-9b5b-262a5981fc67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12510, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家店的菜价很便宜，顾客无需了提前预订，直接来就行。", "corrected_sentence": "这家店的菜价很便宜，顾客无需提前预订，直接来就行。", "error_description": "「无需」后面不能接「了」。应去掉「了」，改为「无需提前预订」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3184cbfb-ccef-4da5-9b5b-262a5981fc67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
