INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12515, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "首先提出并号召他人参与的主张或行动。", "primary_collocate": null, "pronunciation": "chàng yì", "ipa": "ʈʂʰɑŋ˥˩ i˥˩", "syllable_count": 2, "sentences": [{"text": "尽管该标志最初仅为美国国内倡议服务，但其形式上的高度抽象性使其迅速跨越国界。", "target_word": "倡议", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "从城市规划的宏观视角审视，可持续性已从道德倡议转化为经济理性。", "target_word": "倡议", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "学校发出倡议，请同学们少用塑料袋。", "target_word": "倡议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市民积极响应保护河流的倡议。", "target_word": "倡议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这项倡议得到了许多国家的支持。", "target_word": "倡议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "联合国提出了一项新的环保倡议。", "target_word": "倡议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司接受了员工提出的节能倡议。", "target_word": "倡议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的倡议让大家开始重视健康。", "target_word": "倡议", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们都支持这个倡议。", "target_word": "倡议", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "社区发起了垃圾分类的倡议。", "target_word": "倡议", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "倡议书", "label": "复合"}, {"form": "倡议者", "label": "复合"}, {"form": "项", "label": "量词"}], "register": "书面", "sense_fingerprint": "率先提出并号召他人参与的主张或行动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '144bdcb8-b634-4814-93d5-bb47c40a03fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12515, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "倡议", "is_correct": true, "explanation": "正确：倡议指首先建议或发起某种主张、行动。"}, {"text": "抗议", "is_correct": false, "explanation": "kàng 与 chàng 声母不同（k 与 ch），意思是抗议。"}, {"text": "长椅", "is_correct": false, "explanation": "cháng（第二声）与 chàng（第四声）声调不同，yǐ 与 yì 声调也不同，意思是长椅。"}, {"text": "长衣", "is_correct": false, "explanation": "cháng 与 chàng 声调不同，yī 与 yì 声调也不同，意思是长衣服。"}], "explanations": {"倡议": "正确：倡议指首先建议或发起某种主张、行动。", "抗议": "kàng 与 chàng 声母不同（k 与 ch），意思是抗议。", "长椅": "cháng（第二声）与 chàng（第四声）声调不同，yǐ 与 yì 声调也不同，意思是长椅。", "长衣": "cháng 与 chàng 声调不同，yī 与 yì 声调也不同，意思是长衣服。"}, "sentence_index": null, "correct_answer": "倡议"}, "level_3": {"options": [{"text": "倡议", "is_correct": true, "explanation": "正确：倡议指首先提出的主张或行动，与“为美国国内……服务”相符。"}, {"text": "海外", "is_correct": false, "explanation": "语义：海外指国外，与句中的“美国国内”正好相反。"}, {"text": "战争", "is_correct": false, "explanation": "语义：战争与标志的服务对象不相符，句中强调的是国内服务。"}, {"text": "国境", "is_correct": false, "explanation": "搭配：国境指国家边界，不能与“服务”搭配。"}], "explanations": {"倡议": "正确：倡议指首先提出的主张或行动，与“为美国国内……服务”相符。", "海外": "语义：海外指国外，与句中的“美国国内”正好相反。", "战争": "语义：战争与标志的服务对象不相符，句中强调的是国内服务。", "国境": "搭配：国境指国家边界，不能与“服务”搭配。"}, "sentence_index": 0, "correct_answer": "倡议"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次调查的倡议显示，大多数学生都喜欢体育。", "explanation": "这里应该用〈结论〉。倡议指提出主张或发起行动，不指调查得出的结果。"}, {"text": "这家公司去年倡议了两款新手机。", "explanation": "这里应该用〈推出〉。倡议指提出主张或号召，不指公司把产品投放市场。"}, {"text": "我的倡议预测明天会下雨。", "explanation": "这里应该用〈预报〉。倡议指提出主张或号召，不用来说对天气的推断。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a54e2e0-9d56-4d45-81a7-812fd28216ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12515, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "倡议", "is_correct": true, "explanation": "正确：倡议指首先提出的主张或行动，与“公司接受了员工提出的……”的语境相符。"}, {"text": "嘲讽", "is_correct": false, "explanation": "语义：嘲讽指讥笑讽刺，与员工主动提出节能主张的语境不符。"}, {"text": "命令", "is_correct": false, "explanation": "语义：命令由上级发出，员工不能向公司下达命令，与句意不符。"}, {"text": "裁决", "is_correct": false, "explanation": "语义：裁决指裁定是非，与员工提出节能主张的语境不符。"}], "explanations": {"倡议": "正确：倡议指首先提出的主张或行动，与“公司接受了员工提出的……”的语境相符。", "嘲讽": "语义：嘲讽指讥笑讽刺，与员工主动提出节能主张的语境不符。", "命令": "语义：命令由上级发出，员工不能向公司下达命令，与句意不符。", "裁决": "语义：裁决指裁定是非，与员工提出节能主张的语境不符。"}, "sentence_index": 6, "correct_answer": "倡议"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校做出了一个倡议，全体学生都必须遵守。", "explanation": "这里应该用〈决定〉。倡议是号召他人自愿参与的主张，不带强制性，不能要求全体遵守。"}, {"text": "公司制定了一个倡议，下个月开始执行。", "explanation": "这里应该用〈计划〉。倡议是号召性的主张，不是按期执行的安排。"}, {"text": "老师发了一个倡议，要求大家周一交作业。", "explanation": "这里应该用〈通知〉。倡议用于号召自愿参与，不用于布置具体任务。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a54e2e0-9d56-4d45-81a7-812fd28216ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12515, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "社区发起了一只垃圾分类的倡议。", "corrected_sentence": "社区发起了一项垃圾分类的倡议。", "error_description": "错误：“只”用于动物或成对的物品，倡议的量词是“项”。正确形式为“一项垃圾分类的倡议”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a54e2e0-9d56-4d45-81a7-812fd28216ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12515, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大家响应了环保组织的一把节水倡议。", "corrected_sentence": "大家响应了环保组织的一项节水倡议。", "error_description": "错误：“把”用于有柄的器物，倡议的量词应为“项”。正确形式为“一项节水倡议”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a54e2e0-9d56-4d45-81a7-812fd28216ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12517, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "规律", "is_correct": false, "explanation": "无关：规律指事物发展中稳定的联系，与抽象性的任何义项都不构成反义。"}, {"text": "具体性", "is_correct": true, "explanation": "反义：具体性指事物可以看见、触摸、感受的特点，与抽象性相对。"}, {"text": "程序", "is_correct": false, "explanation": "无关：程序指做事的先后步骤，不是抽象性的对立面。"}, {"text": "效率", "is_correct": false, "explanation": "无关：效率指单位时间内的产出，与抽象性没有反义关系。"}], "correct_answer": "具体性", "explanations": {"规律": "无关：规律指事物发展中稳定的联系，与抽象性的任何义项都不构成反义。", "具体性": "反义：具体性指事物可以看见、触摸、感受的特点，与抽象性相对。", "程序": "无关：程序指做事的先后步骤，不是抽象性的对立面。", "效率": "无关：效率指单位时间内的产出，与抽象性没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93e36420-aa7c-4c6e-a47a-cf0756003382') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12517, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "矿石", "is_correct": false, "explanation": "无关：矿石指天然形成的矿物，与抽象性没有反义关系。"}, {"text": "厨房", "is_correct": false, "explanation": "无关：厨房是做饭的地方，与抽象性无关。"}, {"text": "具体性", "is_correct": true, "explanation": "反义：具体性指事物可以看见、触摸、感受的特点，与抽象性相对。"}, {"text": "电压", "is_correct": false, "explanation": "无关：电压是电路中的物理量，与抽象性无关。"}], "correct_answer": "具体性", "explanations": {"矿石": "无关：矿石指天然形成的矿物，与抽象性没有反义关系。", "厨房": "无关：厨房是做饭的地方，与抽象性无关。", "具体性": "反义：具体性指事物可以看见、触摸、感受的特点，与抽象性相对。", "电压": "无关：电压是电路中的物理量，与抽象性无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93e36420-aa7c-4c6e-a47a-cf0756003382') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12517, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "指事物中那些看不见、摸不着，但能通过思考来理解和把握的特点或性质，比如‘正义’、‘美丽’的概念。", "primary_collocate": null, "pronunciation": "chōu xiàng xìng", "ipa": "ʈʂʰoʊ˥ ɕjɑŋ˥˩ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "尽管该标志最初仅为美国国内倡议服务，但其形式上的高度抽象性使其迅速跨越国界。", "target_word": "抽象性", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "数学语言的抽象性很强，初学者常常觉得难懂。", "target_word": "抽象性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“自由”这个词的抽象性，让孩子很难理解。", "target_word": "抽象性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哲学讨论的抽象性，来自它研究的是看不见的道理。", "target_word": "抽象性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师用图片降低了这个概念的抽象性。", "target_word": "抽象性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法律条文的抽象性使普通人不容易读懂。", "target_word": "抽象性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了克服抽象性，作者举了很多生活中的例子。", "target_word": "抽象性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为抽象性强，这个理论需要用例子来说明。", "target_word": "抽象性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "语言学家认为，“时间”一词有很强的抽象性。", "target_word": "抽象性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这篇文章的抽象性很高，不是人人都能读懂。", "target_word": "抽象性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "抽象性|看不见摸不着、靠思考把握的概念特点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11b9558c-ba16-40e5-9481-34d3d74a317c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12517, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "抽象性", "is_correct": true, "explanation": "正确。抽象性指看不见、摸不着、需靠思考把握的特点，“形式上的高度抽象性”使标志能脱离具体国家，因而迅速跨越国界。"}, {"text": "封闭性", "is_correct": false, "explanation": "语义：封闭性指不对外开放，与“迅速跨越国界”正相反，句子说不通。"}, {"text": "地域性", "is_correct": false, "explanation": "语义：地域性使事物局限于一个地方，与“跨越国界”矛盾。"}, {"text": "私密性", "is_correct": false, "explanation": "搭配：“私密性”多用于隐私、空间，不用来形容标志的形式或传播。"}], "explanations": {"抽象性": "正确。抽象性指看不见、摸不着、需靠思考把握的特点，“形式上的高度抽象性”使标志能脱离具体国家，因而迅速跨越国界。", "封闭性": "语义：封闭性指不对外开放，与“迅速跨越国界”正相反，句子说不通。", "地域性": "语义：地域性使事物局限于一个地方，与“跨越国界”矛盾。", "私密性": "搭配：“私密性”多用于隐私、空间，不用来形容标志的形式或传播。"}, "sentence_index": 0, "correct_answer": "抽象性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这幅地图的抽象性很高，每条路和每栋楼都标得清清楚楚。", "explanation": "这里应该用〈具体性〉。地图标注的是看得见的路与楼，应说具体性高；抽象性指看不见、摸不着的概念特点。"}, {"text": "这个理论的抽象性很强，初学者一看就懂。", "explanation": "这里应该用〈通俗〉。通俗指浅显易懂；抽象性指不依赖具体形象的特点，与“一看就懂”相矛盾。"}, {"text": "这幅画的抽象性很强，一眼就能看出画的是谁。", "explanation": "这里应该用〈生动〉。生动指鲜明有画面感；抽象性指看不见、摸不着的特点，画中人物能一眼认出，与之相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93e36420-aa7c-4c6e-a47a-cf0756003382') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12517, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "抽象性", "is_correct": true, "explanation": "正确。抽象性是需要克服的理解障碍，“为了克服”正好接它。"}, {"text": "优越性", "is_correct": false, "explanation": "语义：优越性是优点，不是需要克服的困难，“克服优越性”说不通。"}, {"text": "便利性", "is_correct": false, "explanation": "语义：便利性是好处，人们不会想去克服它，句子说不通。"}, {"text": "美感", "is_correct": false, "explanation": "搭配：“克服”多接困难、障碍，不与“美感”搭配。"}], "explanations": {"抽象性": "正确。抽象性是需要克服的理解障碍，“为了克服”正好接它。", "优越性": "语义：优越性是优点，不是需要克服的困难，“克服优越性”说不通。", "便利性": "语义：便利性是好处，人们不会想去克服它，句子说不通。", "美感": "搭配：“克服”多接困难、障碍，不与“美感”搭配。"}, "sentence_index": 6, "correct_answer": "抽象性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这部小说的抽象性很强，读者仿佛看到了人物。", "explanation": "这里应该用〈形象性〉。形象性指能让人想象出具体的样子，与“仿佛看到了人物”相符；抽象性不依赖具体形象，说不通。"}, {"text": "这张图表的抽象性很强，一眼就能看懂。", "explanation": "这里应该用〈直观性〉。直观性指一眼就能理解，抽象性与“一眼就能看懂”相矛盾。"}, {"text": "这种农具的抽象性很强，农民每天都在用。", "explanation": "这里应该用〈实用性〉。实用性指能直接用于生产生活；抽象性指看不见、摸不着的特点，农具是实物，与“每天都在用”不符。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93e36420-aa7c-4c6e-a47a-cf0756003382') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12517, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这门课有一只很强的抽象性，学生常常需要反复练习。", "corrected_sentence": "这门课有一种很强的抽象性，学生常常需要反复练习。", "error_description": "“抽象性”前的量词用错：“只”多用于动物或成对物品之一，应改为“种”，即“一种很强的抽象性”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93e36420-aa7c-4c6e-a47a-cf0756003382') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12517, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这套理论的抽象性高很，需要慢慢理解。", "corrected_sentence": "这套理论的抽象性很高，需要慢慢理解。", "error_description": "补语位置错：程度副词“很”应放在形容词前，正确说法是“很高”，不能说“高很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93e36420-aa7c-4c6e-a47a-cf0756003382') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12523, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "结构", "is_correct": false, "explanation": "无关：结构指各部分的组织方式，与趋同没有反义关系。"}, {"text": "资源", "is_correct": false, "explanation": "无关：资源指可利用的物质或条件，与趋同无关。"}, {"text": "趋异", "is_correct": true, "explanation": "反义：趋异指事物朝不同方向发展，与趋同相对。"}, {"text": "框架", "is_correct": false, "explanation": "无关：框架指事物的基本架子，与趋同无关。"}], "correct_answer": "趋异", "explanations": {"结构": "无关：结构指各部分的组织方式，与趋同没有反义关系。", "资源": "无关：资源指可利用的物质或条件，与趋同无关。", "趋异": "反义：趋异指事物朝不同方向发展，与趋同相对。", "框架": "无关：框架指事物的基本架子，与趋同无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93e36420-aa7c-4c6e-a47a-cf0756003382') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12523, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "工序", "is_correct": false, "explanation": "无关：工序指生产中的一道道步骤，与趋同没有反义关系。"}, {"text": "途径", "is_correct": false, "explanation": "无关：途径指到达目的的路线或方法，与趋同无关。"}, {"text": "氛围", "is_correct": false, "explanation": "无关：氛围指周围的气氛，与趋同无关。"}, {"text": "趋异", "is_correct": true, "explanation": "反义：趋异指事物朝不同方向发展，与趋同相对。"}], "correct_answer": "趋异", "explanations": {"工序": "无关：工序指生产中的一道道步骤，与趋同没有反义关系。", "途径": "无关：途径指到达目的的路线或方法，与趋同无关。", "氛围": "无关：氛围指周围的气氛，与趋同无关。", "趋异": "反义：趋异指事物朝不同方向发展，与趋同相对。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93e36420-aa7c-4c6e-a47a-cf0756003382') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12523, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指不同的事物或现象向相同的方向发展或演变。", "primary_collocate": null, "pronunciation": "qū tóng", "ipa": "tɕʰy˥ tʰʊŋ˧˥", "syllable_count": 2, "sentences": [{"text": "至1980年代，随着跨国供应链的扩展与环保法规的趋同，这一标志已出现在欧洲、东亚及南美洲的各类包装物上，演变为事实上的国际惯例。", "target_word": "趋同", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "两国的饮食习惯出现了趋同。", "target_word": "趋同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "全球化让各国的文化出现趋同的现象。", "target_word": "趋同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机的外形设计越来越趋同。", "target_word": "趋同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家认为，城市建设的趋同会让城市失去特点。", "target_word": "趋同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市场竞争使不同企业的产品趋同。", "target_word": "趋同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两种语言在长期接触中，语法出现了趋同。", "target_word": "趋同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经济发展水平的趋同，有利于地区合作。", "target_word": "趋同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学者发现，不同地区的教育标准正在趋同。", "target_word": "趋同", "complexity_tier": "T3", "furigana": "xué zhě fā xiàn bù tóng dì qū de jiào yù biāo zhǔn zhèng zài qū tóng", "sentence_source": "generated"}, {"text": "各大银行的服务正在走向趋同。", "target_word": "趋同", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "趨同", "label": "繁体"}, {"form": "趋同化", "label": "复合"}, {"form": "趋同性", "label": "复合"}], "register": "书面", "sense_fingerprint": "趋同|不同的事物或现象向相同方向发展演变", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11b9558c-ba16-40e5-9481-34d3d74a317c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12523, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "趋同", "is_correct": true, "explanation": "正确。趋同指不同事物向相同方向发展，与句中“演变为国际惯例”吻合。"}, {"text": "分裂", "is_correct": false, "explanation": "语义：分裂与“扩展”和“国际惯例”的走向相反，句子说不通。"}, {"text": "隔离", "is_correct": false, "explanation": "语义：隔离会阻断传播，与标志出现在各地、成为惯例相矛盾。"}, {"text": "垄断", "is_correct": false, "explanation": "搭配：“法规”不与“垄断”搭配，且垄断不能形成国际惯例。"}], "explanations": {"趋同": "正确。趋同指不同事物向相同方向发展，与句中“演变为国际惯例”吻合。", "分裂": "语义：分裂与“扩展”和“国际惯例”的走向相反，句子说不通。", "隔离": "语义：隔离会阻断传播，与标志出现在各地、成为惯例相矛盾。", "垄断": "搭配：“法规”不与“垄断”搭配，且垄断不能形成国际惯例。"}, "sentence_index": 0, "correct_answer": "趋同"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这几家工厂趋同复工，市场一下子热闹起来。", "explanation": "这里应该用〈同时〉。同时指在同一时间发生；趋同强调不同事物逐渐靠拢的过程，不能用来描述同一时间的复工。"}, {"text": "双胞胎的脸型很趋同，连家人都难分辨。", "explanation": "这里应该用〈相似〉。趋同指不同事物朝同一方向靠拢的过程，描述已经很像的状态用相似。"}, {"text": "他的性格越来越趋同。", "explanation": "这里应该用〈变化〉。趋同需要两个以上不同的事物朝同一方向靠拢，只说一个人的性格，不能用趋同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93e36420-aa7c-4c6e-a47a-cf0756003382') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12523, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "趋同", "is_correct": true, "explanation": "正确。两种语言长期接触后，语法向相同方向靠拢，正是“趋同”的意思。"}, {"text": "寿命", "is_correct": false, "explanation": "搭配：“寿命”指存在的时间，语法不说“出现了寿命”。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格是商品的钱数，语法没有价格，句子说不通。"}, {"text": "重量", "is_correct": false, "explanation": "语义：重量是物体的属性，语法不具有重量，句子说不通。"}], "explanations": {"趋同": "正确。两种语言长期接触后，语法向相同方向靠拢，正是“趋同”的意思。", "寿命": "搭配：“寿命”指存在的时间，语法不说“出现了寿命”。", "价格": "语义：价格是商品的钱数，语法没有价格，句子说不通。", "重量": "语义：重量是物体的属性，语法不具有重量，句子说不通。"}, "sentence_index": 6, "correct_answer": "趋同"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "两家公司合作多年，技术终于趋同成一体。", "explanation": "这里应该用〈融合〉。融合指合为一体；趋同只指朝相同方向靠拢，不能说“成一体”。"}, {"text": "两家商店的销量瞬间趋同，老板们都很焦急。", "explanation": "这里应该用〈同步〉。趋同指逐渐靠拢的过程，不能与“瞬间”搭配；同时发生的变化应说〈同步〉。"}, {"text": "我的爱好越来越趋同。", "explanation": "这里应该用〈改变〉。趋同需要多个不同事物靠拢，单独一个人的爱好不能用趋同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93e36420-aa7c-4c6e-a47a-cf0756003382') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12523, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这两家公司的价格越来越被趋同，消费者很难选择。", "corrected_sentence": "这两家公司的价格越来越趋同，消费者很难选择。", "error_description": "“趋同”是不及物动词，不能用“被”字句表示被动。应去掉“被”，说“价格越来越趋同”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93e36420-aa7c-4c6e-a47a-cf0756003382') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12523, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这套标准逐渐趋同国际水平，企业更容易合作。", "corrected_sentence": "这套标准逐渐趋同于国际水平，企业更容易合作。", "error_description": "介词“于”漏掉：“趋同”后要接“于”，应说“趋同于国际水平”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93e36420-aa7c-4c6e-a47a-cf0756003382') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12524, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93e36420-aa7c-4c6e-a47a-cf0756003382') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
