INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12525, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93e36420-aa7c-4c6e-a47a-cf0756003382') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12525, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "用来表示所说的话是真实的，相当于‘实际上’。", "primary_collocate": null, "pronunciation": "shì shí shàng", "ipa": "ʂɻ̩˥˩ ʂɻ̩˧˥ ʂɑŋ˥˩", "syllable_count": 3, "sentences": [{"text": "至1980年代，随着跨国供应链的扩展与环保法规的趋同，这一标志已出现在欧洲、东亚及南美洲的各类包装物上，事实上已演变为国际惯例。", "target_word": "事实上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路看着很远，事实上走十分钟就到了。", "target_word": "事实上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说得对，事实上我们真的没有认真复习。", "target_word": "事实上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多人觉得汉字难，事实上只要多写就能记住。", "target_word": "事实上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都以为他不懂，事实上他比谁都清楚。", "target_word": "事实上", "complexity_tier": "T3", "furigana": "dàjiā dōu yǐwéi tā bù dǒng，shì shí shàng tā bǐ shéi dōu qīngchu。", "sentence_source": "generated"}, {"text": "外面看着很旧，事实上这房子刚盖好两年。", "target_word": "事实上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你以为他不知道？事实上他早就听说了。", "target_word": "事实上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人人都说这里安全，事实上也确实没出过事。", "target_word": "事实上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他嘴上说不喜欢，事实上天天都在用这个手机。", "target_word": "事实上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "事实上，这家公司去年就已经搬到上海了。", "target_word": "事实上", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "强调所说的内容是实际情况，相当于“实际上”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11b9558c-ba16-40e5-9481-34d3d74a317c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12525, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "事实上", "is_correct": true, "explanation": "正确：“事实上”引出已经发生的实际情况，与“已演变为国际惯例”吻合。"}, {"text": "短暂", "is_correct": false, "explanation": "语义：“短暂”指持续时间不长，与“惯例”需要长期稳定的意思相矛盾。"}, {"text": "个人", "is_correct": false, "explanation": "语义：“个人”指单独的人，与“国际”相矛盾。"}, {"text": "喜欢", "is_correct": false, "explanation": "搭配：“喜欢”不能用来说明惯例的演变，句子说不通。"}], "explanations": {"事实上": "正确：“事实上”引出已经发生的实际情况，与“已演变为国际惯例”吻合。", "短暂": "语义：“短暂”指持续时间不长，与“惯例”需要长期稳定的意思相矛盾。", "个人": "语义：“个人”指单独的人，与“国际”相矛盾。", "喜欢": "搭配：“喜欢”不能用来说明惯例的演变，句子说不通。"}, "sentence_index": 0, "correct_answer": "事实上"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "请大家事实上保持安静。", "explanation": "这里不能用〈事实上〉。“事实上”表示所说的是真实情况（相当于〈实际上〉），不能用在要求别人做事的句子里，这里应去掉“事实上”。"}, {"text": "如果明天下雨，事实上我们就不去了。", "explanation": "这里不能用〈事实上〉。“事实上”表示已经存在或已经确定的真实情况（相当于〈实际上〉），而假设句陈述的不是真实情况，应去掉“事实上”。"}, {"text": "我已经同意了，事实上我还没有考虑这件事。", "explanation": "这里不能用〈事实上〉。“事实上”陈述的是真实情况（相当于〈实际上〉），而“已经同意”与“还没有考虑”前后矛盾，不能同时为真。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93e36420-aa7c-4c6e-a47a-cf0756003382') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12525, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "事实上", "is_correct": true, "explanation": "正确：“事实上”引出真实情况，与“你以为他不知道”形成对比，后面说他早就听说了。"}, {"text": "突然", "is_correct": false, "explanation": "语义：“突然”指忽然发生，与“早就”表示很久以前已经发生的意思相矛盾。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”指不常发生，与“早就”表示已经发生相矛盾。"}, {"text": "赶紧", "is_correct": false, "explanation": "搭配：“赶紧”表示急忙去做，与“早就”表示已经发生的意思不能搭配。"}], "explanations": {"事实上": "正确：“事实上”引出真实情况，与“你以为他不知道”形成对比，后面说他早就听说了。", "突然": "语义：“突然”指忽然发生，与“早就”表示很久以前已经发生的意思相矛盾。", "偶尔": "语义：“偶尔”指不常发生，与“早就”表示已经发生相矛盾。", "赶紧": "搭配：“赶紧”表示急忙去做，与“早就”表示已经发生的意思不能搭配。"}, "sentence_index": 6, "correct_answer": "事实上"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们事实上先吃饭，再去看电影。", "explanation": "这里不能用〈事实上〉。“事实上”只表示所说的是真实情况（相当于〈实际上〉），不表示动作的先后，应去掉“事实上”。"}, {"text": "他每天都在工作，事实上他从来不工作。", "explanation": "这里不能用〈事实上〉。“事实上”表示所说的是真实情况（相当于〈实际上〉），与前句“每天都在工作”矛盾，前后陈述不能同时为真。"}, {"text": "这家公司去年没有搬家，事实上却搬到了上海。", "explanation": "这里不能用〈事实上〉。“事实上”陈述的是真实情况（相当于〈实际上〉），与前句“没有搬家”矛盾，前后陈述不能同时为真。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93e36420-aa7c-4c6e-a47a-cf0756003382') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12525, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种做法很事实上已成为标准。", "corrected_sentence": "这种做法事实上已成为标准。", "error_description": "“事实上”是副词，不能与程度副词“很”叠用，应去掉“很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93e36420-aa7c-4c6e-a47a-cf0756003382') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12525, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老板说没人加班，很事实上大家都在加班。", "corrected_sentence": "老板说没人加班，事实上大家都在加班。", "error_description": "“事实上”是副词，不能被程度副词“很”修饰，应去掉“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93e36420-aa7c-4c6e-a47a-cf0756003382') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
