INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12526, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "在国际交往中逐渐形成并为各国普遍遵守的习惯做法和规则。", "primary_collocate": null, "pronunciation": "guó jì guàn lì", "ipa": "kwo˧˥ tɕi˥˩ kwan˥˩ li˥˩", "syllable_count": 4, "sentences": [{"text": "至1980年代，随着跨国供应链的扩展与环保法规的趋同，这一标志已出现在欧洲、东亚及南美洲的各类包装物上，演变为事实上的国际惯例。", "target_word": "国际惯例", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "按照国际惯例，大使要向所在国递交国书。", "target_word": "国际惯例", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "各国公司做生意，都要遵守国际惯例。", "target_word": "国际惯例", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这样做不符合国际惯例，别的国家不会同意。", "target_word": "国际惯例", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在国际惯例里，海上的船遇到危险要发出求救信号。", "target_word": "国际惯例", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外交官在别国有特殊的保护，这是国际惯例。", "target_word": "国际惯例", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司的做法和国际惯例不一样。", "target_word": "国际惯例", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国际惯例是各国慢慢形成的，不是一个国家定的。", "target_word": "国际惯例", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他懂国际惯例，所以谈判时很顺利。", "target_word": "国际惯例", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要学习国际惯例，才能和外国人合作。", "target_word": "国际惯例", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "正式", "sense_fingerprint": "国际交往中逐渐形成、各国普遍遵守的习惯做法和规则", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11b9558c-ba16-40e5-9481-34d3d74a317c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12526, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "国际惯例", "is_correct": true, "explanation": "正确：「事实上的国际惯例」指各国普遍遵守的做法，与前文「跨国」「趋同」的语境相符。"}, {"text": "个人习惯", "is_correct": false, "explanation": "语义：「个人习惯」只属于个人，与前文说的跨国、各国普遍接受的情况不符。"}, {"text": "行话", "is_correct": false, "explanation": "语域：「行话」是行业内部的专门用语，与这里描述国际交往习惯的语域不符。"}, {"text": "国家标准", "is_correct": false, "explanation": "语义：「国家标准」限于一个国家，与句中「跨国供应链」「欧洲、东亚及南美洲」的跨国语境相矛盾。"}], "explanations": {"国际惯例": "正确：「事实上的国际惯例」指各国普遍遵守的做法，与前文「跨国」「趋同」的语境相符。", "个人习惯": "语义：「个人习惯」只属于个人，与前文说的跨国、各国普遍接受的情况不符。", "行话": "语域：「行话」是行业内部的专门用语，与这里描述国际交往习惯的语域不符。", "国家标准": "语义：「国家标准」限于一个国家，与句中「跨国供应链」「欧洲、东亚及南美洲」的跨国语境相矛盾。"}, "sentence_index": 0, "correct_answer": "国际惯例"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这种产品的尺寸要符合国际惯例，才能在欧洲销售。", "explanation": "这里应该用〈国际标准〉。惯例指长期形成的做法，尺寸等技术指标要用标准。"}, {"text": "这次会议只做了一个决定，就被大家称为国际惯例。", "explanation": "这里应该用〈先例〉。惯例是长期形成、普遍遵守的做法，一次决定还不能称为惯例。"}, {"text": "各国签署了国际惯例，规定了海上救援的义务。", "explanation": "这里应该用〈国际公约〉。惯例是各国逐渐形成的做法，不是经签署的条约。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93e36420-aa7c-4c6e-a47a-cf0756003382') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12526, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "国际惯例", "is_correct": true, "explanation": "正确：「和国际惯例不一样」是在比较两种做法，「国际惯例」与「公司的做法」属于同类对象。"}, {"text": "天气", "is_correct": false, "explanation": "语义：「天气」不是可以与「做法」相比较的对象，句子说不通。"}, {"text": "心情", "is_correct": false, "explanation": "搭配：「和……不一样」要求比较同类对象，「心情」不能与「做法」相比。"}, {"text": "俚语", "is_correct": false, "explanation": "语域：「俚语」属于口语俗语，与句中正式的商业语境不搭。"}], "explanations": {"国际惯例": "正确：「和国际惯例不一样」是在比较两种做法，「国际惯例」与「公司的做法」属于同类对象。", "天气": "语义：「天气」不是可以与「做法」相比较的对象，句子说不通。", "心情": "搭配：「和……不一样」要求比较同类对象，「心情」不能与「做法」相比。", "俚语": "语域：「俚语」属于口语俗语，与句中正式的商业语境不搭。"}, "sentence_index": 6, "correct_answer": "国际惯例"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个组织制定了国际惯例，帮助成员国处理纠纷。", "explanation": "这里应该用〈国际准则〉。惯例是各国在交往中逐渐形成的，不是由组织制定的。"}, {"text": "他每天晨跑已经成了国际惯例。", "explanation": "这里应该用〈个人习惯〉。国际惯例指世界上多数国家共同遵守的做法，个人每天晨跑只是他自己的习惯，不属于这一范围。"}, {"text": "两家公司签订了国际惯例，约定了付款时间。", "explanation": "这里应该用〈合同〉。惯例是长期形成的做法，不是书面协议，不能签订。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93e36420-aa7c-4c6e-a47a-cf0756003382') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12526, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这一做法已经成为一本国际惯例。", "corrected_sentence": "这一做法已经成为一项国际惯例。", "error_description": "错误：量词「本」用错。正确：「本」用于书籍，抽象的「国际惯例」应使用量词「项」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93e36420-aa7c-4c6e-a47a-cf0756003382') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12526, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们在谈判中都要做国际惯例。", "corrected_sentence": "我们在谈判中都要遵守国际惯例。", "error_description": "错误：「做」不能带「惯例」作宾语。正确：「国际惯例」应与「遵守」搭配，说「遵守国际惯例」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93e36420-aa7c-4c6e-a47a-cf0756003382') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
