INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12527, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指将事物根据特定地区的文化、语言、习惯等进行调整，使其更容易被当地人接受和使用。", "primary_collocate": null, "pronunciation": "běn tǔ huà", "ipa": "pən˨˩˦ tʰu˨˩˦ xua˥˩", "syllable_count": 3, "sentences": [{"text": "值得注意的是，其普及过程并非线性推进，而是伴随着各国本土化调整：例如在某些文化语境中，箭头形态被微调以避免宗教联想；而在另一些地区，则附加数字编码系统以细化分类标准。", "target_word": "本土化", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这家公司很重视产品的本土化。", "target_word": "本土化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这款游戏的本土化做得很好。", "target_word": "本土化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影的本土化让更多观众看懂了故事。", "target_word": "本土化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "快餐店的本土化，就是菜单加入当地口味。", "target_word": "本土化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "软件本土化需要翻译，还要符合当地习惯。", "target_word": "本土化", "complexity_tier": "T3", "furigana": "běntǔhuà", "sentence_source": "generated"}, {"text": "他研究外国连锁店在中国的本土化。", "target_word": "本土化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司的本土化过程用了三年。", "target_word": "本土化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "本土化是外国品牌成功的重要一步。", "target_word": "本土化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个品牌的本土化已经完成了。", "target_word": "本土化", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "本土化策略", "label": "复合"}], "register": "中性", "sense_fingerprint": "本土化|名词|外来事物按当地文化习惯调整的过程", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b45df6f4-fea3-4a2d-97bd-60bf38d18862') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12527, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "本土化", "is_correct": true, "explanation": "正确：本土化指按当地文化、习惯调整事物，句中的例子（箭头形态、宗教联想）正是文化层面的调整。"}, {"text": "商业化", "is_correct": false, "explanation": "语义：句中的例子讲的是文化语境中的调整，不是商业化。"}, {"text": "工业化", "is_correct": false, "explanation": "语义：句中强调的是文化与分类标准，不涉及生产方式的工业化。"}, {"text": "城镇化", "is_correct": false, "explanation": "语义：句中的例子与城镇发展无关，“城镇化调整”无法解释后面的宗教联想例子。"}], "explanations": {"本土化": "正确：本土化指按当地文化、习惯调整事物，句中的例子（箭头形态、宗教联想）正是文化层面的调整。", "商业化": "语义：句中的例子讲的是文化语境中的调整，不是商业化。", "工业化": "语义：句中强调的是文化与分类标准，不涉及生产方式的工业化。", "城镇化": "语义：句中的例子与城镇发展无关，“城镇化调整”无法解释后面的宗教联想例子。"}, "sentence_index": 0, "correct_answer": "本土化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座老城的本土化越来越明显，街上全是咖啡馆。", "explanation": "这里应该用〈西化〉。本土化指使事物适应当地，街上全是咖啡馆说明的是外来风格增多，要用西化。"}, {"text": "这家餐厅把菜单全换成了英文，本土化得很彻底。", "explanation": "这里应该用〈国际化〉。本土化指适应当地，菜单全换成英文是面向外国顾客，要用国际化。"}, {"text": "这座山的本土化让它的海拔升高了一百米。", "explanation": "这里应该用〈隆起〉。本土化指使事物适应当地的文化习惯，山体海拔升高是地壳运动，要用隆起。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3be19b42-deb0-4855-8824-60c9946ebe8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12527, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "本土化", "is_correct": true, "explanation": "正确：本土化指使外国事物适应中国的情况，“外国连锁店在中国的本土化”符合这一意思。"}, {"text": "老龄化", "is_correct": false, "explanation": "语义：老龄化指人口年龄结构的变化，不能用来说连锁店。"}, {"text": "脱水", "is_correct": false, "explanation": "语义：脱水指去除水分，与研究连锁店无关，句中说不通。"}, {"text": "学术化", "is_correct": false, "explanation": "搭配：学术化多用于研究方法或领域，不说“连锁店的学术化”。"}], "explanations": {"本土化": "正确：本土化指使外国事物适应中国的情况，“外国连锁店在中国的本土化”符合这一意思。", "老龄化": "语义：老龄化指人口年龄结构的变化，不能用来说连锁店。", "脱水": "语义：脱水指去除水分，与研究连锁店无关，句中说不通。", "学术化": "搭配：学术化多用于研究方法或领域，不说“连锁店的学术化”。"}, "sentence_index": 6, "correct_answer": "本土化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家公司正在推进本土化，把中国的工厂全部关闭了。", "explanation": "这里应该用〈撤出〉。本土化指适应当地、扎根当地，关闭中国的工厂是撤出，要用撤出。"}, {"text": "这个小镇正在推进本土化，新楼越来越多。", "explanation": "这里应该用〈城市化〉。本土化讲的是适应当地，新楼增多、人口聚集是城市化的过程。"}, {"text": "这家公司的业务本土化了，在十个国家全都停业了。", "explanation": "这里应该用〈退出〉。本土化强调适应当地、扎根当地，在十个国家全部停业是退出市场，要用退出。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3be19b42-deb0-4855-8824-60c9946ebe8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12527, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只本土化很成功。", "corrected_sentence": "这次本土化很成功。", "error_description": "错误：量词用了“只”。正确：应用“次”。本土化指一个过程，过程用“次”计量；“只”用于动物或成对的东西，不能用于本土化。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3be19b42-deb0-4855-8824-60c9946ebe8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12527, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家公司的本土化了很有必要。", "corrected_sentence": "这家公司的本土化很有必要。", "error_description": "错误：“本土化”后面多了“了”。正确：去掉“了”。作名词的“本土化”表示过程，后面不能直接加“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3be19b42-deb0-4855-8824-60c9946ebe8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12528, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3be19b42-deb0-4855-8824-60c9946ebe8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12528, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3be19b42-deb0-4855-8824-60c9946ebe8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12528, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "对模型、系统、技能或其他事物进行小的调整，使其表现更佳。", "primary_collocate": null, "pronunciation": "wēi diào", "ipa": "weɪ˥ tiɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "值得注意的是，其普及过程并非线性推进，而是伴随着各国本土化调整：例如在某些文化语境中，箭头形态被微调以避免宗教联想；而在另一些地区，则附加数字编码系统以细化分类标准。", "target_word": "微调", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "工程师把模型的参数微调了一下。", "target_word": "微调", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师请我把作文的开头微调一下。", "target_word": "微调", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教练微调了球队的比赛方法。", "target_word": "微调", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个系统需要再微调一下，才能用。", "target_word": "微调", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "摄影师微调了灯光，照片更亮了。", "target_word": "微调", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们微调了系统的算法，识别准确率提高了。", "target_word": "微调", "complexity_tier": "T3", "furigana": "wēitiáo", "sentence_source": "generated"}, {"text": "她把音量微调了一下。", "target_word": "微调", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司微调价格后，买的人多了。", "target_word": "微调", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "歌手微调了唱法，声音更好听了。", "target_word": "微调", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "微调了", "label": "体标"}, {"form": "微调过", "label": "体标"}, {"form": "微調", "label": "繁体"}], "register": "中性", "sense_fingerprint": "微调|动词|对模型系统技能等事物做小幅调整以提升表现", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b45df6f4-fea3-4a2d-97bd-60bf38d18862') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12528, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "微调", "is_correct": true, "explanation": "正确：微调指小幅调整，使箭头形态经过细微改动以避免宗教联想。"}, {"text": "冷冻", "is_correct": false, "explanation": "语义：冷冻是降低温度使物体凝固，与避免宗教联想无关。"}, {"text": "点亮", "is_correct": false, "explanation": "语义：点亮指让物体发光，不能用来避免宗教联想。"}, {"text": "脱水", "is_correct": false, "explanation": "语义：脱水指去除水分，与箭头形态的调整无关。"}], "explanations": {"微调": "正确：微调指小幅调整，使箭头形态经过细微改动以避免宗教联想。", "冷冻": "语义：冷冻是降低温度使物体凝固，与避免宗教联想无关。", "点亮": "语义：点亮指让物体发光，不能用来避免宗教联想。", "脱水": "语义：脱水指去除水分，与箭头形态的调整无关。"}, "sentence_index": 0, "correct_answer": "微调"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家工厂把整条生产线微调了，旧设备全部换成了新的。", "explanation": "这里应该用〈更换〉。微调只做小幅调整，旧设备全部换成新的要用更换。"}, {"text": "地震后，这座小镇微调了街道。", "explanation": "这里应该用〈重建〉。微调只做小幅修改，地震后的整体重新建造要用重建。"}, {"text": "这栋楼微调以后，看起来像新的。", "explanation": "这里应该用〈翻修〉。微调只改动局部细节，让整栋楼焕然一新要用翻修。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3be19b42-deb0-4855-8824-60c9946ebe8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12528, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "微调", "is_correct": true, "explanation": "正确：微调指小幅调整，“识别准确率提高了”说明调整的结果是变好。"}, {"text": "拆掉", "is_correct": false, "explanation": "语义：拆掉会让算法消失，与准确率提高矛盾。"}, {"text": "抄写", "is_correct": false, "explanation": "搭配：抄写用于文字内容，不说“抄写算法”来改变准确率。"}, {"text": "涂色", "is_correct": false, "explanation": "语义：涂色只改变外观，与算法的准确率无关。"}], "explanations": {"微调": "正确：微调指小幅调整，“识别准确率提高了”说明调整的结果是变好。", "拆掉": "语义：拆掉会让算法消失，与准确率提高矛盾。", "抄写": "搭配：抄写用于文字内容，不说“抄写算法”来改变准确率。", "涂色": "语义：涂色只改变外观，与算法的准确率无关。"}, "sentence_index": 6, "correct_answer": "微调"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "技术员微调了机器的故障，机器又能用了。", "explanation": "这里应该用〈修复〉。故障不能靠微调解决，微调是对能正常运转的东西做小幅调整。"}, {"text": "工人微调了整台机器，结果机器被拆成了一堆零件。", "explanation": "这里应该用〈拆解〉。微调只做小幅调整，把整台机器拆成零件要用拆解。"}, {"text": "学校微调了教学楼，增加了教室。", "explanation": "这里应该用〈扩建〉。增加教室需要扩大建筑规模，微调不能增加空间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3be19b42-deb0-4855-8824-60c9946ebe8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (12528, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老板微调了把员工的排班表。", "corrected_sentence": "老板微调了员工的排班表。", "error_description": "错误：动词“微调”后面多用了“把”。正确：“微调了”后面直接接宾语“员工的排班表”，不用“把”；若要用“把”字句，应说“老板把员工的排班表微调了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3be19b42-deb0-4855-8824-60c9946ebe8e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
